## AI 봇 아이템 사용 로직 (bot.js 수정)

봇은 단순 휴리스틱으로 아이템을 사용한다. 타이머 기반 주기 점검 방식.

### 신규 상태 변수

```js
/** 봇 보유 아이템 슬롯 (최대 3). */
const botItemSlots = [null, null, null];
/** 마지막 아이템 사용 시각 (과도한 연발 방지). */
let lastItemUsedAt = 0;
```

### `ITEM_GRANTED` 수신 핸들러

```js
case 'ITEM_GRANTED':
  botItemSlots[msg.slotIndex] = msg.itemId;
  scheduleItemUse();
  break;
```

### `scheduleItemUse()` — 봇 아이템 사용 결정

```js
function scheduleItemUse() {
  // 2~4초 딜레이 후 첫 번째 슬롯 사용 (단순)
  const delay = 2000 + Math.random() * 2000;
  setTimeout(() => {
    const now = Date.now();
    if (now - lastItemUsedAt < 3000) return; // 연발 방지 3초 쿨다운
    const idx = botItemSlots.findIndex((s) => s !== null);
    if (idx === -1) return;
    if (ws.readyState !== WebSocket.OPEN) return;
    ws.send(JSON.stringify({ type: 'ITEM_USED', slotIndex: idx }));
    botItemSlots[idx] = null;
    lastItemUsedAt = now;
  }, delay);
}
```

### 게임 시작/리매치 시 슬롯 초기화

```js
case 'GAME_START':
  clearAllTimers();
  botItemSlots.fill(null);
  lastItemUsedAt = 0;
  break;
```

