## 3. bot.js 수정 내용

### 3-1. import 추가

**위치**: 파일 상단 import 블록, `runEvaluate` import 줄 바로 다음

```js
// 현재 (line 16):
import { runEvaluate } from './wuxia_evaluate.js';
// 아래에 추가:
import { runOrder, isOrderInProgress } from './pixellab_order.js';
```

### 3-2. setMyCommands 배열에 /order 추가

**위치**: `setMyCommands` 배열에 `/refine` 다음 줄에 추가

```js
{ command: 'order', description: 'PixelLab 발주: /order {move_id} — 12프레임 픽셀아트 생성' },
```

### 3-3. /order 커맨드 핸들러 삽입

**위치**: `/refine` 핸들러 닫는 `});` 이후, `/model` 핸들러 이전

패턴: `/gen` 핸들러와 동일 (statusMsg + heartbeat + onProgress 콜백).

```
// /order — PixelLab 발주: /order {move_id}
bot.command('order', async (ctx) => {
  const chatId = ctx.chat.id;

  // 중복 실행 방지
  if (isOrderInProgress(chatId)) {
    return ctx.reply('⏳ 이미 발주가 진행 중입니다. 완료 후 다시 시도하세요.');
  }

  const moveId = ctx.message.text.replace(/^\/order(@\w+)?/i, '').trim();
  if (!moveId) {
    return ctx.reply('💡 사용법: /order {move_id}\n예: /order cheol_san_go_12f');
  }

  const statusMsg = await telegramRetry(() =>
    ctx.reply(`🎨 발주 시작: \`${escapeMd(moveId)}\``, { parse_mode: 'Markdown' })
  );
  addGhostMessage(chatId, statusMsg.message_id);

  // 하트비트 — 30초마다 상태 메시지 갱신
  const startTime = Date.now();
  let lastProgress = '발주 준비 중...';
  const heartbeatTimer = setInterval(async () => {
    const elapsed = formatElapsed(Date.now() - startTime);
    try {
      await ctx.telegram.editMessageText(
        chatId, statusMsg.message_id, undefined,
        `🎨 발주 중... \`${escapeMd(moveId)}\` (${elapsed})\n${escapeMd(lastProgress)}`,
        { parse_mode: 'Markdown' }
      );
    } catch { /* 동일 내용 편집 에러 무시 */ }
  }, HEARTBEAT_INTERVAL);

  try {
    const result = await runOrder(moveId, async (msg) => {
      lastProgress = msg;
      // 진행 상황 즉시 갱신 (Set N/4 변경 시점)
      try {
        await ctx.telegram.editMessageText(
          chatId, statusMsg.message_id, undefined,
          `🎨 발주 중... \`${escapeMd(moveId)}\`\n${escapeMd(msg)}`,
          { parse_mode: 'Markdown' }
        );
      } catch { /* 편집 실패 무시 */ }
    });

    clearInterval(heartbeatTimer);
    removeGhostMessage(chatId, statusMsg.message_id);
    await ctx.deleteMessage(statusMsg.message_id).catch(() => {});

    // 완료 텍스트 전송
    const summary = [
      `*발주 완료* \\— \`${escapeMd(moveId)}\``,
      ``,
      `- 프레임: 12장`,
      `- 저장: \`${escapeMd(result.savedDir)}\``,
    ].join('\n');
    await telegramRetry(() => ctx.reply(summary, { parse_mode: 'Markdown' }));

    // sheet.png 텔레그램 전송 (AC-5)
    await telegramRetry(() =>
      ctx.replyWithPhoto(
        { source: fs.createReadStream(result.sheetPath), filename: `${moveId}_sheet.png` },
        { caption: `${moveId} — 12프레임 시트` }
      )
    );

    // evaluate 자동 연계 시도 (AC-7 — compare.png 없으면 조용히 무시)
    try {
      const evalResult = await runEvaluate(moveId);
      if (evalResult?.summary) {
        const chunks = splitMessage(evalResult.summary);
        for (const chunk of chunks) {
          await telegramRetry(() => ctx.reply(chunk, { parse_mode: 'Markdown' }));
        }
      }
    } catch { /* evaluate 실패 — 조용히 무시 */ }

  } catch (err) {
    clearInterval(heartbeatTimer);
    removeGhostMessage(chatId, statusMsg.message_id);
    await ctx.deleteMessage(statusMsg.message_id).catch(() => {});
    logger.error('order_cmd_error', { chatId, moveId, message: err.message });
    await telegramRetry(() => ctx.reply(`❌ 발주 오류: ${err.message}`));
  }
});
```

