chatId → { sessionId, lastActivity, lastResponse }

// 변경 후
chatId → { sessionId, lastActivity, lastResponse, messages: [] }
```
- `messages` 는 `{role: 'user'|'assistant', text: string}[]` 배열

**3. 의존성 임포트 추가**
- `claude.js` 상단에 `extractTraits`, `mergeExtracted`, `saveProfile`, `loadProfile` 임포트 추가
- 순환 참조 없음: `claude.js` → `extractor.js` → (SDK만 사용), `claude.js` → `persona.js` → (fs만 사용)

**4. `triggerAutoLearn(messages)` 내부 함수 추가**
```
async function triggerAutoLearn(messages) {
  // 1. messages가 비어있으면 조기 반환
  // 2. extractTraits(messages) 실행
  // 3. loadProfile() + mergeExtracted() + saveProfile() 실행
  // 4. 학습 완료 로깅
  // 5. 에러 발생 시 logger.error만 하고 throw하지 않음 (봇 크래시 방지)
}
```

**5. `chat()` 함수 수정**

현재 만료 세션 정리 루프:
```javascript
for (const [id, sess] of sessions) {
  if (now - sess.lastActivity > SESSION_TTL_MS) sessions.delete(id);
}
```

변경 후 — 만료 세션 버퍼 학습 추가:
```javascript
for (const [id, sess] of sessions) {
  if (now - sess.lastActivity > SESSION_TTL_MS) {
    // 버퍼에 메시지가 있으면 비동기 백그라운드 학습
    if (sess.messages?.length > 0) {
      triggerAutoLearn(sess.messages).catch(err =>
        logger.error('session_expire_learn_error', { id, error: err.message })
      );
    }
    sessions.delete(id);
  }
}
```

`chat()` 하단 — 버퍼 누적 및 임계치 체크 추가:
```javascript
// 세션 갱신 후
const sess = sessions.get(key);
if (sess) {
  // 버퍼에 user + assistant 발화 추가
  sess.messages.push({ role: 'user', text: userText });
  sess.messages.push({ role: 'assistant', text: text });

  // 임계치 도달 시 비동기 자동 학습
  if (sess.messages.length >= AUTO_INGEST_THRESHOLD) {
    const snapshot = [...sess.messages];
    sess.messages = []; // 버퍼 선행 초기화 (중복 방지)
    triggerAutoLearn(snapshot).catch(err =>
      logger.error('auto_learn_error', { chatId: key, error: err.message })
    );
  }
}
```

**6. `resetSession()` 수정**
```javascript
export function resetSession(chatId) {
  const key = String(chatId);
  const sess = sessions.get(key);
  // 버퍼에 내용이 있으면 학습 실행 후 세션 삭제
  if (sess?.messages?.length > 0) {
    const snapshot = [...sess.messages];
    triggerAutoLearn(snapshot).catch(err =>
      logger.error('reset_session_learn_error', { chatId: key, error: err.message })
    );
  }
  sessions.delete(key);
}
```

**7. `getSessionBuffer(chatId)` 공개 함수 추가**
```javascript
/**
 * 현재 세션의 대화 버퍼를 반환한다. 세션이 없으면 빈 배열을 반환한다.
 * @param {string|number} chatId
 * @returns {Array<{role: string, text: string}>}
 */
export function getSessionBuffer(chatId) {
  return sessions.get(String(chatId))?.messages ?? [];
}
```

