**5. `/learn` 핸들러 추가 (위치: `/new` 핸들러 하단)**
```javascript
bot.command('learn', async (ctx) => {
  const chatId = ctx.chat.id;
  const buffer = getSessionBuffer(chatId);

  if (buffer.length === 0) {
    return ctx.reply('학습할 대화가 없습니다. /ask 로 먼저 대화를 나눠주세요.');
  }

  await ctx.reply(`${buffer.length / 2}회 교환 분량의 대화를 학습합니다...`);
  await ctx.sendChatAction('typing');

  try {
    const traits = await extractTraits(buffer);
    const profile = loadProfile();
    const merged = mergeExtracted(profile, traits);
    saveProfile(merged);
    await ctx.reply(`학습 완료. 페르소나가 갱신되었습니다 (v${merged.version}). /status 로 확인하세요.`);
  } catch (err) {
    logger.error('learn_error', { chatId, error: err.message });
    await ctx.reply(`학습 중 오류가 발생했습니다: ${err.message}`);
  }
});
```

