const aiFillHint = document.getElementById('ai-fill-hint');
if (aiFillHint && currentAiSlotCount > 0) {
  aiFillHint.textContent = `AI ${currentAiSlotCount}명 대기 중`;
} else if (aiFillHint) {
  aiFillHint.textContent = '';
}
```

#### presence 목록에 AI 슬롯 표시 (`renderPresence` 수정)

`LOBBY_STATE`의 `aiSlots` 배열을 `players` 배열 뒤에 이어 표시한다.

```js
function renderPresence(players, aiSlots) {
  // 기존 실제 플레이어 렌더 후
  for (const ai of (aiSlots || [])) {
    const item = document.createElement('span');
    item.className = 'presence-item ai-slot';
    // 🤖 + AI 닉네임
    ...
    listEl.appendChild(item);
  }
}
```

