**Playwright 스크린샷 로직**

```javascript
/**
 * HTML 파일을 Playwright로 렌더링하여 스크린샷 Buffer를 반환한다.
 * @param {string} htmlPath - 절대 경로의 HTML 파일
 * @returns {Promise<Buffer | null>} PNG 이미지 Buffer, 실패 시 null
 */
async function takeHtmlScreenshot(htmlPath) {
  let browser = null;
  try {
    const { chromium } = await import('playwright');
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1280, height: 900 });
    // file:// 프로토콜로 로컬 HTML 직접 로드
    await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 15000 });
    // 페이지 로드 후 1초 대기 (CSS 애니메이션·폰트 로드 완료)
    await page.waitForTimeout(1000);
    const buffer = await page.screenshot({ type: 'png', fullPage: false });
    return buffer;
  } catch (err) {
    logger.warn('design_screenshot_failed', { htmlPath, message: err.message });
    return null;
  } finally {
    if (browser) await browser.close().catch(() => {});
  }
}
```

