**3. `/design` 명령어 핸들러 추가** (기존 `/sdstatus` 핸들러 아래에 추가)

```javascript
// /design [reset] — HTML 디자인 생성/분석 세션
bot.command('design', async (ctx) => {
  const chatId = ctx.chat.id;
  const arg = ctx.message.text.replace(/^\/design(@\w+)?/i, '').trim();

  // /design reset — 세션 초기화
  if (arg.toLowerCase() === 'reset') {
    resetDesignSession(chatId);
    await ctx.reply('🔄 디자인 세션이 초기화되었습니다.');
    return;
  }

  // 이미 진행 중인 Claude 쿼리가 있으면 안내
  if (processingState.has(chatId)) {
    await ctx.reply('⚠️ 현재 작업 진행 중입니다. 완료 후 /design을 사용해주세요.');
    return;
  }

  const statusMsg = await ctx.reply('🎨 디자인 세션 시작 중...');

  try {
    const result = await startDesignSession(chatId, arg || '새 디자인을 만들고 싶습니다');
    await ctx.deleteMessage(statusMsg.message_id).catch(() => {});
    await ctx.reply(result.questionText || result.reportText);

    if (result.htmlPath) {
      // 분석 플로우: 스크린샷 + 파일 전송
      if (result.screenshotBuffer) {
        await telegramRetry(() => ctx.replyWithPhoto({ source: result.screenshotBuffer, filename: 'design-preview.png' }));
      }
      const filename = path.basename(result.htmlPath);
      await telegramRetry(() => ctx.telegram.sendDocument(chatId, {
        source: fs.createReadStream(result.htmlPath),
        filename,
      }));
    }
  } catch (err) {
    await ctx.deleteMessage(statusMsg.message_id).catch(() => {});
    logger.error('design_cmd_error', { chatId, message: err.message });
    await ctx.reply(`❌ 디자인 오류: ${err.message}`).catch(() => {});
  }
});
```

**4. 일반 텍스트 메시지 핸들러 수정** (기존 `bot.on(message('text'))` 앞에 design 세션 라우팅 삽입)

기존 코드:
```javascript
// 일반 텍스트 메시지 → Claude 호출
bot.on(message('text'), async (ctx) => {
  await handleClaude(ctx, ctx.message.text);
});
```

수정 후:
```javascript
// 일반 텍스트 메시지 → design 세션 활성 시 design으로, 아니면 Claude 호출
bot.on(message('text'), async (ctx) => {
  const chatId = ctx.chat.id;
  const text = ctx.message.text;

  // /esc 미들웨어가 먼저 처리하므로, 여기 도달하면 일반 메시지임
  if (hasDesignSession(chatId)) {
    await handleDesignContinue(ctx, text);
    return;
  }

  await handleClaude(ctx, text);
});
```

**5. 문서(document) 핸들러 수정** — design 세션 활성 중 파일 첨부 처리

기존 일반 파일 처리 블록 (`// 일반 파일 → 임시 경로에 저장 후 Claude에 경로 전달` 아래) 앞에 design 세션 분기 추가:

```javascript
// design 세션 활성 중이면 design으로 라우팅 (이미지·일반 파일 공통)
if (hasDesignSession(chatId)) {
  try {
    const savedPath = await downloadTelegramFile(ctx, fileId, doc.file_name);
    await handleDesignContinue(ctx, caption || '이 파일을 분석하고 개선해줘', savedPath);
  } catch (err) {
    await ctx.reply(`❌ 파일 처리 실패: ${_koError(err.message)}`).catch(() => {});
