## 2. 새로운 데이터 구조 정의

### 2-1. `WorkerState` (bot.js 내 정의)

```js
/**
 * @typedef {Object} WorkerState
 * @property {string}   workerId       - 식별자 ("W-1", "W-2", ...)
 * @property {number}   chatId         - 텔레그램 채팅 ID
 * @property {string}   status         - "RUNNING" | "DONE" | "FAILED" | "CANCELLED"
 * @property {string}   summary        - 작업 요약 (사용자 입력 첫 50자)
 * @property {number}   startTime      - Date.now() 스폰 시각
 * @property {number|null} statusMsgId - 스폰 알림 메시지 ID (삭제용)
 * @property {ReturnType<typeof setInterval>|null} heartbeatTimer
 * @property {string[]} keywords       - 충돌 감지용 프로젝트 키워드 (소문자)
 */
```

### 2-2. 워커 레지스트리 (`workers` Map)

```js
/** chatId 범위 내 워커 카운터. chatId → 마지막 발급 번호 */
const workerCounters = new Map(); // Map<chatId, number>

/**
 * 활성/완료 워커 레지스트리.
 * 키: "chatId:workerId" 복합 키 (예: "12345678:W-1")
 * @type {Map<string, WorkerState>}
 */
const workers = new Map();
```

### 2-3. 충돌 확인 대기 Map

```js
/**
 * 충돌 감지 후 사용자 확인을 기다리는 대기 항목.
 * inline keyboard [진행] / [취소] 버튼 응답을 처리할 때 필요한 컨텍스트를 담는다.
 * 키: "chatId:pendingId" (pendingId는 메시지 ID 등 단일 식별자)
 * @type {Map<string, { input: *, ctx: *, keywords: string[] }>}
 */
const conflictPending = new Map();
```

### 2-4. 워커 키 헬퍼

```js
/** @param {number} chatId @param {string} workerId @returns {string} */
function workerKey(chatId, workerId) { return `${chatId}:${workerId}`; }

/**
 * chatId 범위에서 다음 워커 ID를 발급한다.
 * @param {number} chatId @returns {string} 예: "W-1"
 */
function nextWorkerId(chatId) {
  const n = (workerCounters.get(chatId) || 0) + 1;
  workerCounters.set(chatId, n);
  return `W-${n}`;
}
```

