## 4. claude.js 변경 계획

### 4-1. 세션 키 체계 전환

현재:
```js
const sessions = new Map(); // Map<chatId, { sessionId, expiresAt }>
```

변경 후:
```js
/**
 * 워커별 독립 세션 저장소.
 * 키: "chatId:workerId" 복합 키
 * 하위 호환을 위해 워커 없는 레거시 키도 동시 지원한다.
 */
const sessions = new Map(); // Map<string, { sessionId, expiresAt }>
// 레거시 키: String(chatId) (기존 /btw, /compact 등)
// 워커 키: `${chatId}:${workerId}`
```

키 생성 헬퍼 (claude.js 내부):
```js
function sessionKey(chatId, workerId) {
  return workerId ? `${chatId}:${workerId}` : String(chatId);
}
```

### 4-2. activeQueries 키 체계 전환

현재:
```js
const activeQueries = new Map(); // Map<number(chatId), { abort, close }>
```

변경 후:
```js
const activeQueries = new Map(); // Map<string, { abort, close }>
// 키: `${chatId}:${workerId}` 또는 레거시 String(chatId)
```

### 4-3. runClaude 시그니처 변경

현재:
```js
export async function runClaude(chatId, input, { onActivity, onImage, onDone, onStall } = {}, _isRetry = false)
```

변경 후:
```js
export async function runClaude(chatId, input, { onActivity, onImage, onDone, onStall, workerId } = {}, _isRetry = false)
```

- `workerId`가 있으면 `sessionKey(chatId, workerId)` 로 세션/쿼리 관리
- `workerId`가 없으면 기존 chatId 기반으로 동작 (하위 호환 — btw 내부 호출 경로에 영향 없음)
- `getSession`, `sessions.set`, `activeQueries.set/delete` 모두 `sessionKey`를 사용하도록 변경

### 4-4. cancelWorkerQuery 신규 구현

```js
/**
 * 특정 워커의 쿼리를 취소한다.
 * @param {number} chatId
 * @param {string} workerId - "W-1" 등
 * @returns {boolean} 취소 성공 여부
 */
export function cancelWorkerQuery(chatId, workerId) {
  const key = `${chatId}:${workerId}`;
  const q = activeQueries.get(key);
  if (q) {
    q.abort();
    q.close();
    activeQueries.delete(key);
    return true;
  }
  return false;
}
```

### 4-5. cancelQuery 하위 호환 유지

```js
export function cancelQuery(chatId) {
  // 레거시 chatId 키 먼저 시도
  const legacyKey = String(chatId);
  if (activeQueries.has(legacyKey)) {
    const q = activeQueries.get(legacyKey);
    q.abort(); q.close();
    activeQueries.delete(legacyKey);
    return true;
  }
  // 워커 키 중 해당 chatId 것을 모두 취소
  let cancelled = false;
  for (const [key, q] of activeQueries) {
    if (key.startsWith(`${chatId}:`)) {
      q.abort(); q.close();
      activeQueries.delete(key);
      cancelled = true;
    }
  }
  return cancelled;
}
```

### 4-6. resetSession 변경

```js
export function resetSession(chatId) {
  // 해당 chatId의 모든 세션(레거시 + 워커 전체) 삭제
  for (const key of sessions.keys()) {
    if (key === String(chatId) || key.startsWith(`${chatId}:`)) {
      sessions.delete(key);
    }
  }
}
```

### 4-7. getActiveQueryChatIds 변경

```js
export function getActiveQueryChatIds() {
  const chatIds = new Set();
  for (const key of activeQueries.keys()) {
    const parts = key.split(':');
    chatIds.add(Number(parts[0]));
  }
  return [...chatIds];
}
```

### 4-8. 세션 저장 위치 변경 (runClaude 내)

`msg.type === 'system' && msg.subtype === 'init'` 블록:
```js
// 기존: sessions.set(chatId, ...)
// 변경:
const sKey = sessionKey(chatId, workerId);
sessions.set(sKey, { sessionId: msg.session_id, expiresAt: Date.now() + SESSION_TTL });
```

