### 5-2. 신규 구조 추가

`processingState`/`pendingQueue` 선언 위치(458번째 줄)를 아래로 교체:

```js
/** chatId 범위 내 워커 번호 카운터 @type {Map<number, number>} */
const workerCounters = new Map();

/**
 * 전체 워커 레지스트리. 키: "chatId:workerId"
 * @type {Map<string, WorkerState>}
 */
const workers = new Map();

/**
 * 충돌 감지 후 사용자 확인 대기 항목.
 * 키: "chatId:msgId" (충돌 경고 메시지 ID)
 * @type {Map<string, { input: *, ctx: import('telegraf').Context, keywords: string[] }>}
 */
const conflictPending = new Map();

/** 워커 키 생성 헬퍼 */
function workerKey(chatId, wid) { return `${chatId}:${wid}`; }

/** chatId 범위 워커 ID 발급 */
function nextWorkerId(chatId) {
  const n = (workerCounters.get(chatId) || 0) + 1;
  workerCounters.set(chatId, n);
  return `W-${n}`;
}

/** 해당 chatId의 RUNNING 상태 워커 목록 반환 */
function getRunningWorkers(chatId) {
  const result = [];
  for (const [key, w] of workers) {
    if (w.chatId === chatId && w.status === 'RUNNING') result.push(w);
  }
  return result;
}

/**
 * 입력 텍스트에서 프로젝트명 키워드를 추출한다.
 * 전략: 소문자로 변환 후 3글자 이상 알파벳/숫자/한글 토큰 추출, 일반 단어(관사·전치사 등) 제외
 * @param {string | object} input
 * @returns {string[]}
 */
function extractKeywords(input) {
  const text = typeof input === 'string' ? input : (input.text || '');
  // 토큰화: 영문/숫자는 단어 단위, 한글은 2자 이상 연속
  const tokens = text.toLowerCase().match(/[a-z0-9_-]{3,}|[\uAC00-\uD7A3]{2,}/g) || [];
  const STOP_WORDS = new Set(['the', 'and', 'for', 'with', 'this', 'that', 'from', 'into', 'have', 'will', 'can', 'are', 'not', 'all', 'but', 'its']);
  return tokens.filter(t => !STOP_WORDS.has(t));
}

/**
 * 신규 입력 키워드와 RUNNING 워커의 키워드를 비교하여 충돌 워커를 반환한다.
 * @param {number} chatId
 * @param {string[]} newKeywords
 * @returns {WorkerState[]} 충돌하는 RUNNING 워커 목록
 */
function detectConflict(chatId, newKeywords) {
  const running = getRunningWorkers(chatId);
  return running.filter(w =>
    newKeywords.some(kw => w.keywords.includes(kw))
  );
}

/** DONE/FAILED/CANCELLED 중 1시간 초과 항목 정리 */
function cleanupOldWorkers(chatId) {
  const cutoff = Date.now() - 60 * 60 * 1000;
  for (const [key, w] of workers) {
    if (w.chatId === chatId && w.status !== 'RUNNING' && w.startTime < cutoff) {
      workers.delete(key);
    }
  }
}

/**
 * /workers 응답 텍스트를 생성한다.
 * @param {number} chatId
 * @returns {string}
 */
function formatWorkerList(chatId) {
  const now = Date.now();
  const relevant = [...workers.values()]
    .filter(w => w.chatId === chatId)
    .sort((a, b) => a.startTime - b.startTime);

  if (relevant.length === 0) return '📋 활성 워커가 없습니다.';

  const lines = ['📋 **워커 목록**\n'];
  for (const w of relevant) {
    const elapsed = formatElapsed(now - w.startTime);
    const icon = { RUNNING: '▶️', DONE: '✅', FAILED: '❌', CANCELLED: '⛔' }[w.status] || '?';
    lines.push(`${icon} **${w.workerId}** (${elapsed}) — ${w.summary}`);
  }
  return lines.join('\n');
}

/**
 * 특정 워커를 취소한다.
 * @param {number} chatId
 * @param {string} workerId
 * @returns {boolean}
 */
function cancelWorker(chatId, workerId) {
  const key = workerKey(chatId, workerId);
  const w = workers.get(key);
  if (!w || w.status !== 'RUNNING') return false;
  cancelWorkerQuery(chatId, workerId); // claude.js 임포트
  w.status = 'CANCELLED';
  if (w.heartbeatTimer) clearInterval(w.heartbeatTimer);
  return true;
}
```

### 5-3. handleClaude 재설계

기존 `handleClaude`(714~1057번째 줄)를 두 함수로 분리한다.

#### (A) `handleClaude(ctx, input)` — 게이트웨이 역할

```
handleClaude(ctx, input):
  1. 입력 로깅 (기존 유지)
  2. 최대 워커 수 체크 (RUNNING 워커 >= 10 → 거부 메시지 전송 후 return)
  3. extractKeywords(input) → keywords
  4. detectConflict(chatId, keywords) → conflicts
  5. conflicts 없음 → spawnWorker(ctx, input, keywords) 즉시 호출
  6. conflicts 있음 → 충돌 경고 메시지 + [진행][취소] 인라인 키보드 전송
                   → conflictPending에 등록 (메시지 ID 키)
```

#### (B) `spawnWorker(ctx, input, keywords)` — 실제 워커 실행

```
spawnWorker(ctx, input, keywords):
  1. workerId = nextWorkerId(chatId)
  2. summary = (typeof input === 'string' ? input : input.text || '').slice(0, 50)
  3. WorkerState 생성 → workers에 등록 (status: RUNNING)
  4. 스폰 알림 메시지 전송: "**W-N 시작됨** ▶️\n[summary]..."
     → statusMsgId 저장
  5. 하트비트 타이머 시작 (HEARTBEAT_INTERVAL)
     (기존 하트비트 로직과 동일하되 상태 메시지는 스폰 알림 메시지를 편집)
  6. cleanupOldWorkers(chatId)
  7. runClaude(chatId, input, { ..., workerId }) — Non-blocking (await 없이 .then/.catch)
     ├─ onActivity: 하트비트 상태 텍스트 갱신
     ├─ onImage: sendCapturedImage (기존과 동일)
     ├─ onDone: 하트비트 정리, 스폰 알림 메시지 삭제
     ├─ onStall: 기존 정체 경고 로직 동일
     ├─ .then(result):
     │    w.status = 'DONE'
     │    결과 텍스트 파싱 + 마커 처리 (기존 .then 블록과 동일)
     │    "**W-N 완료** ✅\n[결과]" 형식으로 텍스트 앞에 헤더 추가
     └─ .catch(err):
          w.status = 'FAILED'
          "**W-N 실패** ❌\n[오류]" 전송
```

주의: `spawnWorker`는 `runClaude`를 `.then().catch()` 체인으로 non-blocking 호출한다. `await`를 사용하지 않아야 즉시 응답이 가능하다.

### 5-4. 충돌 감지 인라인 키보드 콜백 처리

```js
// 충돌 [진행] 콜백
bot.action(/^conflict_proceed:(.+)$/, async (ctx) => {
  const pendingKey = ctx.match[1]; // "chatId:msgId"
  const pending = conflictPending.get(pendingKey);
  if (!pending) {
    await ctx.answerCbQuery('이미 처리되었습니다.').catch(() => {});
    return;
  }
  conflictPending.delete(pendingKey);
  await ctx.answerCbQuery('워커를 시작합니다.').catch(() => {});
  await ctx.deleteMessage().catch(() => {});
  await spawnWorker(pending.ctx, pending.input, pending.keywords);
});

// 충돌 [취소] 콜백
bot.action(/^conflict_cancel:(.+)$/, async (ctx) => {
  const pendingKey = ctx.match[1];
  conflictPending.delete(pendingKey);
  await ctx.answerCbQuery('작업을 취소했습니다.').catch(() => {});
  await ctx.deleteMessage().catch(() => {});
});
```

충돌 경고 메시지 전송 예시:
```
⚠️ W-1이 [matgo] 관련 작업 중입니다. 계속할까요?
[진행] [취소]
```
- callback_data: `conflict_proceed:chatId:statusMsgId`, `conflict_cancel:chatId:statusMsgId`

### 5-5. 기존 `cancel_query` 액션 유지 + 변경

기존 `cancel_query` 인라인 버튼은 삭제한다 (워커별 하트비트 메시지에는 취소 버튼을 달지 않는다). 취소는 `/esc W-N` 명령어로만 한다.

단, 하트비트 메시지 편집에 취소 버튼을 유지하고 싶다면 callback_data를 `cancel_worker:chatId:workerId` 패턴으로 변경하면 된다. **V1에서는 취소 버튼 없이 텍스트 전용으로 단순화**한다.

