### 각 파일별 변경사항

#### `minigames/rummikub/game.js`

**신규 함수: `normalizeSetTiles(state, set)`**

```
// 내부 헬퍼 — export 불필요
function normalizeSetTiles(state, set) {
  if (!set || !set.tiles || set.tiles.length === 0) return;
  const resolved = resolveSet(state, set.tiles);
  if (!resolved) return;
  const v = validateSet(resolved);
  if (!v.valid) return; // invalid 세트는 정규화 안 함

  if (v.type === 'run') {
    // 런 정규화:
    //   1) findRunStart로 시작 슬롯 결정
    //   2) start~end 순으로 슬롯 배열 생성
    //   3) 각 슬롯에 해당 숫자 타일 배정, 없는 슬롯에 조커 배정(오름차순)
    const start = findRunStart(resolved);
    if (start < 0) return;
    const end = start + set.tiles.length - 1;

    // 숫자 타일: number → tileId 매핑
    const numByValue = new Map(); // number → tileId
    const jokerIds = [];
    for (let i = 0; i < set.tiles.length; i++) {
      const t = resolved[i];
      if (t.kind === 'num') numByValue.set(t.number, set.tiles[i]);
      else jokerIds.push(set.tiles[i]);
    }

    // 슬롯 순서대로 tiles 재배열
    const ordered = [];
    let jokerIdx = 0;
    for (let v2 = start; v2 <= end; v2++) {
      if (numByValue.has(v2)) {
        ordered.push(numByValue.get(v2));
      } else {
        // 빠진 슬롯 → 조커
        ordered.push(jokerIds[jokerIdx++]);
      }
    }
    set.tiles = ordered;

  } else if (v.type === 'group') {
    // 그룹 정규화:
    //   COLOR_ORDER(red, blue, black, orange) 순 + 조커 마지막
    const COLOR_ORDER = ['red', 'blue', 'black', 'orange'];
    const numTileIds = [];
    const jokerIds = [];
    for (let i = 0; i < set.tiles.length; i++) {
      const t = resolved[i];
      if (t.kind === 'num') numTileIds.push(set.tiles[i]);
      else jokerIds.push(set.tiles[i]);
    }
    numTileIds.sort((aId, bId) => {
      const ta = state.tiles[aId];
      const tb = state.tiles[bId];
      return COLOR_ORDER.indexOf(ta.color) - COLOR_ORDER.indexOf(tb.color);
    });
    set.tiles = [...numTileIds, ...jokerIds];
  }
}
```

**`moveTile` 수정 — 3단계 mutation 완료 후 정규화 호출**

현재 3단계 끝(return `{ ok: true }` 직전)에 아래를 삽입:

```javascript
// 정규화: 영향받은 세트가 valid이면 tiles 배열 재정렬
if (fromSet) normalizeSetTiles(state, fromSet);
if (toSet && toSet !== fromSet) normalizeSetTiles(state, toSet);
```

- `fromSet`은 from.kind === 'set'일 때만 non-null.
- `toSet`은 to.kind === 'set'일 때만 non-null.
- 동일 세트(`toSet === fromSet`) 내 이동이면 한 번만 호출.
- from.kind === 'hand' → toSet만 정규화.
- to.kind === 'hand' → fromSet만 정규화.

**`swapJoker` 수정 — 교환 수행 후 정규화 호출**

현재 `return { ok: true, jokerId: jokerTileId };` 직전에:

```javascript
// SWAP_JOKER: 교환 완료 후 세트 정규화 (jokerIndex는 이미 처리됨)
normalizeSetTiles(state, set);
```

`set`은 swapJoker 내부에서 이미 `const set = state.board.find(...)` 로 참조되어 있음.

**주의: `normalizeSetTiles` 위치**

`resolveSet`, `validateSet`, `findRunStart` 모두 헬퍼 섹션에 정의되어 있으므로 `normalizeSetTiles`는 그 아래 — `moveTile` 함수 앞에 배치한다.

#### `minigames/rummikub/public/js/hand.js`

**`renderHand` 시그니처 변경**

`ctx` 객체에 `sortMode?: 'color' | 'number'` 파라미터 추가 (기본 `'color'`).

**정렬 로직 분기**

현재 고정된 sort 함수를 `sortMode`에 따라 분기:

```javascript
const sortMode = ctx.sortMode || 'color';
tiles.sort((a, b) => {
  // 조커는 항상 마지막
  if (a.kind === 'joker' && b.kind === 'joker') return 0;
  if (a.kind === 'joker') return 1;
  if (b.kind === 'joker') return -1;

  if (sortMode === 'number') {
    // 숫자 오름차순, 동수면 COLOR_ORDER 순
    if (a.number !== b.number) return a.number - b.number;
    return COLOR_ORDER.indexOf(a.color) - COLOR_ORDER.indexOf(b.color);
  } else {
    // 색상순 (기존): COLOR_ORDER → number 오름차순
    const ca = COLOR_ORDER.indexOf(a.color);
    const cb = COLOR_ORDER.indexOf(b.color);
    if (ca !== cb) return ca - cb;
    return a.number - b.number;
  }
});
```

