#### `minigames/rummikub/tests/smoke.test.js`

RUMMI-033~037 케이스를 기존 RUMMI-032 블록 다음에 추가한다.

| 케이스 | 제목 | 검증 내용 |
|---|---|---|
| RUMMI-033 | normalizeSetTiles — 런 정규화 | 서버 state에 `[red5, red3, red4]` 런 세트 배치 후 `moveTile`로 타일 추가(valid 상태 만듦) → set.tiles가 `[red3, red4, red5]` 오름차순으로 재배열됨을 직접 확인 |
| RUMMI-034 | normalizeSetTiles — 조커 런 정규화 | `[red3, red5, joker]` 런 (start=3, joker→slot 4) → 정규화 후 `[red3, joker, red5]` (슬롯 3-4-5 순) |
| RUMMI-035 | normalizeSetTiles — 그룹 정규화 | `[black7, red7, orange7]` 그룹 → 정규화 후 `[red7, black7, orange7]` (COLOR_ORDER: red→black→orange) |
| RUMMI-036 | normalizeSetTiles — invalid 세트는 정규화 안 함 | 2장짜리 미완성 세트는 정규화 후에도 tiles 순서 불변 확인 |
| RUMMI-037 | normalizeSetTiles — SWAP_JOKER 후 정규화 | `swapJoker` 성공 후 세트가 valid이면 정규화 적용됨 확인 |

**테스트 구현 패턴** (game.js에서 `normalizeSetTiles`를 export하지 않으므로 `moveTile`/`swapJoker` 경유로 검증):

```javascript
// RUMMI-033 예시
section('RUMMI-033: normalizeSetTiles — 런 정규화 (moveTile 경유)');
{
  const g = createGame();
  // 타일 추가
  Object.assign(g.tiles, {
    r3: { id:'r3', kind:'num', color:'red', number:3 },
    r4: { id:'r4', kind:'num', color:'red', number:4 },
    r5: { id:'r5', kind:'num', color:'red', number:5 },
  });
  // 보드에 역순 런 [r5, r3, r4] 세팅 (직접 조작)
  g.board = [{ id:'set_run', type:'run', tiles:['r5','r3','r4'] }];
  g.hands.p1 = [];
  // p2 손에 r4 있다고 가정 → 실제로는 valid 상태인 세트를 moveTile로 한번 건드리면 정규화됨
  // 단순화: normalizeSetTiles를 직접 호출하기 위해 손→보드 빈 조작 1회
  // 단, export 없으므로 아래 방식 사용:
  // r3을 한번 손으로 꺼냈다가 다시 세트에 넣어서 valid 세트로 확정 후 정규화 트리거
  g.hands.p1 = ['r3'];
  g.board = [{ id:'set_run', type:'run', tiles:['r5','r4'] }]; // 2장 (invalid)
  g.played.p1 = true;
  g.turnSnapshot = {
    board:[{ id:'set_run', type:'run', tiles:['r5','r4'] }],
    hands:{ p1:['r3'], p2:g.hands.p2.slice() },
    nextSetSeq: g.nextSetSeq,
    jokerReturnedThisTurn: {},
  };
  // 손 r3 → set_run 끝에 삽입 → [r5, r4, r3] → valid 런(3~5)이므로 정규화 → [r3, r4, r5]
  moveTile(g, 'p1', { kind:'hand', tileId:'r3' }, { kind:'set', setId:'set_run' });
  assertEq(g.board[0].tiles, ['r3','r4','r5'], '런 정규화: 슬롯 오름차순');
}
```

