### 각 파일별 변경사항

#### `minigames/yutnori/bot.js` (신규)

rummikub `bot.js`의 구조를 그대로 사용하되, 윷놀이 게임 로직에 맞게 의사결정을 구현한다.

**파일 상단 구조:**

```javascript
/**
 * @fileoverview 윷놀이(Yutnori) AI 봇 — mode=ai 사용자가 들어왔을 때
 * server.js가 child_process로 spawn 한다.
 *
 * 실행:
 *   node bot.js                        → ws://localhost:3004/ws?mode=bot 접속
 *   node bot.js --url ws://...         → 다른 서버 지정 가능
 *
 * 휴리스틱:
 *   - THROW_YUT: 던질 수 있을 때 항상 던진다.
 *   - MOVE_PIECE: 그리디 — 완주(GOAL=99)에 가장 가까운 말을 우선. 동률이면 인덱스 낮은 말.
 *     백도 처리: 출발한 말(cell !== HOME) 중 가장 앞에 있는 말 (HOME으로 가지 않는 말).
 *   - CHOOSE_PATH (corner): 30% 확률 shortcut, 70% outer (테스트 커버리지 확보)
 *   - CHOOSE_PATH (center): 50% 확률 top, 50% bottom
 *   - 잡기 보너스(capturedBonus=true): 즉시 던진다.
 *   - 재대결(GAME_OVER): 0.5초 후 REMATCH 자동 송신.
 */
```

**__isMain 가드 패턴 (rummikub 동일):**

```javascript
const __isMain = (() => {
  try {
    const argv1 = process.argv[1] ? process.argv[1].replace(/\\/g, '/') : '';
    const argvUrl = argv1 ? new URL(`file:///${argv1.replace(/^\/+/, '')}`).href : '';
    return import.meta.url === argvUrl;
  } catch { return true; }
})();
```

**상태 변수:**

```javascript
let myId = null;
let lastActedFor = null;   // 중복 행동 방지 키: `${currentTurn}|${pendingResultsKey}|${awaitingBranchAt}`
let lastState = null;
let pendingActTimer = null;
let actionEpoch = 0;       // [rummikub #9 패턴] 액션 체인 무효화
```

**WS 연결:**

```javascript
// __isMain이 false면 WS 연결 생략 (테스트 import 시)
const ws = __isMain
  ? new WebSocket(BOT_URL)
  : { readyState: 3, send: () => {}, close: () => {}, on: () => {} };
```

**메시지 핸들러 (`ws.on('message', ...)`):**

```
JOINED  → myId = msg.playerId; send(READY)
START   → lastActedFor = null
STATE   → handleState(msg)
YUT_RESULT → 무시 (STATE가 함께 broadcast됨)
GAME_OVER  → setTimeout 500ms 후 send(REMATCH)
OPPONENT_LEFT → ws.close()
ERROR (방이 가득) → ws.close()
ERROR (그 외) → lastActedFor = null; actionEpoch += 1; clearPendingTimer
```

**`handleState(s)` 의사코드:**

```
lastState = s
if (!myId) return
if (s.winner) return                       // 게임 종료 후 상태 무시
if (s.currentTurn !== myId) {
  clearPendingTimer(); actionEpoch += 1; return
}

// 중복 행동 방지 키
// pendingResults 내용 + awaitingBranchAt로 상태 변화 감지
const key = `${s.currentTurn}|${(s.pendingResults||[]).join(',')}|${s.awaitingBranchAt}`
if (key === lastActedFor) return
lastActedFor = key

clearPendingTimer()
const delay = 300 + Math.floor(Math.random() * 500)  // 300~800ms
pendingActTimer = setTimeout(() => {
  pendingActTimer = null
  const cur = lastState
  if (!cur || cur.currentTurn !== myId || cur.winner) return
  actTurn(cur)
}, delay)
```

**`actTurn(s)` 의사코드 — 상태 머신:**

```
actionEpoch += 1
const myEpoch = actionEpoch

// 1) 분기 대기 중이면 CHOOSE_PATH 우선
if (s.awaitingBranchAt !== null) {
  const branchType = s.awaitingBranchType  // 'center' | 'corner'
  let pathChoice
  if (branchType === 'corner') {
    // 30% 확률 지름길, 70% 외곽 (테스트 커버리지)
    pathChoice = Math.random() < 0.3 ? 'shortcut' : 'outer'
  } else {
    // 중앙: 50/50
    pathChoice = Math.random() < 0.5 ? 'top' : 'bottom'
  }
  send({ type: 'CHOOSE_PATH', pathChoice })
  return
}

// 2) pendingResults에 사용 가능한 결과가 있으면 MOVE_PIECE
const pending = s.pendingResults || []
if (pending.length > 0) {
  // 사용할 결과 선택 (첫 번째)
  const useResult = pending[0]
  // 이동할 말 그리디 선택
  const myPlayer = s.players.find(p => p.id === myId)
  const pieceIdx = choosePiece(myPlayer.pieces, useResult)
  if (pieceIdx >= 0) {
    send({ type: 'MOVE_PIECE', pieceIndex: pieceIdx, useResult })
  }
  return
}

// 3) 큐가 비었으면 → THROW 가능 여부 확인
//    capturedBonus=true OR 큐 마지막이 yut/mo (큐 비어있는 상황에서 이 조건은 capturedBonus로만 진입)
//    서버 검증 조건: pendingResults.length===0 && (capturedBonus===true || last===yut/mo)
//    큐가 비어있고 도달한 이 시점은 던지기 가능 상태
send({ type: 'THROW_YUT' })
```

**`choosePiece(pieces, resultName)` 의사코드:**

```
// GOAL=99, HOME=-1
const steps = { backdo:-1, do:1, gae:2, geol:3, yut:4, mo:5 }[resultName]

// 백도: cell !== HOME인 말만 대상
const candidates = pieces.filter((p, i) => {
  if (p.done) return false
  if (resultName === 'backdo' && p.cell === -1) return false
  return true
})
if (candidates.length === 0) return -1

// GOAL(99)에 가장 가까운 말 = cell이 가장 큰 말
// 단, HOME(-1)은 가장 멀리 있는 것으로 취급 (cell 기준 정렬에서 -1 → 낮은 우선순위)
// 이동 후 GOAL에 도달하는 말을 최우선으로 선택
// 단순화: cell 내림차순으로 첫 번째 (GOAL=99는 done=true라 already filtered)
candidates.sort((a, b) => {
  // cell이 높을수록 GOAL에 가까움 (0~28 외곽 + 지름길)
  // HOME(-1)은 출발 전이라 우선순위 낮음
  const ca = a.cell === -1 ? -2 : a.cell
  const cb = b.cell === -1 ? -2 : b.cell
  return cb - ca  // 내림차순
})
return pieces.indexOf(candidates[0])
```

**테스트 export (파일 하단):**

```javascript
export { choosePiece };
```

