##### #5 boardChanged — 시그니처 맵 비교

**A. 턴 전환 시 시그니처 맵 캡처 추가**

`onState` 핸들러 내부, 본인 턴 시작(`state.currentTurn === myId`) 분기에서 `turnStartBoardIds` 갱신 직후에 추가:

```js
// #5: 보드 시그니처 맵 캡처 (setId → tiles.join(','), 비어있지 않은 세트만)
turnStartBoardSig = new Map();
for (const set of state.board || []) {
  if (set.tiles && set.tiles.length > 0) {
    turnStartBoardSig.set(set.id, set.tiles.join(','));
  }
}
```

`turnStartBoardSig`는 `let turnStartBoardSig = new Map();`로 상태 변수 목록에 추가한다 (기존 `let turnStartBoardIds = new Set();` 바로 다음).

**B. boardChanged() 함수 교체**

현재 코드:
```js
function boardChanged(state) {
  const curSetIds = new Set((state.board || []).map((s) => s.id));
  if (freshTileIds.size > 0) return true;
  for (const set of state.board || []) {
    if (set.tiles.length === 0) return true;
  }
  return false;
}
```

교체 코드:
```js
/**
 * 현재 보드가 턴 시작과 비교해 실질적으로 변경되었는지 판단.
 * 빈 세트 존재 또는 비어있지 않은 세트의 타일 구성 변화 여부로 판정.
 * 서버 boardsEqualIgnoringEmpty와 동등한 클라 구현.
 * @param {object} state
 * @returns {boolean}
 */
function boardChanged(state) {
  // freshTileIds가 있으면 분명히 손→보드 이동이 있었다.
  if (freshTileIds.size > 0) return true;
  // 빈 세트가 있으면 NEW_SET을 한 적이 있다.
  for (const set of state.board || []) {
    if (!set.tiles || set.tiles.length === 0) return true;
  }
  // 현재 비어있지 않은 세트의 시그니처와 턴 시작 시 시그니처 비교.
  // 세트 수가 다르면 변경.
  const curNonEmpty = (state.board || []).filter((s) => s.tiles && s.tiles.length > 0);
  if (curNonEmpty.length !== turnStartBoardSig.size) return true;
  for (const set of curNonEmpty) {
    const sig = turnStartBoardSig.get(set.id);
    if (sig === undefined) return true; // 이 턴에 새로 생긴 세트
    if (sig !== set.tiles.join(',')) return true; // 타일 구성 변경
  }
  return false;
}
```

**C. renderActionBar 힌트 — #5와 #1 연동**

`renderActionBar` 호출 직전 (`const freshScore = ...` 다음)에서 `hasChanges`를 사용하는 곳 근처에 힌트 텍스트 로직 추가:

`ui.js`의 `renderActionBar`에 `actionHint` 텍스트 분기가 이미 있다면 그곳에, 없다면 `main.js`의 `renderAll` 내부에서 직접 `els.actionHint.textContent`를 설정한다. 아래는 `main.js renderAll` 내부에서의 처리:

```js
// #5 힌트: 보드 변경 있지만 손 타일 0장인 경우 (재배치만) 경고 힌트.
const isMyTurn = state.currentTurn === myId && state.phase === 'playing';
if (isMyTurn && hasChanges && freshTileIds.size === 0 && !state.played[myId]) {
  // 첫 등판 중 재배치만 한 상태.
  els.actionHint && (els.actionHint.textContent =
    '보드 변경은 손 타일을 1장 이상 내야 적용됩니다 (아니면 롤백 + 더미 1장)');
} else if (isMyTurn && hasChanges && freshTileIds.size === 0 && state.played[myId]) {
  // 등판 후 재배치만 한 상태.
  els.actionHint && (els.actionHint.textContent =
    '재배치만으로는 턴이 종료되지 않습니다. 손 타일을 1장 이상 내야 적용됩니다.');
}
```

이 로직은 `renderActionBar(els, state, myId, freshScore, hasChanges);` 호출 **직전**에 위치시킨다. `renderActionBar`가 actionHint를 덮어쓰지 않는다면 직후도 무방하다. `ui.js`의 `renderActionBar` 구현을 확인하여 겹치지 않도록 한다.

