##### RUMMI-026: #3 뒤섞인 런 점수 정확 계산

```
section('RUMMI-026: #3 뒤섞인 런 점수 순서 독립 계산');
{
  // 런: [red6, joker, red4, red5] (순서: 6, 조커, 4, 5)
  // validateSet → start=4, 빠진 슬롯=[5 or ...] 아니라 [5]? 아니면 joker=5가 될 수 있는지 확인.
  // 실제로 red 4,5,6 + 조커 → start=4, end=7 또는 start=4, end=7?
  // nums=[4,5,6], jokers=1, len=4. startMin=max(1,6-4+1)=3, startMax=min(4,13-4+1)=4.
  // start=3: [3,4,5,6] → 조커=3. score=18.
  // start=4: [4,5,6,7] → 조커=7. score=22 (best).
  // bestStart=4.
  // 빠진 슬롯 = [4..7] - {4,5,6} = {7}. 조커 → 7.
  const g = createGame();
  const tiles = {
    r6: { id: 'r6', kind: 'num', color: 'red', number: 6 },
    r4: { id: 'r4', kind: 'num', color: 'red', number: 4 },
    r5: { id: 'r5', kind: 'num', color: 'red', number: 5 },
    JY: { id: 'JY', kind: 'joker', color: null, number: null },
    hx: { id: 'hx', kind: 'num', color: 'blue', number: 1 }, // 더미용
  };
  Object.assign(g.tiles, tiles);
  // 보드에 [r6, JY, r4, r5] 순서로 저장 — fresh = 전부 (이번 턴 손에서 냄).
  g.board = [{ id: 'set_d', type: 'run', tiles: ['r6', 'JY', 'r4', 'r5'] }];
  g.hands.p1 = [];
  g.played.p1 = false;
  const snap = {
    board: [],
    hands: { p1: ['r6', 'JY', 'r4', 'r5'], p2: [] },
    nextSetSeq: 2,
    jokerReturnedThisTurn: {},
  };
  // computeInitialMeldScore: 이 세트 타일 전부 added.
  // 예상 점수: r6=6, r4=4, r5=5, JY=7 (빠진 슬롯 7). 합 = 22.
  // (인덱스 기반이면: start=4, i=0→4, i=1→5, i=2→6, i=3→7 = 22지만 순서가 달라지면 틀림)
  // 순서 독립 방식: red4=4, red5=5, red6=6, 조커→7. 합=22. 순서 무관.
  // 이 테스트는 순서가 [6,J,4,5]이므로 인덱스 기반이면: 4+0=4, 4+1=5, 4+2=6, 4+3=7 = 22 (우연히 맞음).
  // 더 명확한 케이스: [r5, JY, r4] — start=4, end=6, 빠진슬롯={6}. 조커→6.
  //   인덱스 기반: 4+0=4, 4+1=5, 4+2=6 → r5가 인덱스0이면 4 (틀림, r5=5여야).
  g.board = [{ id: 'set_e', type: 'run', tiles: ['r5', 'JY', 'r4'] }];
  const snap2 = {
    board: [],
    hands: { p1: ['r5', 'JY', 'r4'], p2: [] },
    nextSetSeq: 2,
    jokerReturnedThisTurn: {},
  };
  g.turnSnapshot = snap2;
  // computeInitialMeldScore 직접 호출 (export 필요하면 endTurn 경유로 테스트).
  // 우회: 실제 endTurn으로 점수 검증.
  // 예상: r5=5, JY=6(빠진슬롯), r4=4 → 합=15 ≥ 30 불가. 미달 롤백.
  // 인덱스 기반이면: start=4, i=0→4, i=1→5, i=2→6 → r5(i=0)→4점(오산!), JY(i=1)→5점, r4(i=2)→6점 = 15. 우연히 합은 같다.
  // 더 명확한 케이스: [JY, r4, r5] (조커가 앞), start=4, 빠진슬롯={6}. 조커→6.
  //   인덱스 기반: 4+0=4(조커), 4+1=5, 4+2=6 = 15 (조커=4 오산).
  //   순서 독립: JY=6, r4=4, r5=5 → 15. 이 케이스에서도 합은 같다...
  //   더 명확: [JY, r6, r4] — start=4, end=6, 빠진슬롯={5}. 조커→5.
  //     인덱스 기반: 4+0=4(조커), 4+1=5(r6→6인데 5?), 4+2=6 = 15. 틀림(r6=6이어야).
  //     순서 독립: JY=5, r6=6, r4=4 → 15. 맞음.
  // 위 케이스로 테스트.
  const r6t = { id: 'r6t', kind: 'num', color: 'red', number: 6 };
  const r4t = { id: 'r4t', kind: 'num', color: 'red', number: 4 };
  const JYt = { id: 'JYt', kind: 'joker', color: null, number: null };
  g.tiles.r6t = r6t; g.tiles.r4t = r4t; g.tiles.JYt = JYt;
  g.board = [{ id: 'set_f', type: 'run', tiles: ['JYt', 'r6t', 'r4t'] }];
  // 전체 3장이 added → 점수 합 = 4+5+6 = 15.
  // 단, 개별 타일 점수 검증: JYt→5(빠진슬롯), r6t→6, r4t→4.
  // computeInitialMeldScore 결과는 15이고, 인덱스 기반도 15이므로 구분이 어렵다.
  // 실질 검증: added 타일 중 JYt만 포함된 경우 테스트.
  g.tiles.base1 = { id: 'base1', kind: 'num', color: 'red', number: 4 };
  g.tiles.base2 = { id: 'base2', kind: 'num', color: 'red', number: 6 };
  // 보드에 [base1(r4), JYt(조커), base2(r6)] 존재, JYt만 added.
  g.board = [{ id: 'set_g', type: 'run', tiles: ['base1', 'JYt', 'base2'] }];
  const snap3 = {
    board: [{ id: 'set_g', type: 'run', tiles: ['base1', 'base2'] }], // JYt가 없던 상태
    hands: { p1: ['JYt'], p2: [] },
    nextSetSeq: g.nextSetSeq,
    jokerReturnedThisTurn: {},
  };
  g.hands.p1 = [];
  g.played.p1 = false;
  g.turnSnapshot = snap3;
  // added = JYt만. JYt는 빠진슬롯 {5}에 해당 → 점수 5.
  // 인덱스 기반: start=4, i=1(JYt 위치) → 4+1=5. 맞음(우연).
  // 더 명확하게: [base2(r6), JYt, base1(r4)] 순서로, JYt가 인덱스 1.
  //   인덱스 기반: 4+1=5. 여전히 우연히 맞음.
  // [JYt, base1, base2] 순서: JYt가 인덱스 0.
  //   인덱스 기반: 4+0=4 (틀림, JYt=빠진슬롯5여야).
  //   순서 독립: JYt→5. 맞음.
  g.board = [{ id: 'set_h', type: 'run', tiles: ['JYt', 'base1', 'base2'] }];
  // JYt가 added. 예상 점수: 5 (빠진슬롯 {5}).
  // endTurn을 실행하면 30점 미달이지만 reason='initial_meld_short' + error 안에 현재 점수 포함.
  g.turnSnapshot = {
    board: [{ id: 'set_h', type: 'run', tiles: ['base1', 'base2'] }],
    hands: { p1: ['JYt'], p2: [] },
    nextSetSeq: g.nextSetSeq,
    jokerReturnedThisTurn: {},
  };
  const er026 = endTurn(g, 'p1');
  assertEq(er026.reason, 'initial_meld_short', '#3 초기 등판 미달(점수 부족)');
