##### RUMMI-030: #7 이탈 후 ready 리셋 (WS 통합 테스트)

```
section('RUMMI-030: #7 이탈 후 ready 리셋 — 재접속 시 자동 시작 방지');
// WS 서버가 필요한 통합 테스트 — 기존 RUMMI-010 서버 패턴 사용.
await (async () => {
  const app = createApp({});
  const server = http.createServer(app.handleHttp);
  server.on('upgrade', app.handleUpgrade);
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;

  const connect = () => new Promise((res) => {
    const ws = new WebSocket(`ws://127.0.0.1:${port}/ws`);
    ws.on('open', () => {
      ws.send(JSON.stringify({ type: 'JOIN' }));
      ws.send(JSON.stringify({ type: 'READY' }));
      res(ws);
    });
  });

  const ws1 = await connect();
  const ws2 = await connect();

  // 잠시 대기 후 ws1이 READY가 됐는지 확인 (양쪽 READY → START).
  await new Promise((r) => setTimeout(r, 300));

  // ws1 이탈.
  ws1.close();
  await new Promise((r) => setTimeout(r, 200));

  // ws3 새 접속 + READY → ws2도 READY가 리셋됐으면 자동 시작 X.
  let autoStarted = false;
  const ws3 = await new Promise((res) => {
    const ws = new WebSocket(`ws://127.0.0.1:${port}/ws`);
    ws.on('message', (data) => {
      const msg = JSON.parse(data.toString());
      if (msg.type === 'START') autoStarted = true;
    });
    ws.on('open', () => {
      ws.send(JSON.stringify({ type: 'JOIN' }));
      ws.send(JSON.stringify({ type: 'READY' }));
      res(ws);
    });
  });

  await new Promise((r) => setTimeout(r, 300));
  assertEq(autoStarted, false, '#7 이탈 후 ws3만 READY → 자동 시작 X');

  ws2.close(); ws3.close();
  await new Promise((r) => server.close(r));
})();
```

