#### `public/js/board.js`

**FIX-3: 칸 24/25 좌표 추가**

```js
/**
 * centerExitB 경로 (중앙 → 좌하): 24, 25.
 * 24, 25는 중앙(23)과 좌하(0) 사이의 1/3, 2/3 지점.
 */
function buildCenterExitB() {
  const start = CENTER_COORD;  // 중앙
  const end = OUTER_COORDS[0]; // 좌하(0)
  const list = [];
  for (let i = 1; i <= 2; i++) {
    const t = i / 3;
    list.push({
      x: start.x + (end.x - start.x) * t,
      y: start.y + (end.y - start.y) * t,
      big: false,
    });
  }
  return list;
}

export const CENTER_EXIT_B = buildCenterExitB();
```

