**4. `GAME_START` 메시지 핸들러에 초기화 추가:**
```js
case 'GAME_START':
  hideModal();
  selectedSlot = null;
  guessHistory = [];
  guessHistoryListEl.innerHTML = '';
  break;
```

**5. `renderState()` 내에 `renderLastGuess()` 호출 대신 `renderGuessHistory()` 호출:**
- `renderLastGuess(s.lastGuess)` 줄을 다음 두 줄로 교체:
  ```js
  accumulateGuess(s.lastGuess);
  renderGuessHistory();
  ```

**6. `accumulateGuess(lg)` 함수 추가:**
- `s.lastGuess`가 null이거나 `guessHistory` 마지막 항목과 동일(from+slot+value 비교)하면 push 하지 않는다.
- 새 항목이면 `guessHistory.unshift(...)` (최신을 맨 앞에 삽입).

```js
/**
 * lastGuess가 신규 항목이면 guessHistory 맨 앞에 추가한다.
 * 동일한 항목(from+slot+value 일치)은 중복 추가하지 않는다.
 * @param {object|null} lg
 */
function accumulateGuess(lg) {
  if (!lg) return;
  if (guessHistory.length > 0) {
    const last = guessHistory[0];
    if (last.from === lg.from && last.slot === lg.slot && last.value === lg.value) return;
  }
  guessHistory.unshift(lg);
}
```

**7. `renderGuessHistory()` 함수 추가:**
```js
/**
 * guessHistory 배열을 우 패널 목록으로 렌더링한다.
 */
function renderGuessHistory() {
  guessHistoryListEl.innerHTML = '';
  guessHistory.forEach((lg) => {
    const who = lg.from === me ? '나' : '상대';
    const slotLabel = `${lg.slot + 1}번째`;
    const resultClass = lg.correct ? 'result-correct' : 'result-wrong';
    const resultSymbol = lg.correct ? '✓' : '✗';

    const el = document.createElement('div');
    el.className = 'guess-entry';
    el.innerHTML = `
      <span class="who">${who}</span>
      <span>${slotLabel} → <strong>${lg.value}</strong></span>
      <span class="${resultClass}">${resultSymbol}</span>
    `;
    guessHistoryListEl.appendChild(el);
  });
}
```

**8. `renderMemoBoard(s)` 함수 추가 + `renderState()` 내에서 호출:**
```js
/**
 * 숫자 메모판 렌더링.
 * revealed 카드(자기 + 상대)를 dim 처리한다.
 * @param {object} s - STATE 스냅샷
 */
function renderMemoBoard(s) {
  // 공개된 {color, value} 집합 구성
  const usedSet = new Set();
  [...s.oppHand, ...s.yourHand].forEach((card) => {
    if (card.revealed) usedSet.add(`${card.color}-${card.value}`);
  });

  ['black', 'white'].forEach((color) => {
    const containerEl = color === 'black' ? memoBlackEl : memoWhiteEl;
    containerEl.innerHTML = '';
    for (let v = 0; v <= 11; v++) {
      const tile = document.createElement('div');
      tile.className = `memo-tile ${color}-tile`;
      tile.textContent = String(v);
      if (usedSet.has(`${color}-${v}`)) tile.classList.add('used');
      containerEl.appendChild(tile);
    }
  });
}
```

`renderState()` 내 `renderLastGuess(s.lastGuess)` 줄을 다음 세 줄로 교체:
```js
renderMemoBoard(s);
accumulateGuess(s.lastGuess);
renderGuessHistory();
```

**9. 기존 `renderLastGuess()` 함수 전체 제거** (`#last-guess` DOM 참조 및 함수 본체 삭제).

**10. NEW_GAME 수신 처리 — `STATE` 메시지가 새 게임 시작을 알리므로 별도 핸들러는 불필요. 단, `GAME_START` 핸들러에서 이미 `guessHistory` 초기화하므로 충분.**
- 만약 서버가 NEW_GAME에 대해 `GAME_START` 메시지를 내려주는지 확인 필요: `server.js`에서 `GAME_START` 브로드캐스트가 확인되면 현재 핸들러로 충분. 확인되지 않을 경우 `STATE` 수신 시 `deckCount === 24`(초기 덱 크기)이고 `guessHistory.length > 0`이면 초기화 로직 추가. (Coder가 server.js를 읽어 확인 후 판단)

### 의존성
- 신규 패키지 없음. 순수 HTML/CSS/JS 변경만.

