### 각 파일별 변경사항

---

#### `launcher/server.js`

**1. lobbyPhase 변수 제거**

현재 코드:
```js
let lobbyPhase = 'lobby';
let currentMode = null;
```

변경 후:
- `lobbyPhase` 변수 완전 제거
- `currentMode`는 유지 (1/2 → ai, 2/2 → human 결정에 계속 사용)

**2. votes Map 추가** (모듈 수준 상태에 추가)

```js
/**
 * 게임별 투표 현황.
 * key: gameId (string), value: Set of playerId (string, 'p1'|'p2')
 * @type {Map<string, Set<string>>}
 */
const votes = new Map();
```

**3. sendLobbyStateTo 함수 수정** — votes 포함

현재:
```js
sendJson(ws, {
  type: 'LOBBY_STATE',
  count: clients.size,
  role: meta.role,
  hostId: hostEntry ? hostEntry.id : null,
  phase: lobbyPhase,
  mode: currentMode,
});
```

변경 후:
```js
// votes를 { gameId: count } 형태로 직렬화
const votesSnapshot = {};
for (const [gameId, playerSet] of votes) {
  votesSnapshot[gameId] = playerSet.size;
}
sendJson(ws, {
  type: 'LOBBY_STATE',
  count: clients.size,
  role: meta.role,
  hostId: hostEntry ? hostEntry.id : null,
  mode: currentMode,
  votes: votesSnapshot,
});
```

**4. handleMessage 수정**

- `START` case 제거 (또는 하위 호환으로 무시 처리)
- `PICK_GAME` case: `lobbyPhase !== 'game-select'` 가드 제거, `count >= 2` 또는 `count === 1` (AI) 조건으로 대체

```js
case 'PICK_GAME': {
  if (meta.role !== 'host') return;
  const gameId = String(msg.gameId || '');
  const game = gamesMap.get(gameId);
  if (!game) {
    console.warn(`[launcher] PICK_GAME 알 수 없는 gameId: ${gameId}`);
    return;
  }
  // 인원수에 따라 모드 결정 (pick 시점에 확정)
  currentMode = clients.size === 1 ? 'ai' : 'human';
  const redirectPath = `/${gameId}/`;
  console.log(`[launcher] PICK_GAME → gameId=${gameId}, mode=${currentMode}`);
  broadcast({
    type: 'REDIRECT',
    gameId,
    path: redirectPath,
    mode: currentMode,
  });
  break;
}

case 'VOTE_GAME': {
  const gameId = String(msg.gameId || '');
  if (!gamesMap.has(gameId)) return;
  if (!votes.has(gameId)) votes.set(gameId, new Set());
  const voterSet = votes.get(gameId);
  // toggle: 이미 투표했으면 취소, 아니면 추가
  if (voterSet.has(meta.id)) {
    voterSet.delete(meta.id);
  } else {
    voterSet.add(meta.id);
  }
  console.log(`[launcher] VOTE_GAME: ${meta.id} → ${gameId}, count=${voterSet.size}`);
  broadcastLobbyState();
  break;
}
```

**5. disconnect 핸들러 수정** — votes 리셋 포함

모두 나갈 때(`clients.size === 0`) votes도 초기화:
```js
if (clients.size === 0) {
  currentMode = null;
  nextIdSeq = 1;
  votes.clear();
  return;
}
```

호스트 나갈 때도 votes 초기화:
```js
if (departed.role === 'host') {
  broadcast({ type: 'RESET' });
  currentMode = null;
  votes.clear();
  reassignHost();
}
```

**6. POST /lobby/return 엔드포인트 추가** (HTTP 서버 핸들러에 추가)

```js
// HTTP 핸들러 최상단에 추가
if (req.method === 'POST' && urlPath === '/lobby/return') {
  res.writeHead(204);
  res.end();
  // 로비 상태 리셋
  currentMode = null;
  votes.clear();
  broadcast({ type: 'RETURN_LOBBY' });
  console.log('[launcher] POST /lobby/return → RETURN_LOBBY broadcast');
  return;
}
```

**7. fileoverview 및 로비 흐름 주석 갱신** — phase/start 설명 제거, 단순화된 흐름으로 업데이트

