**1. 상수 및 상태 변수 정리**

제거: `SELECT_VIEW_ID`, `cardsRendered`, `currentPhase`

추가:
```js
/** @type {{ [gameId: string]: number }} 서버에서 수신한 투표 현황 */
let currentVotes = {};

/**
 * 로비가 활성화된 상태 (2/2 + 호스트)인지 여부.
 * 이 플래그가 true일 때만 카드 클릭이 가능하다.
 * @type {boolean}
 */
let cardClickEnabled = false;
```

**2. createCard 함수 수정**

- 👍 버튼 요소 추가 (`game-card-vote` 클래스)
- 기존 `pick` 핸들러는 유지 (내부에서 `cardClickEnabled && myRole === 'host'` 체크)

```js
// 👍 투표 버튼 (카드 하단)
const voteBtn = document.createElement('button');
voteBtn.className = 'game-card-vote';
voteBtn.type = 'button';
voteBtn.dataset.gameId = game.id;
voteBtn.setAttribute('aria-label', `${game.name} 추천`);
voteBtn.innerHTML = '👍 <span class="vote-count" id="vote-count-' + game.id + '">0</span>';
body.appendChild(voteBtn);

// 👍 투표 이벤트 — 호스트/게스트 모두 가능, 항상 활성
voteBtn.addEventListener('click', (event) => {
  event.stopPropagation(); // 카드 pick 이벤트 방지
  if (!ws || ws.readyState !== WebSocket.OPEN) return;
  ws.send(JSON.stringify({ type: 'VOTE_GAME', gameId: game.id }));
});
```

- 기존 `pick` 함수 수정:
```js
const pick = (event) => {
  if (event) event.stopPropagation();
  if (!cardClickEnabled) return;  // 1/2 상태 또는 비활성
  if (myRole !== 'host') return;
  if (currentMode === 'ai' && game.botAvailable === false) return;
  if (!ws || ws.readyState !== WebSocket.OPEN) return;
  ws.send(JSON.stringify({ type: 'PICK_GAME', gameId: game.id }));
};
```

**3. transitionTo 함수 제거** — 단일 뷰이므로 불필요. `updateLobbyUI`가 모든 상태 갱신을 담당.

**4. updateLobbyUI 함수 재작성**

```js
function updateLobbyUI(msg) {
  const { count, role, mode, votes } = msg;
  myRole = role;
  currentMode = mode;
  currentVotes = votes || {};

  // 인원 카운트 표시
  const countEl = document.getElementById('player-count');
  if (countEl) countEl.textContent = `${count}/2`;

  // 역할 표시
  const roleEl = document.getElementById('player-role');
  if (roleEl) roleEl.textContent = role === 'host' ? '호스트' : '게스트';

  // 힌트 텍스트
  const hintEl = document.getElementById('lobby-hint');
  if (hintEl) {
    if (count === 1) {
      hintEl.textContent = role === 'host'
        ? '혼자 플레이 가능 (AI 대전) — 또는 친구를 기다리세요'
        : '호스트가 종목을 선택 중...';
    } else {
      hintEl.textContent = role === 'host'
        ? '친구가 들어왔습니다! 종목을 선택하세요'
        : '호스트가 종목을 선택 중...';
    }
  }

  // 게스트 대기 안내
  const guestWait = document.getElementById('guest-waiting');
  if (guestWait) guestWait.hidden = role === 'host';

  // cardClickEnabled: 호스트이면 항상 클릭 가능 (1/2=ai, 2/2=human 자동 결정)
  cardClickEnabled = role === 'host';

  // 그리드 비활성 CSS 클래스 갱신
  const grid = document.getElementById(GRID_EL_ID);
  if (grid) {
    // 게스트이면 항상 guest-mode
    grid.classList.toggle('guest-mode', role === 'guest');
    // 1/2 호스트: 카드는 클릭 가능하지만 AI 모드 (no-bot 비활성)
    // count에 따른 ai-mode/human-mode 배지 (선택 사항, mode badge 요소가 없으므로 생략 또는 별도 hint)
  }

  // 투표 배지 갱신
  updateVoteBadges();
}
```

**5. updateVoteBadges 함수 추가**

```js
/**
 * 모든 카드의 👍 카운트를 현재 currentVotes로 갱신한다.
 */
function updateVoteBadges() {
  for (const game of gamesCache) {
    const countEl = document.getElementById(`vote-count-${game.id}`);
    if (countEl) {
      const count = currentVotes[game.id] || 0;
      countEl.textContent = count;
    }
    // voteBtn 활성화 상태 표시 (내가 투표했는지는 서버가 알려주지 않으므로 로컬 추적 필요 — 심플하게 count > 0이면 강조)
  }
}
```

**6. onMessage 핸들러 수정**

```js
case 'LOBBY_STATE':
  updateLobbyUI(msg);
  break;
case 'PHASE':          // 하위 호환 — 무시 (서버에서 더 이상 송신 안 함)
  break;
case 'RETURN_LOBBY':   // POST /lobby/return 결과로 서버가 broadcast
  // 로컬 상태 초기화 후 로비로
  currentVotes = {};
  cardClickEnabled = false;
  location.href = '/';
  break;
case 'REDIRECT':
  handleRedirect(msg);
  break;
case 'FULL':
  showFullAlert();
  break;
case 'RESET':
  resetToLobby();
  break;
```

