**5. 게임 전용 추가 스타일** (시안에 없는 것만 병합):

```css
/* ── 카드 애니메이션 (기존 유지) ──────────────────────────── */
@keyframes card-appear { ... }      /* 기존 그대로 */
.card.anim-appear { ... }
@keyframes card-fly-in-captured { ... }
.card.anim-fly-in-captured { ... }
.card.flying-card, .flying-card { position: fixed !important; ... }  /* 기존 그대로 */
@keyframes card-match-glow { ... }
.card.anim-match-glow { ... }
.action-toast { ... }               /* 기존 그대로 */
@keyframes action-toast-show { ... }

/* ── 카드 인터랙션 ────────────────────────────────────────── */
.card.clickable { cursor: pointer; transition: transform 0.12s, box-shadow 0.12s; }
/* my-hand-zone hover는 시안 스타일(.my-hand-zone .card:hover)로 통일 */
.card.selectable-floor {
  outline: 3px solid var(--gold-hi);
  outline-offset: -3px; cursor: pointer;
}
.card.selectable-floor:hover { transform: scale(1.06); }
.card.ppeok-mark::after {
  content: '뻑'; position: absolute; bottom: 2px; left: 4px;
  font-size: 9px; background: rgba(255,0,0,0.7); padding: 1px 4px; border-radius: 2px;
}

/* ── 모달 (스타일 v8 톤으로 교체, 구조 ID 유지) ──────────── */
.modal { position: fixed; inset: 0; background: rgba(0,0,0,0.75);
         display: flex; align-items: center; justify-content: center; z-index: 100; }
.modal.hidden { display: none; }
.modal-inner {
  background: var(--bg-panel); padding: 24px 32px; border-radius: 12px;
  max-width: 480px; text-align: center;
  border: 2px solid var(--gold); color: #ece6d6;
