  myMoneyEl.textContent  = formatMoney(s.money[me]) + '원';
  oppMoneyEl.textContent = formatMoney(s.money[oppId]) + '원';

  // perPoint — activeElement 체크는 유지
  if (document.activeElement !== perPointEl) {
    perPointEl.value = s.perPoint;
  }

  // 점수 (기존 로직 유지)
  myScoreEl.textContent  = String(s.score[me] || 0);
  oppScoreEl.textContent = String(s.score[oppId] || 0);

  // 더미 카운트 (기존 유지)
  deckCountBigEl.textContent = String(s.deckCount);

  // 손패 장수 extras
  myExtraEl.textContent  = `손 ${s.yourHand.length}장`;
  oppExtraEl.textContent = `손 ${s.oppHandCount}장`;

  // 배지 (고/흔들기 등)
  updateProfileBadges(myBadgesEl,  me, s);
  updateProfileBadges(oppBadgesEl, oppId, s);

  // 배너 상태 텍스트 + warning 클래스 (기존 turnEl 로직을 bannerStatus로 이전)
  const turnText = deriveTurnText(s);
  bannerStatusEl.textContent = turnText;
  bannerMultiEl.textContent  = deriveBannerMultiplier(s);
  floorZoneEl.classList.toggle('warning', s.score[me] >= 7 || s.score[oppId] >= 7);

  // 기존 renderOppHand, renderMyHand, renderFloor, renderCaptured 호출 (함수명 유지)
  renderOppHand(s);
  renderMyHand(s);
  renderFloor(s);
  renderCaptured('p1', s);
  renderCaptured('p2', s);
  updateActionPanel(s);

  // last-action 제거로 renderLastAction 호출 삭제 (action-display로 통합)
  resolvePendingFlies();
}
