신설 헬퍼 함수:
```js
/** 배너 multiplier 문자열 도출 (고 횟수 or 흔들기 배수) */
function deriveBannerMultiplier(s) {
  const goCount = (s.goCount[me] || 0) + (s.goCount[oppId] || 0);
  const shaking = s.shaking[me] || s.shaking[oppId];
  if (goCount > 0 && shaking) return `${goCount}고 · ×2`;
  if (goCount > 0) return `${goCount}고`;
  if (shaking) return '×2';
  return '';
}

/** 배지 갱신 (흔들기, 고) */
function updateProfileBadges(el, pid, s) {
  el.innerHTML = '';
  if (s.shaking && s.shaking[pid]) {
    const b = document.createElement('span');
    b.className = 'profile-badge';
    b.textContent = '흔들기 ×2';
    el.appendChild(b);
  }
  if (s.goCount && s.goCount[pid] > 0) {
    const b = document.createElement('span');
    b.className = 'profile-badge red';
    b.textContent = `${s.goCount[pid]}고`;
    el.appendChild(b);
  }
}
```

**3. renderFloor() 수정 — 허니콤 고정 슬롯 방식으로 교체**

기존 flex 휘저음(tilt + offset CSS 변수) 방식을 FLOOR_SLOTS 절대위치 방식으로 교체한다.

```js
// 시안의 FLOOR_SLOTS 상수 추가 (client.js 상단)
const FLOOR_SLOTS = (() => {
  const R = 150;
  const h = R * Math.sqrt(3) / 2;
  return [
    { dx:  R,       dy:  0 },
    { dx:  R / 2,   dy: -h },
    { dx: -R / 2,   dy: -h },
    { dx: -R,       dy:  0 },
    { dx: -R / 2,   dy:  h },
    { dx:  R / 2,   dy:  h },
    { dx:  2 * R,   dy:  0 },
    { dx: -2 * R,   dy:  0 },
    { dx:  2 * R,   dy: -h },
    { dx:  2 * R,   dy:  h },
    { dx: -2 * R,   dy: -h },
    { dx: -2 * R,   dy:  h },
  ];
})();

function applyFloorSlot(el, idx) {
  const slot = FLOOR_SLOTS[idx % FLOOR_SLOTS.length];
  el.style.left      = `calc(50% + ${slot.dx}px)`;
  el.style.top       = `calc(50% + ${slot.dy}px)`;
  el.style.transform = 'translate(-50%, -50%)';
  el.style.zIndex    = '1';
}

function renderFloor(s) {
  // deck-card, floor-mission 이외 카드 제거
  Array.from(floorCardsEl.children).forEach((ch) => {
    if (!ch.classList.contains('deck-card')
     && !ch.classList.contains('floor-mission')
     && !ch.id === 'go-stop-overlay') {
      ch.remove();
    }
  });
  const deckEl = floorCardsEl.querySelector('.deck-card');
  const isChoice = s.turn === me && s.phase === 'awaiting_floor_choice' && s.pendingChoice;
  const choiceIds = isChoice ? new Set(s.pendingChoice.candidates.map((c) => c.id)) : new Set();

  s.floor.forEach((card, idx) => {
    const isPpeok = !!s.ppeokFlags[card.month];
    const anim = newFloorIds.has(card.id) ? 'appear' : null;
    const el = makeCardEl(card, { ppeok: isPpeok, anim });
    applyFloorSlot(el, idx);
    if (choiceIds.has(card.id)) {
      el.classList.add('selectable-floor');
      el.addEventListener('click', () => sendChooseFloor(card.id));
    }
    floorCardsEl.insertBefore(el, deckEl);
  });
}
```

주의: `floorCardsEl.innerHTML = ''` 방식 대신 개별 remove를 사용해 deck-card·floor-mission을 보존한다.

**4. renderCaptured() 수정 — card-stack fan 방식으로 교체**

```js
function renderCaptured(pid, s) {
  const zoneEl = (pid === me)
    ? document.getElementById('my-captured-zone')
    : document.getElementById('opp-captured-zone');
  const cards  = s.captured[pid] || [];
  const newIds = (pid === 'p1') ? newCapIds.p1 : newCapIds.p2;

  const groups = { gwang: [], kkeut: [], tti: [], pi: [] };
  for (const c of cards) if (groups[c.type]) groups[c.type].push(c);

  const thresholds = { gwang: 3, kkeut: 5, tti: 5, pi: 10 };
  const typeLabels = { gwang: '광', kkeut: '끗', tti: '띠', pi: '피' };

  for (const type of ['gwang', 'kkeut', 'tti', 'pi']) {
    const count   = groups[type].length;
    const reached = count >= thresholds[type];

    // captured-summary 갱신
    const sumRow = zoneEl.querySelector(`.captured-summary .cs-row[data-type="${type}"]`);
    if (sumRow) {
      sumRow.textContent = `${typeLabels[type]} ${count}`;
      sumRow.classList.toggle('empty', count === 0);
      sumRow.classList.toggle('scored', reached);
    }

    // card-stack 갱신
    const groupEl = zoneEl.querySelector(`.captured-group[data-type="${type}"]`);
    if (!groupEl) continue;
    const stack = groupEl.querySelector('.card-stack');
    stack.innerHTML = '';
    for (const c of groups[type]) {
      const anim = newIds.has(c.id) ? 'fly-in-captured' : null;
      stack.appendChild(makeCardEl(c, { anim }));
    }
    groupEl.classList.toggle('scored', reached);
  }
}
```

