  { "id": "davinci-code",   "name": "다빈치 코드",   "port": 3002, "color": "#7B68EE", "emoji": "🎴", ... },
  { "id": "matgo",          "name": "맞고",           "port": 3003, "color": "#2E8B57", "emoji": "🃏", ... },
  { "id": "yutnori",        "name": "윷놀이",         "port": 3004, "color": "#D4A017", "emoji": "🎲", ... },
  { "id": "tetris-battle",  "name": "테트리스 배틀",  "port": 3005, "color": "#5DADE2", "emoji": "🟦", ... }
