#### game별 server.js — 공통 변환 패턴

아래 패턴을 codenames-duet / davinci-code / matgo에 적용한다. (yutnori/tetris-battle은 express 사용으로 별도 처리)

```js
// ── createApp 패턴 ──────────────────────────────────────────────

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PUBLIC_DIR = path.join(__dirname, 'public');

/** MIME 매핑 (기존 그대로) */
const MIME = { ... };

/**
 * 게임 앱 인스턴스 생성.
 * launcher가 import하여 라우터에 등록할 때 호출한다.
 * @returns {{ handleHttp: Function, handleUpgrade: Function }}
 */
export function createApp() {
  // ── 게임 상태 (closure로 격리) ──────────────────
  let players = [];
  let game = null;
  // ... 기존 상태 변수들

  // ── WSS (noServer) ────────────────────────────
  const wss = new WebSocketServer({ noServer: true });

  // ── 기존 wss.on('connection', ...) 로직 그대로 유지 ──
  wss.on('connection', (ws) => { /* 기존 로직 그대로 */ });

  // ── HTTP 핸들러 ───────────────────────────────
  function handleHttp(req, res) {
    // req.url은 launcher가 prefix를 제거한 뒤 전달함 (예: '/index.html')
    const urlPath = req.url === '/' || req.url === '' ? '/index.html' : (req.url.split('?')[0] || '/index.html');
    const safePath = path.normalize(urlPath).replace(/^([\\/])+/, '');
    const fullPath = path.join(PUBLIC_DIR, safePath);
    if (!fullPath.startsWith(PUBLIC_DIR)) {
      res.writeHead(403); res.end('Forbidden'); return;
    }
    fs.readFile(fullPath, (err, data) => {
      if (err) { res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Not found'); return; }
      const ext = path.extname(fullPath).toLowerCase();
      res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
      res.end(data);
    });
  }

  // ── WS upgrade 핸들러 ─────────────────────────
  function handleUpgrade(req, socket, head) {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  }

  return { handleHttp, handleUpgrade };
}

// ── standalone 실행 지원 ──────────────────────────────────────
// `node server.js`로 단독 실행 시에는 기존과 동일하게 동작
if (import.meta.url === `file://${process.argv[1].replace(/\\/g, '/')}`) {
  const app = createApp();
  const srv = http.createServer(app.handleHttp);
  srv.on('upgrade', (req, socket, head) => app.handleUpgrade(req, socket, head));
  // 포트 설정 및 listen (기존 코드 재사용)
  srv.listen(PORT, '0.0.0.0', () => { printBanner(PORT, getLanAddresses()); });
}
```

