#### `minigames/yutnori/server.js` — express 기반 변환

yutnori는 express를 사용하므로 `handleHttp`를 express의 `app` 미들웨어를 감싸는 방식으로 구현한다.

```js
export function createApp() {
  // ── 게임 상태 (closure로 격리) ──────────────────
  let players = [];
  let game = { ... };
  // ... 기존 상태 함수/변수 전부 closure 안으로

  // ── express 앱 (정적 서빙) ────────────────────
  const expressApp = express();
  expressApp.use(express.static(path.join(__dirname, 'public')));

  // ── WSS (noServer) ────────────────────────────
  const wss = new WebSocketServer({ noServer: true });
  wss.on('connection', (ws) => { /* 기존 로직 그대로 */ });

  function handleHttp(req, res) {
    expressApp(req, res, () => {
      // express가 처리 못한 경우 (404)
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not found');
    });
  }

  function handleUpgrade(req, socket, head) {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  }

  return { handleHttp, handleUpgrade };
}
```

yutnori의 `throwYutSticks()`, `computeNextCell()` 같은 export 함수들은 launcher가 import하지 않으므로 그대로 둬도 무방하다. 단, `YUTNORI_NO_LISTEN` 환경변수 처리 블록과 포트 폴백 로직은 standalone 실행 시만 동작하도록 조건부 처리한다.

