#### `minigames/launcher/server.js` — 통합 라우터

기존 코드에서 `server`, `wss` 부분을 전면 재작성한다. 로비 상태 머신(clients, lobbyPhase, currentMode 등) 및 유틸 함수(sendJson, broadcast 등)는 그대로 유지한다.

**변경 1: 게임 앱 import**
```js
import { createApp as createCodenamesApp } from '../codenames-duet/server.js';
import { createApp as createDavinciApp }   from '../davinci-code/server.js';
import { createApp as createMatgoApp }     from '../matgo/server.js';
import { createApp as createYutnoriApp }   from '../yutnori/server.js';
import { createApp as createTetrisApp }    from '../tetris-battle/server.js';
```

**변경 2: 앱 인스턴스 생성**
```js
const GAME_APPS = {
  'codenames-duet': createCodenamesApp(),
  'davinci-code':   createDavinciApp(),
  'matgo':          createMatgoApp(),
  'yutnori':        createYutnoriApp(),
  'tetris-battle':  createTetrisApp(),
};
```

**변경 3: 로비 WSS (noServer)**
```js
const lobbyWss = new WebSocketServer({ noServer: true });
// 기존 wss.on('connection', ...) → lobbyWss.on('connection', ...)
```

**변경 4: HTTP 서버 및 라우터**
```js
const server = http.createServer((req, res) => {
  const urlPath = (req.url || '/').split('?')[0];
  // 첫 path segment 추출: /matgo/style.css → 'matgo'
  const segments = urlPath.split('/').filter(Boolean);
  const first = segments[0] || '';

  if (GAME_APPS[first]) {
    // req.url을 prefix 제거 후 재작성
    const sub = '/' + segments.slice(1).join('/') || '/';
    req.url = sub === '/' || sub === '' ? '/' : sub;
    return GAME_APPS[first].handleHttp(req, res);
  }

  // 런처 정적 서빙 (기존 resolveSafePath 로직 재사용)
  return serveLauncherStatic(req, res);
});
```

**변경 5: WS upgrade 라우터**
```js
server.on('upgrade', (req, socket, head) => {
  const urlPath = (req.url || '/').split('?')[0];
  const segments = urlPath.split('/').filter(Boolean);
  const first = segments[0] || '';
  const last  = segments[segments.length - 1] || '';

  if (GAME_APPS[first] && last === 'ws') {
    return GAME_APPS[first].handleUpgrade(req, socket, head);
  }
  if (urlPath === '/ws') {
    return lobbyWss.handleUpgrade(req, socket, head, (ws) => {
      lobbyWss.emit('connection', ws, req);
    });
  }
  // 미매칭 → 연결 거절
  socket.destroy();
});
```

**변경 6: spawnBot URL**
```js
function spawnBot(gameId) {
  const botPath = path.join(MINIGAMES_ROOT, gameId, 'bot.js');
  if (!fs.existsSync(botPath)) {
    console.warn(`[launcher] bot.js 없음, AI 봇 생략: ${gameId}`);
    return;
  }
  const wsUrl = `ws://localhost:${PORT}/${gameId}/ws`;
  const child = spawn(process.execPath, [botPath, '--url', wsUrl], {
    detached: true, stdio: 'ignore',
  });
  child.on('error', (err) => console.error(`[launcher] 봇 spawn 에러 (${gameId}):`, err.message));
  child.unref();
  console.log(`[launcher] 봇 기동: ${gameId} --url ${wsUrl} (pid=${child.pid})`);
}
```

spawnBot 시그니처 변경: `(gameId, port)` → `(gameId)`. `port` 파라미터 제거.

`PICK_GAME` 핸들러에서 `spawnBot(gameId, port)` → `spawnBot(gameId)` 호출로 변경.

**변경 7: REDIRECT 메시지 페이로드**
기존: `broadcast({ type: 'REDIRECT', gameId, port, mode })`
변경: `broadcast({ type: 'REDIRECT', gameId, path: `/${gameId}/`, mode })`

`port` 필드는 제거하거나 하위 호환을 위해 유지해도 무방하나, app.js에서 더 이상 사용하지 않으므로 제거한다.

