**설계 구조:**
```js
/** 광고 제거 상품 ID (스토어 등록 후 실제 ID로 교체) */
export const REMOVE_ADS_PRODUCT_ID = 'com.lazyslime.kitchenchaos.remove_ads';

/** localStorage 키 */
const ADS_REMOVED_KEY = 'kitchenChaos_adsRemoved';

export class IAPManager {
  /**
   * 광고 제거 상품을 구매한다 (스텁).
   * Phase 81 범위: 즉시 구매 완료로 처리(테스트/개발용).
   * 실제 구현 시 @capacitor-community/in-app-purchases 연동 필요.
   * @returns {Promise<void>}
   */
  static async purchaseRemoveAds() {
    // 스텁: localStorage에 구매 플래그 저장
    localStorage.setItem(ADS_REMOVED_KEY, '1');
    console.log('[IAPManager] 광고 제거 구매 완료 (스텁)');
  }

  /**
   * 광고 제거 구매 여부를 반환한다.
   * @returns {boolean}
