**변경 후 `_createResourceHUD()` 상세**:

```js
_createResourceHUD() {
  const HUD_Y1 = 92;   // 1행: 기존 리소스 (y=100 → 92로 소폭 상향)
  const HUD_Y2 = 112;  // 2행: 에너지 표시

  // 1행: 기존 리소스
  const gold = SaveManager.getGold();
  const coins = SaveManager.getCoins();
  const essence = SaveManager.getMireukEssence();

  const colXs = [GAME_WIDTH / 6, GAME_WIDTH / 2, GAME_WIDTH * 5 / 6];
  const labels1 = [
    `💰 ${gold.toLocaleString()}`,
    `🪙 ${coins}`,
    `✨ ${essence}`,
  ];
  const colors1 = ['#ffd700', '#aaddff', '#cc88ff'];

  labels1.forEach((text, i) => {
    this.add.text(colXs[i], HUD_Y1, text, {
      fontSize: '12px', color: colors1[i],
      stroke: '#000000', strokeThickness: 2,
    }).setOrigin(0.5);
  });

  // 2행: 에너지 표시
  const energy = EnergyManager.getEnergy();
  const energyStr = `⚡ ${energy}/${ENERGY_MAX}`;
  this.add.text(GAME_WIDTH / 2 - 60, HUD_Y2, energyStr, {
    fontSize: '12px', color: '#ffdd55',
    stroke: '#000000', strokeThickness: 2,
  }).setOrigin(0.5);

  // 에너지 미만 시 카운트다운 타이머 표시
  if (energy < ENERGY_MAX) {
    const countdownText = this.add.text(GAME_WIDTH / 2 + 30, HUD_Y2, '', {
      fontSize: '11px', color: '#aaaaaa',
      stroke: '#000000', strokeThickness: 1,
    }).setOrigin(0, 0.5);

    // 1초 주기 갱신 타이머
    this._energyCountdownEvent = this.time.addEvent({
      delay: 1000,
      loop: true,
      callback: () => {
        const secs = EnergyManager.getRechargeCountdown();
        if (secs <= 0) {
          countdownText.setText('');
          if (this._energyCountdownEvent) {
            this._energyCountdownEvent.remove();
            this._energyCountdownEvent = null;
          }
        } else {
          const mm = String(Math.floor(secs / 60)).padStart(2, '0');
          const ss = String(secs % 60).padStart(2, '0');
          countdownText.setText(`충전까지 ${mm}:${ss}`);
        }
      },
    });
  }
}
```

