for (const side of ['top', 'bot']) {
  for (let s = 0; s < 4; s++) { ... }
}

// 변경 후
for (const side of ['left', 'right']) {
  for (let s = 0; s < 3; s++) { ... }  // lv0 = 3슬롯
}
```

