## 단위 자가 검증 방법

Coder는 구현 완료 후 브라우저 콘솔 또는 Node.js에서 아래와 같이 단독 검증할 수 있다.

```js
// Node.js 환경에서 ES module 실행: node --input-type=module < test.mjs
import { getEligiblePool, selectBranchCards } from './kitchen-chaos/js/data/merchantBranchData.js';

// 시나리오 A: ch=5, season2=false → arjun bond 카드 미출현
const psA = { currentChapter: 5, season2Unlocked: false, season3Unlocked: false, tools: { pan: { count: 4 } } };
const poolBondA = getEligiblePool('bond', {}, psA);
console.assert(!poolBondA.some(c => c.chefId === 'arjun_chef'), 'FAIL: arjun bond가 ch5에서 출현');
console.assert(!poolBondA.some(c => c.chefId === 'lao_chef'),   'FAIL: lao bond가 ch5에서 출현');
console.assert(!poolBondA.some(c => c.chefId === 'andre_chef'), 'FAIL: andre bond가 ch5에서 출현');
console.assert(!poolBondA.some(c => c.chefId === 'yuki_chef'),  'FAIL: yuki bond가 ch5에서 출현');
// mimi, rin, mage는 항상 해금
console.assert(poolBondA.some(c => c.chefId === 'mimi_chef'), 'FAIL: mimi bond 누락');

// 시나리오 B: wasabi_cannon.count=0 → mut_wasabi_cluster 미출현
const psB = { currentChapter: 10, season2Unlocked: true, season3Unlocked: false,
              tools: { pan: { count: 4 }, wasabi_cannon: { count: 0 } } };
const poolMutB = getEligiblePool('mutation', {}, psB);
console.assert(!poolMutB.some(c => c.id === 'mut_wasabi_cluster'), 'FAIL: wasabi mutation이 미보유 상태에서 출현');

// 시나리오 C: 모든 카테고리 풀 소진 시 에러 없이 빈 배열 반환
const psC = { currentChapter: 1, season2Unlocked: false, season3Unlocked: false, tools: {} };
const result = selectBranchCards({ toolMutations: { pan: 'mut_pan_flame', salt: 'mut_salt_chain',
  grill: 'mut_grill_inferno', delivery: 'mut_delivery_ghost', freezer: 'mut_freezer_permafrost',
  soup_pot: 'mut_soup_overcharge', wasabi_cannon: 'mut_wasabi_cluster', spice_grinder: 'mut_spice_venom' },
  unlockedBranchRecipes: ['branch_dragon_feast','branch_mireuk_tea','branch_grand_omakase',
    'branch_golden_curry','branch_chaos_ramen','branch_frozen_dessert','branch_spice_bomb','branch_bistro_course'],
  chefBonds: ['bond_mimi_salt','bond_mimi_spice','bond_rin_pan','bond_mage_freezer'] }, psC);
console.assert(Array.isArray(result), 'FAIL: 반환값이 배열이 아님');
console.log('결과 카드 수:', result.length, '(0~3 정상)');
```

