      const path = `${SPRITES_ROOT}/bosses/queen_of_taste/phase${phaseId.slice(-1)}/animations/${hash}/${dir}/frame_${String(f).padStart(3, '0')}.png`;
      scene.load.image(key, path);
    }
  }
}
