### 2-3. `_cellToWorld(col, row)` 신규 추가

**추가 위치:** `_createTables()` 바로 위

```js
/**
 * 홀 격자 좌표 → 아이소메트릭 월드 픽셀 중심 좌표 변환.
 * config.js의 cellToWorld()와 동일한 공식이나,
 * ServiceScene 홀 전용 상수(SISO_*)를 사용한다.
 * @param {number} col - 열 (0 ~ tableCols-1)
 * @param {number} row - 행 (0 ~ TABLE_ROWS-1)
 * @returns {{x: number, y: number}}
 * @private
 */
_cellToWorld(col, row) {
  return {
    x: SISO_ORIGIN_X + (col - row) * SISO_HALF_W,
    y: SISO_ORIGIN_Y + (col + row) * SISO_HALF_H,
  };
}
```

### 2-4. `_drawIsoFloor()` 신규 추가

**추가 위치:** `_cellToWorld()` 바로 아래

아이소메트릭 홀 바닥 렌더링 함수.
floor_hall 스프라이트가 있으면 이미지로, 없으면 다이아몬드 폴리곤 fallback.

```js
/**
 * 아이소메트릭 홀 바닥 렌더링.
 * floor_hall 스프라이트 우선, fallback: 다이아몬드 폴리곤 격자.
 * @private
 */
_drawIsoFloor() {
  if (SpriteLoader.hasTexture(this, 'floor_hall')) {
    // 홀 영역 전체를 덮는 단일 이미지
    this.add.image(GAME_WIDTH / 2, HALL_Y + HALL_H / 2, 'floor_hall')
      .setDisplaySize(GAME_WIDTH, HALL_H)
      .setDepth(0);
    return;
  }

  // fallback: 아이소 다이아몬드 폴리곤 격자 (2행×4열)
  const gfx = this.add.graphics().setDepth(1);
  for (let r = 0; r < TABLE_ROWS; r++) {
    for (let c = 0; c < this.tableCols; c++) {
      const { x, y } = this._cellToWorld(c, r);
      const hw = SISO_HALF_W, hh = SISO_HALF_H;
      gfx.fillStyle(0x2a2a4a, 0.8);
      gfx.fillPoints([
        { x: x,      y: y - hh },   // 상
        { x: x + hw, y: y      },   // 우
        { x: x,      y: y + hh },   // 하
        { x: x - hw, y: y      },   // 좌
      ], true);
      gfx.lineStyle(1, 0x4a4a6a, 0.6);
      gfx.strokePoints([
        { x: x,      y: y - hh },
        { x: x + hw, y: y      },
        { x: x,      y: y + hh },
        { x: x - hw, y: y      },
      ], true);
    }
  }
}
```

### 2-5. `_createTables()` 전면 재작성

**변경 전 (요약):**
```js
_createTables() {
  // 홀 배경 이미지/색상 직사각형
  // ...
  const cellW = GAME_WIDTH / this.tableCols;
  const cellH = HALL_H / TABLE_ROWS;
  for (let row = 0; row < TABLE_ROWS; row++) {
    for (let col = 0; col < this.tableCols; col++) {
      const cx = cellW * col + cellW / 2;       // flat 좌표
      const cy = HALL_Y + cellH * row + cellH / 2;  // flat 좌표
      const container = this.add.container(cx, cy).setDepth(10);  // 고정 depth
      // 테이블, 의자, 말풍선, 인내심 바, 손님 아이콘, 히트 영역 생성
      // ...
    }
  }
}
```

**변경 후 (요약):**
```js
_createTables() {
  // 홀 배경 — 아이소 바닥 렌더
  this._drawIsoFloor();

  this.tableContainers = [];
  const tw = SISO_HALF_W * 2;   // 80px
  const th = SISO_HALF_H * 2;   // 60px

  for (let row = 0; row < TABLE_ROWS; row++) {
    for (let col = 0; col < this.tableCols; col++) {
      const idx = row * this.tableCols + col;
      if (idx >= this.tableCount) break;

      // 아이소메트릭 좌표 계산
      const { x: cx, y: cy } = this._cellToWorld(col, row);
      const grade = this.tableUpgrades[idx] || 0;

      // depth sorting: y좌표 기반 (뒤쪽 테이블이 앞쪽에 가려지도록)
      const depth = 10 + cy;
      const container = this.add.container(cx, cy).setDepth(depth);

      // 테이블 스프라이트 (Phase 19-4 에셋 재활용)
      const tableKey = `table_lv${grade}`;
      if (SpriteLoader.hasTexture(this, tableKey)) {
        const tableImg = this.add.image(0, 0, tableKey)
          .setDisplaySize(tw, th);
        container.add(tableImg);
      } else {
        // fallback: 아이소 다이아몬드 형태 색상 박스
        const tableBg = this.add.rectangle(0, 0, tw, th, TABLE_COLORS[grade], 0.6)
          .setStrokeStyle(TABLE_STROKE_WIDTH[grade], TABLE_STROKE_COLOR[grade]);
        container.add(tableBg);
        if (grade >= 1) {
          container.add(this.add.rectangle(0, 0, tw - 16, th - 12, 0xffffff, 0.15));
