            fontSize: '7px', fontStyle: 'bold', color: '#ffd700',
            backgroundColor: '#000000aa', padding: { x: 2, y: 1 },
          }).setOrigin(1, 0);
          container.add(vipBadge);
        }
      }

      // "빈 테이블" 텍스트 (y offset 조정: 아이소에서 상단)
      const statusText = this.add.text(0, -th / 2 - 8, '빈 테이블', {
        fontSize: '10px', color: '#888888',
