      container.add(statusText);

      // 말풍선 (테이블 상단)
      const bubble = this.add.rectangle(0, -th / 2 - 20, 80, 22, 0xffffff, 0.9)
        .setStrokeStyle(1, 0x000000).setVisible(false);
      container.add(bubble);
      const bubbleText = this.add.text(0, -th / 2 - 20, '', {
        fontSize: '9px', color: '#333333',
      }).setOrigin(0.5).setVisible(false);
      container.add(bubbleText);

      // 인내심 바 (테이블 하단)
      const pBarBg = this.add.rectangle(0, th / 2 + 6, 60, 6, 0x333333).setVisible(false);
      container.add(pBarBg);
      const pBarFill = this.add.rectangle(-30, th / 2 + 6, 60, 6, 0x00ff00)
        .setOrigin(0, 0.5).setVisible(false);
      container.add(pBarFill);

      // 손님 아이콘 (테이블 위 중앙)
      const custIconImg = this.add.image(0, -th / 2 + 8, '__MISSING')
        .setDisplaySize(28, 28).setVisible(false);
      container.add(custIconImg);
      const custIconText = this.add.text(0, -th / 2 + 8, '', {
        fontSize: '20px',
      }).setOrigin(0.5).setVisible(false);
      container.add(custIconText);

      // 터치 영역
      const hitArea = this.add.rectangle(0, 0, tw + 10, th + 10, 0x000000, 0)
        .setInteractive({ useHandCursor: true });
      container.add(hitArea);
      hitArea.on('pointerdown', () => this._onTableTap(idx));

      this.tableContainers.push(container);

      // UI 참조 저장 (기존 키 그대로 유지 — _updateTableUI 무변경)
      container.setData('statusText', statusText);
      container.setData('bubble', bubble);
      container.setData('bubbleText', bubbleText);
      container.setData('pBarBg', pBarBg);
      container.setData('pBarFill', pBarFill);
      container.setData('custIconImg', custIconImg);
      container.setData('custIconText', custIconText);
    }
  }
}
```

### 2-6. `create()` 내 tableW / tableH 계산 제거

**변경 전:**
```js
// 테이블 크기: 4~6석 90x80, 8석 75x70
this.tableW = this.tableCount >= 7 ? 75 : 90;
this.tableH = this.tableCount >= 7 ? 70 : 80;
```

**변경 후:**
```js
// 테이블 크기: 아이소메트릭 셀 크기 기반 (SISO_HALF_W*2 × SISO_HALF_H*2)
// tableW, tableH 변수 제거 (SISO_HALF_W/H로 대체)
```

`this.tableW`, `this.tableH`가 `_createTables()` 외부에서 참조되지 않으므로 삭제해도 안전.
(Grep 검증 필요 — Coder가 확인 후 삭제 또는 호환값 유지)

