import { DialogueManager } from '../managers/DialogueManager.js';

// GatheringScene.create() 내
if (this.stageId.endsWith('-6')) {
  // 보스 스테이지 첫 진입 경고 (스테이지별 ID로 구분)
  const bossWarningId = `stage_boss_warning_${this.stageId}`;
