  if (!DialogueManager.hasSeen('stage_boss_warning')) {
    // 씬 페이드인 후 300ms 지연으로 트리거
    this.time.delayedCall(400, () => {
      DialogueManager.start(this, 'stage_boss_warning');
    });
  }
}
