### 각 파일별 변경사항

#### `js/data/storyData.js` (신규)

트리거 목록을 배열로 정의한다. 각 트리거는 `triggerPoint`(어느 씬/이벤트), `dialogueId`(재생할 대화), `condition`(조건 함수)으로 구성된다.

```js
/**
 * @fileoverview 스토리 트리거 데이터.
 * 각 항목은 triggerPoint별로 분류되며, StoryManager.checkTriggers()가 평가한다.
 *
 * condition(ctx, save): boolean 함수
 *   ctx  — { stageId?, stars?, isFirstClear?, isMarketFailed?, chapter? }
 *   save — StoryManager.getProgress() 반환값 (currentChapter, storyFlags, seenDialogues 참조)
 */
export const STORY_TRIGGERS = [
  // ── WorldMapScene 진입 ──
  {
    triggerPoint: 'worldmap_enter',
    dialogueId: 'intro_welcome',
    once: true,
    condition: (ctx, save) => true,
    // intro_welcome 완료 후 연쇄 트리거
    chain: {
      dialogueId: 'chapter1_start',
      condition: (ctx, save) => save.currentChapter >= 1,
    },
  },
  {
    triggerPoint: 'worldmap_enter',
    dialogueId: 'chapter2_intro',
    once: true,
    condition: (ctx, save) => save.currentChapter >= 2,
  },
  {
    triggerPoint: 'worldmap_enter',
    dialogueId: 'mage_introduction',
    once: true,
    condition: (ctx, save) => save.currentChapter >= 3,
  },
  {
    triggerPoint: 'worldmap_enter',
    dialogueId: 'mage_research_hint',
    once: true,
    condition: (ctx, save) =>
      save.seenDialogues.includes('mage_introduction'),
  },

  // ── MerchantScene 진입 ──
  {
    triggerPoint: 'merchant_enter',
    dialogueId: 'merchant_first_meet',
    once: true,
    condition: (ctx, save) => true,
  },
  {
    triggerPoint: 'merchant_enter',
    dialogueId: 'poco_discount_fail',
    once: true,
    condition: (ctx, save) =>
      save.seenDialogues.includes('merchant_first_meet'),
  },

  // ── GatheringScene 진입 ──
  {
    triggerPoint: 'gathering_enter',
    dialogueId: 'stage_boss_warning',
    once: true,
    condition: (ctx, save) =>
      ctx.stageId?.endsWith('-6') === true,
    delay: 400,
  },

  // ── ResultScene: 스테이지 클리어 ──
  {
    triggerPoint: 'result_clear',
    dialogueId: 'stage_first_clear',
    once: false,            // 매 첫 클리어마다 (단, hasSeen으로 1회 제한)
    once: true,
    condition: (ctx, save) =>
      ctx.isFirstClear && ctx.stars > 0 &&
      ctx.stageId !== '1-6' &&
      ctx.stageId !== '2-1' &&
      ctx.stageId !== '3-3',
    delay: 800,
  },
  {
    triggerPoint: 'result_clear',
    dialogueId: 'stage_first_clear',
    once: false,
    condition: (ctx, save) =>
      ctx.isFirstClear && ctx.stars > 0 && ctx.stageId === '1-6',
    delay: 800,
    chain: { dialogueId: 'chapter1_clear' },
  },
  {
    triggerPoint: 'result_clear',
    dialogueId: 'rin_first_meet',
    once: true,
    condition: (ctx, save) =>
      ctx.isFirstClear && ctx.stars > 0 && ctx.stageId === '2-1',
    delay: 800,
  },
  {
    triggerPoint: 'result_clear',
    dialogueId: 'chapter3_rin_joins',
    once: true,
    condition: (ctx, save) =>
      ctx.isFirstClear && ctx.stars > 0 && ctx.stageId === '3-3',
    delay: 800,
  },

  // ── ResultScene: 장보기 실패 ──
  {
    triggerPoint: 'result_market_failed',
    dialogueId: 'after_first_loss',
    once: true,
    condition: (ctx, save) => true,
    delay: 800,
  },
];
```

**설계 원칙:**
- `triggerPoint`는 씬/이벤트 식별자 문자열이다. 씬 코드는 이 문자열만 알면 된다.
- `once: true`이면 `DialogueManager.hasSeen(dialogueId)`로 중복 재생을 차단한다.
- `chain`은 부모 대화 `onComplete` 콜백에서 자동으로 연쇄 실행된다.
- `delay`(ms)가 있으면 `scene.time.delayedCall`로 지연 실행한다.
- `condition`이 false이면 해당 항목을 건너뛴다.

