/**
 * 시즌을 전환한다. 맵 콘텐츠를 재생성한다.
 * @param {number} season - 1 또는 2
 * @private
 */
_switchSeason(season) {
  this._currentSeason = season;

  // 기존 패널 닫기
  if (this._panelContainer) {
    this._panelContainer.destroy();
    this._panelContainer = null;
