### B1. _showRewardPopup(rewardObj, title, isMilestone)

```javascript
_showRewardPopup(rewardObj, title, isMilestone = false) {
  // 오버레이
  const overlay = this.add.graphics().setDepth(200);
  overlay.fillStyle(0x000000, 0.6);
  overlay.fillRect(0, 0, 360, 640);

  // 팝업 컨테이너 (depth 201)
  const popup = this.add.container(180, 320).setDepth(201);

  // 패널 배경 (280×200, 중심 기준 -140,-100 ~ +140,+100)
  const panel = this.add.graphics();
  panel.fillStyle(0x0A0A2E, 0.95);
  panel.fillRoundedRect(-140, -100, 280, 200, 8);
  panel.lineStyle(2, isMilestone ? COLORS.NEON_CYAN : COLORS.NEON_GREEN, 0.9);
  panel.strokeRoundedRect(-140, -100, 280, 200, 8);
  popup.add(panel);

  // 타이틀 (16px)
  const titleText = this.add.text(0, -76, title, {
    fontSize: '16px', fontFamily: 'Galmuri11, monospace',
    color: isMilestone ? UI_COLORS.neonCyan : UI_COLORS.neonGreen,
  }).setOrigin(0.5);
  popup.add(titleText);

  // 구분선
  const divider = this.add.graphics();
  divider.lineStyle(1, COLORS.UI_BORDER, 0.6);
  divider.lineBetween(-100, -56, 100, -56);
  popup.add(divider);

  // 보상 항목 (18px, 줄간격 28px)
  let rewardY = -36;
  const rewardLines = [];
  if (rewardObj.credits) rewardLines.push(`💰 ${t('daily.reward.credits', rewardObj.credits)}`);
  if (rewardObj.scrap) rewardLines.push(`🔩 ${t('daily.reward.scrap', rewardObj.scrap)}`);
  if (rewardObj.dataCores) rewardLines.push(`⚡ ${t('daily.reward.dataCores', rewardObj.dataCores)}`);
  if (rewardObj.crystal) rewardLines.push(`💎 ${t('daily.reward.crystal', rewardObj.crystal)}`);

  rewardLines.forEach(line => {
    const rt = this.add.text(0, rewardY, line, {
      fontSize: '16px', fontFamily: 'Galmuri11, monospace',
      color: UI_COLORS.textPrimary,
    }).setOrigin(0.5);
    popup.add(rt);
    rewardY += 26;
  });

  // 확인 버튼 (200×44)
  const btnBg = this.add.graphics();
  btnBg.fillStyle(isMilestone ? COLORS.NEON_CYAN : COLORS.NEON_GREEN, 0.9);
  btnBg.fillRoundedRect(-100, 56, 200, 44, 6);
  popup.add(btnBg);

  const btnText = this.add.text(0, 78, t('daily.confirm') || '확인', {
    fontSize: '14px', fontFamily: 'Galmuri11, monospace',
    color: '#000000', fontStyle: 'bold',
  }).setOrigin(0.5);
  popup.add(btnText);

  const btnZone = this.add.zone(0, 78, 200, 44).setInteractive({ useHandCursor: true });
  popup.add(btnZone);

  // 등장 애니메이션
  popup.setScale(0.7).setAlpha(0);
  this.tweens.add({
    targets: popup, scale: 1, alpha: 1,
    duration: 200, ease: 'Back.Out',
  });

  // 사운드
  SoundSystem.play('levelup');

  // 마일스톤이면 파티클
  if (isMilestone) {
    VFXSystem.levelUpBurst(this, 180, 320);
  }

  // 확인 버튼 → 제거 → restart
  btnZone.on('pointerup', () => {
    this.tweens.add({
      targets: [popup, overlay], alpha: 0, duration: 150,
      onComplete: () => {
        popup.destroy();
        overlay.destroy();
        this.scene.restart();
      },
    });
  });
}
```

