```js
// 기존 유지
const LIST_Y_START = 210;

// 신규 추가
const LIST_Y_END   = 560;   // 칩 목록 가시 영역 하단 (마스크 하단 경계)
const SCROLL_AREA_H = LIST_Y_END - LIST_Y_START;  // = 350px (약 3.24행 가시)
const ACTION_Y_START = 565; // 고정 버튼 영역 시작 (구분선 Y)
const DRAG_THRESHOLD = 8;   // 드래그/탭 구분 임계값(px)
```

