### 스크롤 구현 방식

#### 인스턴스 변수 추가 (create() 내 초기화)
```js
/** @type {number} 현재 스크롤 오프셋 (listContainer.y) */
this._scrollOffset = 0;
/** @type {number} 스크롤 최솟값 (음수, 콘텐츠 하단 경계) */
this._scrollMin = 0;
/** @type {number} 스크롤 최댓값 (0, 상단) */
this._scrollMax = 0;
/** @type {number} 포인터다운 Y (드래그 판별) */
this._pointerDownY = 0;
/** @type {number} 드래그 누적 이동량 (탭 억제 판별) */
this._dragDelta = 0;
/** @type {boolean} 드래그 중 여부 */
this._isDragging = false;
```

#### 마스크 생성 (_refreshList() 또는 전용 메서드)
```js
// 기존 마스크 제거
if (this._listMask) {
  this._listMask.destroy();
  this._listMask = null;
}
// 새 마스크 생성 (씬 좌상단 기준 절대좌표)
const maskGraphics = this.make.graphics({ x: 0, y: 0, add: false });
maskGraphics.fillStyle(0xffffff, 1);
maskGraphics.fillRect(0, LIST_Y_START, GAME_WIDTH, SCROLL_AREA_H);
this._listMask = maskGraphics.createGeometryMask();
this._listContainer.setMask(this._listMask);
```

- `this._listMask`를 인스턴스 변수로 보관하여 `_refreshList()` 호출 시마다 재생성
- 마스크는 스크롤 컨테이너의 오프셋과 무관하게 씬 절대좌표 기준 고정

#### 스크롤 범위 계산 공식
```
총 콘텐츠 높이 = rows * (CARD_H + CARD_GAP) - CARD_GAP
             = Math.ceil(items.length / CARDS_PER_ROW) * 108 - 8

scrollMin = -(totalContentH - SCROLL_AREA_H)  // 음수 or 0
scrollMax = 0
스크롤 비활성 조건: totalContentH <= SCROLL_AREA_H
```

#### 이벤트 등록/해제 메서드: `_setupScrollInput()`
`_refreshList()` 끝에서 호출한다.

```js
_setupScrollInput() {
  // 기존 리스너 제거
  this.input.off('pointerdown', this._onPointerDown, this);
  this.input.off('pointermove', this._onPointerMove, this);
  this.input.off('pointerup',   this._onPointerUp,   this);

  if (this._scrollMin >= 0) return; // 스크롤 불필요

  this.input.on('pointerdown', this._onPointerDown, this);
  this.input.on('pointermove', this._onPointerMove, this);
  this.input.on('pointerup',   this._onPointerUp,   this);
}
```

#### 포인터 핸들러 메서드 (인스턴스 메서드로 추가)

```js
_onPointerDown(pointer) {
  // 칩 목록 영역 내 터치만 처리
  if (pointer.y < LIST_Y_START || pointer.y > LIST_Y_END) return;
  this._pointerDownY = pointer.y;
  this._dragDelta = 0;
  this._isDragging = false;
}

_onPointerMove(pointer) {
  if (!pointer.isDown) return;
  if (pointer.y < LIST_Y_START || pointer.y > LIST_Y_END) return;
  const dy = pointer.y - pointer.prevPosition.y;
  this._dragDelta += Math.abs(dy);
  if (this._dragDelta > DRAG_THRESHOLD) this._isDragging = true;
  if (!this._isDragging) return;
  this._scrollOffset = Phaser.Math.Clamp(
    this._scrollOffset + dy,
    this._scrollMin,
    this._scrollMax
  );
  this._listContainer.setY(this._scrollOffset);
}

_onPointerUp(pointer) {
  // isDragging이면 카드 탭 이벤트 억제 플래그 설정
  // (카드 zone의 pointerdown 핸들러에서 this._isDragging 체크)
  // — 별도 액션 없음, 플래그는 다음 pointerdown에서 초기화됨
}
```

#### 카드 탭 억제: `_renderCards()` 내 zone.on('pointerdown') 수정
```js
// 기존
zone.on('pointerdown', () => { this._onCardTap(item, isGroup); });

// 변경
zone.on('pointerdown', () => {
  // 드래그 중이면 카드 탭 이벤트 무시
  if (this._isDragging) return;
  this._onCardTap(item, isGroup);
});
```

#### 스크롤 리셋 타이밍
`_refreshList()` 첫 줄에서 리셋:
```js
this._scrollOffset = 0;
this._listContainer.setY(0);
this._isDragging = false;
this._dragDelta = 0;
```

