└── _onShutdown()             — SoundSystem 복원 + 리소스 정리
```

**`init(data)` 메서드**

```javascript
init(data) {
  this._chipId   = data.chipId;    // 'pierce' | 'multishot' | ... 등 8종
  this._chipGrade = data.chipGrade; // 'C' | 'B' | 'A' | 'S'
  this._bounds   = data.bounds;    // { x:20, y:130, w:320, h:360 }
}
```

**`create()` 메서드 — 카메라 및 배경**

```javascript
const { x, y, w, h } = this._bounds;
this.cameras.main.setViewport(x, y, w, h);

// 어두운 패널 배경
this._bgGraphics = this.add.graphics();
this._bgGraphics.fillStyle(COLORS.BG_DARK, 0.95);
