SoundSystem._sfxEnabled = false;
```

**`create()` 메서드 — mockPlayer 구성**

mockPlayer는 뷰포트 하단 1/3 지점에 고정 배치. 드론이 공전하므로 bioplasma와 달리 이동 불필요.

```javascript
this._mockPlayer = {
  x: w / 2,
  y: h * 2 / 3,
  active: true,
  attackMultiplier: 1,
  cooldownMultiplier: 1,
  critChance: 0,
  critDamage: 1.5,
  critDamageMultiplier: 0,
  droneDamageBonus: 0,
  currentHp: 100,
  maxHp: 100,
  getEffectiveAttackMultiplier: () => 1,
};
```

**`create()` 메서드 — 더미 적 3개 배치**

적은 뷰포트 상단에 배치하여 드론 사거리 내에 위치:
- 상단 중앙: `(w/2, h/5)`
- 우측 중간: `(w*3/4, h/3)`
- 좌측 중간: `(w/4, h/3)`

더미 적 최소 인터페이스 (WeaponPreviewScene 패턴 동일):
```javascript
_createDummyEnemy(ex, ey) {
  return {
    x: ex, y: ey,
    active: true,
    currentHp: 9999,            // findClosestEnemy의 currentHp > 0 조건 통과
    takeDamage: () => {},
    setTint: () => {},
    clearTint: () => {},
    applyDebuff: () => {},
    applyPoison: () => {},
    tauntTarget: null,
    body: { velocity: { x: 0, y: 0 } },
  };
}
```

**`create()` 메서드 — waveSystem 호환 레이어**

칩 전략들이 `scene.waveSystem.enemyPool.getActive()` 또는 `scene.waveSystem.enemyPool.forEach()`를 호출하므로 두 인터페이스 모두 제공:
```javascript
this.waveSystem = {
  enemyPool: {
    forEach:   (cb) => this._dummyEnemies.forEach(cb),
    getActive: ()   => this._dummyEnemies,  // 배열 직접 반환
  },
};
```

**`create()` 메서드 — 투사체 풀 (mock)**

실제 ObjectPool(Projectile)을 생성하되 풀 크기는 20으로 제한. `DroneCompanionSystem.fireDrone()`이 `this.projectilePool.get()`을 호출하므로 실제 ObjectPool이 필요하다.

```javascript
import ObjectPool from '../systems/ObjectPool.js';
import Projectile from '../entities/Projectile.js';
// ...
this._projectilePool = new ObjectPool(this, Projectile, 20);
```

**`create()` 메서드 — mock DroneCompanionSystem 구성**

전략 클래스 생성자가 `new Cls(droneSystem, grade)` 형식으로 호출하며, `droneSystem.player`, `droneSystem.scene`, `droneSystem.findClosestEnemy()`, `droneSystem.fireDrone()`, `droneSystem._droneHoverAngle`, `droneSystem._stats`를 참조한다.

mock 시스템 객체는 DroneCompanionSystem 인스턴스화 없이 직접 구성한다 (SaveManager 의존성 회피):

```javascript
this._mockDroneSystem = {
  scene: this,
  player: this._mockPlayer,
  projectilePool: this._projectilePool,
  _droneHoverAngle: 0,
  _stats: {
    damage: 20,
    cooldown: 800,
    shootRange: 120,
    moveSpeed: 120,
    droneCount: 1,
    hivemind: false,
  },

  /** findClosestEnemy: waveSystem.enemyPool.getActive() 기반 탐색 */
  findClosestEnemy: (x, y, range) => {
    let closest = null;
    let minDist = range;
    for (const enemy of this._dummyEnemies) {
      if (!enemy.active || enemy.currentHp <= 0) continue;
      const dx = enemy.x - x;
      const dy = enemy.y - y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < minDist) { minDist = dist; closest = enemy; }
    }
    return closest;
  },

  /** fireDrone: 실제 투사체 풀 사용, 사운드 스킵 */
  fireDrone: (drone, target, options = {}) => {
    // options.overrideDir 또는 target 방향 계산
    let dirX, dirY;
    if (options.overrideDir) {
      dirX = options.overrideDir.x; dirY = options.overrideDir.y;
    } else {
      const dx = target.x - drone.gfx.x;
      const dy = target.y - drone.gfx.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist === 0) return;
      dirX = dx / dist; dirY = dy / dist;
    }
    const proj = this._projectilePool.get(drone.gfx.x, drone.gfx.y);
    if (proj) {
      proj.fire(drone.gfx.x, drone.gfx.y, dirX, dirY, 1, 350,
                options.pierceCount || 1);
      proj.weaponId = 'drone_preview';
    }
    // 사운드 재생 없음 (SoundSystem._sfxEnabled = false로 이미 처리)
  },
};
```

**`create()` 메서드 — mockDrone 생성**

Arcade Physics 없이 `this.add.image()`로 생성. 전략의 `onSpawn(drone)` 호출 후 칩 틴트 적용:

```javascript
const chipDef = getChipDef(this._chipId);
const droneImg = this.add.image(
  this._mockPlayer.x,
  this._mockPlayer.y - 50,
  'effect_drone'
).setDepth(6);

if (chipDef && chipDef.tint != null) {
  droneImg.setTint(chipDef.tint);
}

this._mockDrone = {
  gfx: droneImg,
  lastFired: 0,
  targetEnemy: null,
  active: true,
  hoverOffset: 0,
  orbitPhase: 0,
  auraGraphics: [],
  auraTweens: [],
};

// 전략 생성 및 onSpawn 호출
this._chipStrategy = createStrategy(this._mockDroneSystem, this._chipId, this._chipGrade);
this._chipStrategy.onSpawn(this._mockDrone);
```

**`create()` 메서드 — 시각 요소**

```javascript
// 더미 적 빨간 사각형 (WeaponPreviewScene 동일)
this._enemyGraphics = this.add.graphics().setDepth(5);
for (const enemy of this._dummyEnemies) {
  this._enemyGraphics.fillStyle(0xFF3333, 0.7);
  this._enemyGraphics.fillRect(enemy.x - 6, enemy.y - 6, 12, 12);
}

// mockPlayer 시안 십자 마커
this._playerGraphics = this.add.graphics().setDepth(5);
const px = this._mockPlayer.x, py = this._mockPlayer.y;
this._playerGraphics.lineStyle(2, COLORS.NEON_CYAN, 0.8);
this._playerGraphics.beginPath();
this._playerGraphics.moveTo(px - 8, py); this._playerGraphics.lineTo(px + 8, py);
this._playerGraphics.moveTo(px, py - 8); this._playerGraphics.lineTo(px, py + 8);
this._playerGraphics.strokePath();
```

**`update(time, delta)` 메서드**

```javascript
update(time, delta) {
  if (!this._mockDroneSystem || !this._mockDrone) return;

  const { w, h } = this._bounds;
  const deltaSec = delta / 1000;

  // 1. mockDroneSystem._droneHoverAngle 갱신
  this._mockDroneSystem._droneHoverAngle += deltaSec * 2;

  // 2. mockDrone 공전: mockPlayer 주변 반경 60px 원형 공전
  //    전략이 자체적으로 gfx.setPosition()을 호출하므로,
  //    타겟이 없는 상태(호버링 상태)에서 자연스럽게 공전이 표현됨.
  //    단, 카미카제처럼 STATE_DEAD가 지속될 수 있으므로
  //    mockDrone.active는 항상 true로 유지.
  this._mockDrone.active = true;
  this._mockDrone.gfx.setActive(true).setVisible(true);

  // 3. 전략 실행
  this._chipStrategy.execute(
    this._mockDrone, this._mockDroneSystem._stats, this, delta
  );

  // 4. 드론 호버링 미세 회전
  this._mockDrone.gfx.rotation =
    Math.sin(time * 0.003 + this._mockDrone.hoverOffset) * 0.2;

  // 5. 더미 적 active 항상 유지
  for (const enemy of this._dummyEnemies) {
    enemy.active = true;
  }

  // 6. 투사체 갱신 (프레임마다 풀 내 활성 투사체 이동 처리)
  //    투사체는 Arcade Physics Sprite이므로 씬 physics가 자동 업데이트.
  //    단, 뷰포트 범위(0~w, 0~h) 밖으로 나간 투사체는 비활성화.
  this._projectilePool.group.getChildren().forEach((proj) => {
    if (!proj.active) return;
    if (proj.x < 0 || proj.x > w || proj.y < 0 || proj.y > h) {
      proj.setActive(false).setVisible(false);
    }
  });
}
```

**`_onShutdown()` 메서드**

```javascript
_onShutdown() {
  // 사운드 복원
  if (this._prevSfxEnabled !== undefined) {
    SoundSystem._sfxEnabled = this._prevSfxEnabled;
  }

  // 전략 정리
  if (this._chipStrategy && this._chipStrategy.onDestroy) {
    this._chipStrategy.onDestroy(this._mockDrone);
  }
  this._chipStrategy = null;

  // mockDrone 스프라이트 파괴
  if (this._mockDrone && this._mockDrone.gfx) {
    this._mockDrone.gfx.destroy();
  }
  this._mockDrone = null;

  // 투사체 풀 파괴
  if (this._projectilePool) {
    this._projectilePool.group.destroy(true);  // 자식 포함 파괴
    this._projectilePool = null;
  }

  // Graphics 파괴
  ['_bgGraphics', '_enemyGraphics', '_playerGraphics'].forEach((key) => {
    if (this[key]) { this[key].destroy(); this[key] = null; }
  });

  this._dummyEnemies = null;
  this._mockPlayer = null;
  this._mockDroneSystem = null;
}
```

