### 각 파일별 변경사항

#### `js/systems/SoundSystem.js`

**1. @fileoverview 수정**
- `SFX 11종` → `SFX 17종`으로 변경

**2. play() switch 문에 6개 case 추가**
기존 `case 'ultimate':` 다음에 삽입한다.

```js
case 'select':
  SoundSystem._playSelect(ctx, now, vol);
  break;
case 'explosion':
  SoundSystem._playExplosion(ctx, now, vol);
  break;
case 'game_over':
  SoundSystem._playGameOver(ctx, now, vol);
  break;
case 'victory':
  SoundSystem._playVictory(ctx, now, vol);
  break;
case 'button_click':
  SoundSystem._playButtonClick(ctx, now, vol);
  break;
case 'purchase_fail':
  SoundSystem._playPurchaseFail(ctx, now, vol);
  break;
```

**3. SFX 구현 메서드 6개 추가** (`// ── SFX 구현 ──` 섹션 내, `_playUltimate` 이후에 추가)

```js
/**
 * UI 확인/선택 SFX: 880Hz→1000Hz 사인파, gain 0.15, 0.08초.
 * ShopScene 구매 완료, DroneChipScene 장착/해제 등에 사용.
 * @private
 */
static _playSelect(ctx, now, vol) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(880, now);
  osc.frequency.linearRampToValueAtTime(1000, now + 0.08);
  gain.gain.setValueAtTime(0.15 * vol, now);
  gain.gain.linearRampToValueAtTime(0, now + 0.08);
  osc.connect(gain).connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.08);
}

/**
 * 카미카제 폭발 SFX: 저음 노이즈 버스트, 로우패스 100Hz→20Hz, 0.3초.
 * @private
 */
static _playExplosion(ctx, now, vol) {
  const bufferSize = Math.floor(ctx.sampleRate * 0.3);
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = (Math.random() * 2 - 1);
  }
  const noise = ctx.createBufferSource();
  noise.buffer = buffer;

  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(100, now);
  filter.frequency.linearRampToValueAtTime(20, now + 0.3);

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.6 * vol, now);
  gain.gain.linearRampToValueAtTime(0, now + 0.3);

  noise.connect(filter).connect(gain).connect(ctx.destination);
  noise.start(now);
  noise.stop(now + 0.3);
}

/**
 * 게임 오버 징글: C4→A3→F3→C3 하강 아르페지오, 0.12초씩.
 * @private
 */
static _playGameOver(ctx, now, vol) {
  const notes = [261.63, 220.00, 174.61, 130.81]; // C4, A3, F3, C3
  notes.forEach((freq, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, now + i * 0.12);
    gain.gain.setValueAtTime(0.3 * vol, now + i * 0.12);
    gain.gain.linearRampToValueAtTime(0, now + i * 0.12 + 0.12);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now + i * 0.12);
    osc.stop(now + i * 0.12 + 0.15);
  });
}

/**
 * 승리 팡파르: C4→E4→G4→C5→E5 상승 아르페지오, 0.12초씩.
 * @private
 */
static _playVictory(ctx, now, vol) {
  const notes = [261.63, 329.63, 392.00, 523.25, 659.25]; // C4, E4, G4, C5, E5
  notes.forEach((freq, i) => {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, now + i * 0.12);
    gain.gain.setValueAtTime(0.25 * vol, now + i * 0.12);
    gain.gain.linearRampToValueAtTime(0, now + i * 0.12 + 0.15);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now + i * 0.12);
    osc.stop(now + i * 0.12 + 0.18);
  });
}

/**
 * UI 버튼 틱 SFX: 600Hz 사인파, gain 0.12, 0.04초.
 * MenuScene 버튼, 일시정지/재개 등에 사용.
 * @private
 */
static _playButtonClick(ctx, now, vol) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(600, now);
  gain.gain.setValueAtTime(0.12 * vol, now);
  gain.gain.linearRampToValueAtTime(0, now + 0.04);
  osc.connect(gain).connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.04);
}

/**
 * 구매 실패/거부 SFX: 200Hz 사각파, gain 0.25, 0.12초.
 * ShopScene 잔액 부족, 인벤토리 가득 참 등에 사용.
 * @private
 */
static _playPurchaseFail(ctx, now, vol) {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'square';
  osc.frequency.setValueAtTime(200, now);
  osc.frequency.linearRampToValueAtTime(160, now + 0.12);
  gain.gain.setValueAtTime(0.25 * vol, now);
  gain.gain.linearRampToValueAtTime(0, now + 0.12);
  osc.connect(gain).connect(ctx.destination);
  osc.start(now);
  osc.stop(now + 0.12);
}
```

