// 버튼 클릭 SFX를 callback에 래핑
const wrappedCallback = callback
  ? () => { SoundSystem.play('button_click'); callback(); }
  : null;

return createNineSliceButton(this, x, y, label, {
  width, height, fontSize, textColor,
  textStroke, textStrokeThickness,
  disabled, callback: wrappedCallback, tint, alpha, frameType,
