#### `neon-exodus/js/scenes/MenuScene.js`

**제거할 코드:**

```js
// ── 드론 칩 버튼 (해금 시만 표시) ──
if (droneChipUnlocked) {
  this._createButton(centerX, 404, t('menu.droneChip'), { ... });
}
```

```js
// ── 에피소드 버튼 (항상 표시) ──
const episodeBtnY = droneChipUnlocked ? 498 : 476;
this._createButton(centerX, episodeBtnY, t('menu.episode'), { ... });
```

**새 레이아웃 Y좌표 (droneChipUnlocked=true 케이스):**

현재 9행 구조 → 6행(타이틀 + row0 + row1 + 상점 + aux행 + CTA) 구조로 재배치.
화면 높이 640, 타이틀 로고 Y=62 고정.

| 요소 | 새 Y좌표 | 높이 |
|---|---|---|
| row0 (캐릭터 + 업그레이드) | 320 | 52 |
| row1 (도전과제 + 일일 미션) | 380 | 52 |
| 상점 버튼 | 438 | 48 |
| aux행 (도감 + auto/구매 + 설정) | 494 | 36 |
| CTA 출격 버튼 | 548 | 56 |
| 하단 리소스 텍스트 | 616 (= GAME_HEIGHT - 24) | — |

CTA 하단(548+28=576) ~ 리소스(616) 여백 = **40px** (기준 12px 초과, 성공 기준 만족).

**새 레이아웃 Y좌표 (droneChipUnlocked=false 케이스):**

| 요소 | 새 Y좌표 | 높이 |
|---|---|---|
| row0 (캐릭터 + 업그레이드) | 336 | 52 |
| row1 (도전과제 + 일일 미션) | 396 | 52 |
| 상점 버튼 (비활성) | 454 | 48 |
| aux행 (도감 + auto/구매 + 설정) | 510 | 36 |
| CTA 출격 버튼 | 566 | 56 |
| 하단 리소스 텍스트 | 616 | — |

CTA 하단(566+28=594) ~ 리소스(616) 여백 = **22px** (성공 기준 만족).

**변경 후 코드 구조 (MenuScene.js create() 내부):**

```js
const droneChipUnlocked = SaveManager.isDroneChipUnlocked();
const row0Y  = droneChipUnlocked ? 320 : 336;
const row1Y  = droneChipUnlocked ? 380 : 396;
const shopBtnY = droneChipUnlocked ? 438 : 454;
const auxBtnY  = droneChipUnlocked ? 494 : 510;
const ctaBtnY  = droneChipUnlocked ? 548 : 566;

// 캐릭터 버튼 (0,0)
this._createButton(96, row0Y, t('menu.character'), { frameType: 'primary', callback: ... });

// 업그레이드 버튼 (1,0)
this._createButton(264, row0Y, t('menu.upgrade'), { frameType: 'primary', disabled: !upgradeUnlocked, callback: ... });

// 도전과제 버튼 (0,1)
this._createButton(96, row1Y, t('menu.achievements'), { frameType: 'primary', callback: ... });

// 일일 미션 버튼 (1,1)
this._createButton(264, row1Y, dailyLabel, { frameType: 'primary', callback: ... });

// 상점 버튼 (항상 표시, 미해금 시 비활성 + 잠금 토스트)
if (droneChipUnlocked) {
  this._createButton(centerX, shopBtnY, t('menu.shop'), {
    width: 310, height: 48, fontSize: '15px',
    frameType: 'primary',
    callback: () => { this._fadeToScene('ShopScene'); },
  });
} else {
  this._createButton(centerX, shopBtnY, t('menu.shop'), {
    width: 310, height: 48, fontSize: '15px',
    frameType: 'primary', disabled: true,
  });
  const shopZone = this.add.zone(centerX, shopBtnY, 310, 48).setInteractive({ useHandCursor: true });
  shopZone.on('pointerdown', () => { this._showLockedToast(t('shop.locked')); });
}

// aux 행 (도감 + auto/구매 + 설정)
this._createButton(56, auxBtnY, t('menu.collection'), { ... callback: () => this._fadeToScene('CollectionScene') });
// ... auto hunt / 설정 버튼 (기존과 동일, Y만 변경)

// CTA 출격 버튼
this._createButton(centerX, ctaBtnY, t('menu.start'), { width: 310, height: 56, fontSize: '20px', ... });
```

