**`_drawTabBar` 메서드 수정:**

```js
_drawTabBar() {
  const gfx = this._tabBg;
  gfx.clear();

  // 전체 배경 (3탭 대응)
  gfx.fillStyle(UI_COLORS.panelBg, 0.8);
  gfx.fillRoundedRect(20, 75, 320, 34, 6);
  gfx.lineStyle(1, COLORS.NEON_ORANGE, 0.3);
  gfx.strokeRoundedRect(20, 75, 320, 34, 6);

  // 활성 탭 하이라이트
  if (this._activeTab === 'chip') {
    gfx.fillStyle(COLORS.NEON_ORANGE, 0.2);
    gfx.fillRoundedRect(22, 77, 100, 30, 4);
    this._tabChipText.setColor(UI_COLORS.neonOrange);
    this._tabCrystalText.setColor(UI_COLORS.textSecondary);
    this._tabChipManageText.setColor(UI_COLORS.textSecondary);
  } else if (this._activeTab === 'crystal') {
    gfx.fillStyle(COLORS.NEON_MAGENTA, 0.2);
    gfx.fillRoundedRect(130, 77, 100, 30, 4);
    this._tabChipText.setColor(UI_COLORS.textSecondary);
    this._tabCrystalText.setColor(UI_COLORS.neonMagenta);
    this._tabChipManageText.setColor(UI_COLORS.textSecondary);
  } else {
    // chipManage
    gfx.fillStyle(COLORS.NEON_CYAN, 0.2);
    gfx.fillRoundedRect(238, 77, 100, 30, 4);
    this._tabChipText.setColor(UI_COLORS.textSecondary);
    this._tabCrystalText.setColor(UI_COLORS.textSecondary);
    this._tabChipManageText.setColor(UI_COLORS.neonCyan);
  }
}
```

**`_switchTab` 메서드에 chipManage 케이스 추가:**

```js
_switchTab(tabName) {
  if (this._activeTab === tabName) return;

  // chipManage 탭 클릭 처리
  if (tabName === 'chipManage') {
    const droneChipUnlocked = SaveManager.isDroneChipUnlocked();
    if (!droneChipUnlocked) {
      this._showToast(t('shop.chipManageLocked'), UI_COLORS.hpRed);
      return;
    }
    // DroneChipScene으로 씬 전환 (뒤로가기는 ShopScene)
    if (this._transitioning) return;
    this._transitioning = true;
    this.cameras.main.fadeOut(200, 0, 0, 0);
    this.cameras.main.once('camerafadeoutcomplete', () => {
      this.scene.start('DroneChipScene', { fromScene: 'ShopScene' });
    });
    return;
  }

  this._activeTab = tabName;
  this._drawTabBar();
  // ... 기존 chip/crystal 전환 로직
}
```

**탭 바 폰트 크기:** 현재 `'12px'` → 3탭에서 텍스트가 100px 내에 들어가야 하므로 `'11px'`로 줄인다.

