/**
 * 타이틀 글리치 트윈을 시작한다.
 * @private
 */
_startGlitchTween() {
  this.time.addEvent({
    delay: 2500,
    loop: true,
    callback: () => {
      // 짧은 글리치: 마젠타/시안 레이어를 랜덤 오프셋으로 0.08초 튐
