      this._titleGlitchMag.setPosition(GAME_WIDTH / 2 + ox - 2, 30 + oy);
      this._titleGlitchCyan.setPosition(GAME_WIDTH / 2 - ox + 2, 30 - oy);
      this._titleGlitchMag.setAlpha(0.8);
      this._titleGlitchCyan.setAlpha(0.7);
      this.time.delayedCall(80, () => {
        this._titleGlitchMag.setPosition(GAME_WIDTH / 2 - 2, 30);
        this._titleGlitchCyan.setPosition(GAME_WIDTH / 2 + 2, 30);
        this._titleGlitchMag.setAlpha(0.5);
        this._titleGlitchCyan.setAlpha(0.4);
      });
    },
  });
}
