##### `_createDroneSlots()` 교체

현재: `Graphics.fillRoundedRect`
변경: `this.add.nineslice()` + 등급 글로우 + 빈 슬롯 점선+"+"

```javascript
_createDroneSlots(centerX) {
  const equippedChips = SaveManager.getEquippedChips();
  const inventory = SaveManager.getDroneChipInventory();
  const droneCount = this._getDroneCount();

  this._droneSlotTexts = [];

  for (let i = 0; i < 3; i++) {
    const sx = centerX - 100 + i * 100;
    const sy = 83;  // 슬롯 중앙 y
    const isLocked = i >= droneCount;

    // 9-slice 프레임 (96×80 → 70×55로 표시)
    const slotFrame = this.add.nineslice(sx, sy, 'drone_slot_frame', null, 70, 55, 16, 16, 16, 16)
      .setOrigin(0.5)
      .setAlpha(isLocked ? 0.3 : 0.85)
      .setDepth(3);

    // 드론 번호 레이블
    const label = isLocked ? `🔒 ${i + 1}` : `드론 ${i + 1}`;
    this.add.text(sx, sy - 13, label, {
      fontSize: '10px', fontFamily: 'Galmuri11, monospace',
      color: isLocked ? UI_COLORS.textSecondary : UI_COLORS.textMuted,
    }).setOrigin(0.5).setDepth(4);

    // 장착 칩 표시 또는 빈 슬롯 "+"
    let chipLabel = '';
    let chipColor = UI_COLORS.textSecondary;
    let glowColor = null;

    if (!isLocked) {
      if (equippedChips[i]) {
        const chipItem = inventory.find(c => c.uid === equippedChips[i]);
        if (chipItem) {
          const def = getChipDef(chipItem.chipId);
          const gi = getGradeInfo(chipItem.grade);
          chipLabel = `${chipItem.grade} ${def ? def.icon : '?'}`;
          chipColor = gi ? gi.color : '#FFFFFF';
          glowColor = gi ? gi.colorHex : null;
        }
      } else {
        // 빈 슬롯: 점선 박스 + "+"
        chipLabel = '+';
        chipColor = UI_COLORS.textSecondary;
        // 점선 효과: Graphics로 점선 사각형 그리기
        this._drawDashedSlotBorder(sx, sy);
      }
    }

    const chipText = this.add.text(sx, sy + 8, chipLabel || '---', {
      fontSize: chipLabel === '+' ? '18px' : '11px',
      fontFamily: 'Galmuri11, monospace',
      color: chipColor,
    }).setOrigin(0.5).setDepth(4);

    // 등급 글로우: 장착 칩이 있을 때 슬롯 테두리 색상 강조
    if (glowColor && !isLocked) {
      slotFrame.setTint(glowColor);
    }

    this._droneSlotTexts.push(chipText);

    // 터치 영역 (기존 유지)
    if (!isLocked) {
      const zone = this.add.zone(sx, sy, 70, 55).setInteractive({ useHandCursor: true }).setDepth(5);
      zone.on('pointerdown', () => {
        if (this._activeTab === 'equip') {
          this._selectedDrone = i;
          this._onActionButton();
        }
      });
    }
  }
}

/**
 * 빈 드론 슬롯 점선 테두리를 그린다.
 * @param {number} cx - 슬롯 중앙 X
 * @param {number} cy - 슬롯 중앙 Y
 * @private
 */
_drawDashedSlotBorder(cx, cy) {
  const gfx = this.add.graphics().setDepth(3);
  const x = cx - 35, y = cy - 27, w = 70, h = 55;
  const dash = 6, gap = 4;
  gfx.lineStyle(1, 0x444466, 0.8);
  // 상단 / 하단 점선
  for (let dx = x; dx < x + w; dx += dash + gap) {
    gfx.strokeLineShape(new Phaser.Geom.Line(dx, y, Math.min(dx + dash, x + w), y));
    gfx.strokeLineShape(new Phaser.Geom.Line(dx, y + h, Math.min(dx + dash, x + w), y + h));
  }
  // 좌측 / 우측 점선
  for (let dy = y; dy < y + h; dy += dash + gap) {
    gfx.strokeLineShape(new Phaser.Geom.Line(x, dy, x, Math.min(dy + dash, y + h)));
    gfx.strokeLineShape(new Phaser.Geom.Line(x + w, dy, x + w, Math.min(dy + dash, y + h)));
  }
}
```

##### `_createTabBar()` 교체

현재: 텍스트 배경색 변경
변경: 9-slice pill 컨테이너 + 활성 pill 오버레이 + 글로우 언더라인

```javascript
_createTabBar(centerX) {
  const TAB_BAR_W = 320;
  const TAB_BAR_H = 36;
  const TAB_Y = 170;

  // 탭 바 pill 컨테이너 (9-slice)
  this.add.nineslice(centerX, TAB_Y, 'tab_bar_bg', null, TAB_BAR_W, TAB_BAR_H, 18, 18, 6, 6)
    .setOrigin(0.5).setDepth(5);

  // 각 탭 너비 계산
  const tabWidth = TAB_BAR_W / TABS.length;  // 80px each
  const startX = centerX - TAB_BAR_W / 2 + tabWidth / 2;

  this._tabTexts = [];
  this._tabActivePills = [];

  TABS.forEach((tab, idx) => {
    const tx = startX + idx * tabWidth;
    const isActive = tab === this._activeTab;

    // 활성 탭 pill 오버레이 (9-slice)
    const activePill = this.add.nineslice(tx, TAB_Y, 'tab_active_pill', null, tabWidth - 4, TAB_BAR_H - 4, 18, 18, 6, 8)
      .setOrigin(0.5).setAlpha(isActive ? 1 : 0).setDepth(6);
    this._tabActivePills.push({ pill: activePill, tab });

    // 글로우 언더라인 (Graphics, 활성 탭 하단)
    const underlineGfx = this.add.graphics().setDepth(7);
    if (isActive) {
      underlineGfx.fillStyle(0x00FFFF, 0.9);
      underlineGfx.fillRect(tx - tabWidth / 2 + 8, TAB_Y + TAB_BAR_H / 2 - 3, tabWidth - 16, 2);
    }
    this._tabActivePills[idx].underlineGfx = underlineGfx;

    // 탭 텍스트
    const text = this.add.text(tx, TAB_Y, t(`chip.tab.${tab}`), {
      fontSize: '11px', fontFamily: 'Galmuri11, monospace',
      color: isActive ? UI_COLORS.neonCyan : UI_COLORS.textSecondary,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true }).setDepth(8);

    text.on('pointerdown', () => {
      this._activeTab = tab;
      this._selectedChips.clear();
      this._selectedDrone = null;
      this._refreshTabHighlight();
      this._refreshList();
    });

    this._tabTexts.push({ text, tab });
  });
}

/**
 * 탭 하이라이트를 갱신한다 (pill 알파 + 언더라인 + 텍스트 색상).
 * @private
 */
_refreshTabHighlight() {
  const TAB_Y = 170;
  const TAB_BAR_W = 320;
  const tabWidth = TAB_BAR_W / TABS.length;
  const startX = GAME_WIDTH / 2 - TAB_BAR_W / 2 + tabWidth / 2;

  this._tabTexts.forEach(({ text, tab }) => {
    const isActive = tab === this._activeTab;
    text.setColor(isActive ? UI_COLORS.neonCyan : UI_COLORS.textSecondary);
  });

  this._tabActivePills.forEach(({ pill, tab, underlineGfx }, idx) => {
    const isActive = tab === this._activeTab;
    pill.setAlpha(isActive ? 1 : 0);
    underlineGfx.clear();
    if (isActive) {
      const tx = startX + idx * tabWidth;
      underlineGfx.fillStyle(0x00FFFF, 0.9);
      underlineGfx.fillRect(tx - tabWidth / 2 + 8, TAB_Y + 14, tabWidth - 16, 2);
    }
  });
}
```

