##### `_renderCards()` 교체

현재: `Graphics.fillRoundedRect` 단색 카드
변경: 9-slice 텍스처 카드 + 상단 등급 바 텍스트 오버레이 + S/A 펄스 트윈

```javascript
_renderCards(items, equippedUids) {
  const startX = (GAME_WIDTH - (CARDS_PER_ROW * (CARD_W + CARD_GAP) - CARD_GAP)) / 2 + CARD_W / 2;

  items.forEach((item, idx) => {
    const row = Math.floor(idx / CARDS_PER_ROW);
    const col = idx % CARDS_PER_ROW;
    const cx = startX + col * (CARD_W + CARD_GAP);
    const cy = LIST_Y_START + row * (CARD_H + CARD_GAP) + CARD_H / 2;

    const chipId = item.chipId || (item.group ? item.group.chipId : '?');
    const grade  = item.grade  || (item.group ? item.group.grade  : 'C');
    const uid    = item.uid || null;
    const isGroup = !!item.group;

    const def       = getChipDef(chipId);
    const gradeInfo = getGradeInfo(grade);
    const isSelected = uid
      ? this._selectedChips.has(uid)
      : (isGroup && this._selectedChips.has(item.groupKey));
    const isEquipped = uid ? equippedUids.has(uid) : false;

    // ── 카드 배경 (9-slice 텍스처) ──
    const cardTexKey = `chip_card_bg_${grade}`;
    // CARD_W=80, CARD_H=100. 텍스처 96×112 → 80×100으로 9-slice 표시
    const card = this.add.nineslice(cx, cy, cardTexKey, null, CARD_W, CARD_H, 12, 12, 18, 12)
      .setOrigin(0.5).setDepth(10);
    this._listContainer.add(card);

    // 선택 시 추가 테두리 강조 (Graphics 오버레이)
    if (isSelected) {
      const selGfx = this.add.graphics().setDepth(11);
      selGfx.lineStyle(2, 0x39FF14, 0.9);
      selGfx.strokeRoundedRect(cx - CARD_W / 2, cy - CARD_H / 2, CARD_W, CARD_H, 6);
      this._listContainer.add(selGfx);
    }

    // ── 상단 등급 바 텍스트 (카드 상단 8px 영역 위에 등급 표시) ──
    const gradeBarText = this.add.text(cx, cy - CARD_H / 2 + 9, grade, {
      fontSize: '9px', fontFamily: 'Galmuri11, monospace',
      color: '#000000',
      fontStyle: 'bold',
    }).setOrigin(0.5).setDepth(12);
    this._listContainer.add(gradeBarText);

    // ── 아이콘 ──
    const icon = def ? def.icon : '?';
    const iconText = this.add.text(cx, cy - 22, icon, {
      fontSize: '22px', fontFamily: 'Galmuri11, monospace',
      color: gradeInfo ? gradeInfo.color : '#FFFFFF',
    }).setOrigin(0.5).setDepth(12);
    this._listContainer.add(iconText);

    // ── 등급 텍스트 ──
    const gradeText = this.add.text(cx, cy + 4, grade, {
      fontSize: '16px', fontFamily: 'Galmuri11, monospace',
      color: gradeInfo ? gradeInfo.color : '#FFFFFF',
      fontStyle: 'bold',
    }).setOrigin(0.5).setDepth(12);
    this._listContainer.add(gradeText);

    // ── 이름 텍스트 ──
    const nameKey = def ? def.nameKey : chipId;
    const nameText = this.add.text(cx, cy + 26, t(nameKey), {
      fontSize: '9px', fontFamily: 'Galmuri11, monospace',
      color: UI_COLORS.textPrimary,
    }).setOrigin(0.5).setDepth(12);
    this._listContainer.add(nameText);

    // ── 합성 탭: 수량 표시 ──
    if (isGroup) {
      const countText = this.add.text(cx + CARD_W / 2 - 5, cy - CARD_H / 2 + 20, `x${item.count}`, {
        fontSize: '10px', fontFamily: 'Galmuri11, monospace',
        color: UI_COLORS.neonGreen,
      }).setOrigin(1, 0).setDepth(12);
      this._listContainer.add(countText);
    }

    // ── 장착 뱃지 ──
    if (isEquipped) {
      const eqChips = SaveManager.getEquippedChips();
      const droneIdx = Object.keys(eqChips).find(k => eqChips[k] === uid);
      const badge = this.add.text(cx - CARD_W / 2 + 5, cy - CARD_H / 2 + 20, `D${Number(droneIdx) + 1}`, {
        fontSize: '9px', fontFamily: 'Galmuri11, monospace',
        color: '#000000',
        backgroundColor: UI_COLORS.neonCyan,
        padding: { x: 2, y: 1 },
      }).setOrigin(0, 0).setDepth(13);
      this._listContainer.add(badge);
    }

    // ── S/A 등급 펄스 트윈 ──
    if (grade === 'S' || grade === 'A') {
      const pulseColor = grade === 'S' ? 0xFFD700 : 0xFF00FF;
      const pulseTween = this.tweens.add({
        targets: card,
        alpha: { from: 0.85, to: 1.0 },
        duration: grade === 'S' ? 900 : 1200,
        yoyo: true,
        repeat: -1,
        ease: 'Sine.easeInOut',
      });
      // 트윈은 tweens 관리 대상 → _refreshList에서 stopAll로 정리됨
    }

    // ── 터치 영역 (기존 유지) ──
    const zone = this.add.zone(cx, cy, CARD_W, CARD_H).setInteractive({ useHandCursor: true }).setDepth(15);
    this._listContainer.add(zone);
    zone.on('pointerdown', () => { this._onCardTap(item, isGroup); });
  });
}
```

