#### `neon-exodus/js/managers/ShopManager.js`

import에 `SHOP_REFRESH_MAX_COST` 추가.

`getTimeUntilNextRotation()` 아래에 추가:

```js
/**
 * 즉시 갱신에 필요한 크리스탈 비용을 반환한다.
 * 잔여 시간이 많을수록 비싸며, 잔여 시간 0이면 0을 반환 (버튼 숨김 처리는 씬에서).
 * @returns {number} 크리스탈 비용 (0이면 갱신 불필요)
 */
static getRefreshCost() {
  const remaining = ShopManager.getTimeUntilNextRotation();
  if (remaining <= 0) return 0;
  return Math.max(1, Math.ceil(remaining / SHOP_ROTATION_INTERVAL * SHOP_REFRESH_MAX_COST));
}
```

기존 `forceRotate()` 는 그대로 유지. (이미 ShopManager에 존재 확인됨)

---

#### `neon-exodus/js/managers/SaveManager.js`

기존 `addCrystal()` 아래에 추가:

```js
/**
 * 크리스탈을 소비한다. 잔액이 부족하면 false를 반환한다.
 * @param {number} amount - 소비할 양
 * @returns {boolean} 성공 여부
 */
static spendCrystal(amount) {
  const data = SaveManager.getData();
  const current = data.crystal || 0;
  if (amount > current) return false;
  data.crystal = current - amount;
  SaveManager.save();
  return true;
}
```

