**_updateRefreshButton():**
```js
_updateRefreshButton() {
  const cost = ShopManager.getRefreshCost();
  if (cost === 0) {
    // 잔여 시간 없음 → 버튼 전체 숨김
    this._refreshBtnBg.setVisible(false);
    this._refreshBtnText.setVisible(false);
    this._refreshBtnZone.input.enabled = false;
    return;
  }
  const canAfford = SaveManager.getCrystal() >= cost;
  this._refreshBtnBg.setVisible(true);
  this._refreshBtnText.setVisible(true);
  this._refreshBtnBg.clear();
  const color = canAfford ? COLORS.NEON_MAGENTA : UI_COLORS.btnDisabled;
  // 버튼 그리기 (fillRoundedRect x=222 y=118 w=80 h=24 radius=4)
  this._refreshBtnBg.fillStyle(color, canAfford ? 0.7 : 0.4);
  this._refreshBtnBg.fillRoundedRect(222, 118, 80, 24, 4);
  this._refreshBtnText.setText(t('shop.refresh', cost));
  this._refreshBtnText.setColor(canAfford ? UI_COLORS.neonMagenta : UI_COLORS.textSecondary);
  this._refreshBtnZone.input.enabled = canAfford;
}
```

