**변경 3: `migrateV15toV16` 함수 신규 추가 (migrateV14toV15 함수 아래)**

```js
/**
 * v15 → v16 마이그레이션.
 * Wave 5: 각 노선에 openedQuarter 필드 추가 (수요 감쇠 계산 준비용).
 * 기존 노선은 ageQuarters가 이미 올바른 값이므로 openedQuarter는 기록용으로만 추가.
 * @param {Object} data
 * @returns {Object}
 * @private
 */
function migrateV15toV16(data) {
  const q = data.quarterNumber || 1;

  for (const route of (data.routes || [])) {
    if (route.openedQuarter === undefined) {
      // 기존 노선: 현재 분기 - ageQuarters로 역산 (없으면 1)
      const age = route.ageQuarters || 0;
      route.openedQuarter = Math.max(1, q - age);
    }
  }

  data.version = 16;
  return data;
}
```

