**변경 1: `_hasInternationalRoutes(save)` 헬퍼 추가**

`_buildRouteData` 함수 아래에 추가:

```js
/**
 * 세이브 데이터에 국제선(round >= 2 도시) 노선이 있는지 확인한다.
 * @param {Object} save
 * @returns {boolean}
 * @private
 */
function _hasInternationalRoutes(save) {
  if (!save.routes || save.routes.length === 0) return false;
  const { CITY_MAP } = // getCity 또는 CITY_MAP 활용
  return save.routes.some(r => {
    const origin = getCity(r.originId);
    const dest = getCity(r.destId);
    return (origin?.round || 1) >= 2 || (dest?.round || 1) >= 2;
  });
}
```

**변경 2: `_initViews` 초기 뷰 결정 로직 수정**

기존 단순 라운드 기반 로직을 아래로 교체:

```js
// 초기 뷰 결정: 국제선 보유 여부 + 라운드 종합 판단
let initialViewId;
if (currentRound <= 1 && !_hasInternationalRoutes(save)) {
  initialViewId = 'korea';
} else if (currentRound <= 3) {
  // 국제선이 있거나 round 2+ → east-asia 기본
  initialViewId = 'east-asia';
  // 국제선 목적지 중 동아시아 밖(SIN, BKK 등)이 있으면 그 뷰로
  // (다수 국제선 시 첫 번째 국제선 목적지 기준)
  if (_hasInternationalRoutes(save)) {
    const intlRoute = save.routes?.find(r => {
      const dest = getCity(r.destId);
      return (dest?.round || 1) >= 2;
    });
    if (intlRoute) {
      const destCity = getCity(intlRoute.destId);
      if (destCity) {
        const viewForDest = getViewForCoords(destCity.lat, destCity.lng);
        if (viewForDest && viewForDest.id !== 'world') {
          initialViewId = viewForDest.id;
        }
      }
    }
  }
} else {
  initialViewId = 'world';
}
// _initViews 파라미터로 save 추가 필요: _initViews(renderer, currentRound, save)
```

- `_initViews` 함수 시그니처에 `save` 파라미터 추가
- 호출부 `_initViews(_renderer, _currentRound)` → `_initViews(_renderer, _currentRound, save)` 수정

**변경 3: 뷰 전환 버튼 HTML 추가**

`el.innerHTML = ...` 템플릿에서 `<canvas>` 위에 삽입:

```html
${_buildViewBtnsHTML(save, _currentRound)}
```

`_buildViewBtnsHTML(save, round)` 함수 추가:

```js
/**
 * 지도 우측 상단 뷰 전환 버튼 그룹 HTML을 빌드한다.
 * round < 2이고 국제선도 없으면 빈 문자열 반환.
 * @param {Object} save
 * @param {number} round
 * @returns {string}
 * @private
 */
function _buildViewBtnsHTML(save, round) {
  if (round < 2 && !_hasInternationalRoutes(save)) return '';
  const views = getAvailableViews(round);
  // world + 대륙 레벨 뷰만 표시 (korea 제외 또는 round에 따라 포함)
  const displayViews = views.filter(v => v.id === 'world' || v.round >= 1);
  return `
    <div class="map-view-btns" id="map-view-btns">
      ${displayViews.map(v =>
        `<button class="map-view-btn ${_currentViewId === v.id ? 'active' : ''}" data-view="${v.id}">${v.label}</button>`
      ).join('')}
    </div>
  `;
}
```

이벤트 바인딩 추가 (render 함수 내 이벤트 바인딩 섹션):

```js
// 뷰 전환 버튼 이벤트
el.querySelectorAll('.map-view-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    _switchToView(btn.dataset.view);
    // 버튼 활성화 상태 갱신
    el.querySelectorAll('.map-view-btn').forEach(b =>
      b.classList.toggle('active', b.dataset.view === _currentViewId)
    );
  });
});
```

주의: `_buildViewBtnsHTML` 호출 시점에 `_currentViewId`가 아직 `'world'` 초기값일 수 있으므로, `_initViews` 완료 후 버튼 상태를 갱신하는 로직 추가 필요.

