    <button class="challenge-tab ${_activeTab === 'competitor' ? 'active' : ''}" data-tab="competitor">${t('competitor_section_title')}</button>
  </div>
  <div class="screen-body" id="report-tab-content"></div>
`;
```

**변경 3: `_renderActiveTab(save)` 분기 수정**

```js
// 변경 전
function _renderActiveTab(save) {
  const contentEl = _el?.querySelector('#report-tab-content');
  if (!contentEl) return;

  if (_activeTab === 'challenge') {
    contentEl.innerHTML = _buildChallengesHTML(save);
    _bindChallengeEvents(contentEl, save);
  } else if (_activeTab === 'contract') {
    renderContractTab(contentEl);
  } else if (_activeTab === 'competitor') {
    renderCompetitorTab(contentEl);
  } else {
    contentEl.innerHTML = _buildSummaryHTML(save);
    _bindSummaryEvents(contentEl);
  }
}

// 변경 후
function _renderActiveTab(save) {
  const contentEl = _el?.querySelector('#report-tab-content');
  if (!contentEl) return;

  if (_activeTab === 'revenue') {
    contentEl.innerHTML = _buildRevenueHTML(save);
    _bindRevenueEvents(contentEl);
  } else if (_activeTab === 'goal') {
    contentEl.innerHTML = _buildGoalHTML(save);
    _bindGoalEvents(contentEl);
  } else if (_activeTab === 'challenge') {
    contentEl.innerHTML = _buildChallengesHTML(save);
    _bindChallengeEvents(contentEl, save);
  } else if (_activeTab === 'contract') {
    renderContractTab(contentEl);
  } else if (_activeTab === 'competitor') {
    renderCompetitorTab(contentEl);
  }
}
```

**변경 4: `_buildSummaryHTML` → `_buildRevenueHTML`로 분리**

기존 `_buildSummaryHTML`에서 재무 요약 + 노선별 순이익 부분만 추출한다.

```js
/**
 * 수익 탭 HTML — 재무 요약 + 노선별 순이익.
 * @param {Object} save
 * @returns {string}
 * @private
 */
function _buildRevenueHTML(save) {
  let totalRevenue = 0;
  let totalCost = 0;

  let routeRows = '';
  for (const route of save.routes) {
    const calc = tryCalcRoute(route, save);
    totalRevenue += calc.dailyRevenue;
    totalCost += calc.dailyCost;

    const net = calc.netProfit;
    const cls = net >= 0 ? 'profit' : 'loss';
    const fmt = formatRoute(route.originId, route.destId);
    routeRows += `
      <div style="display:flex;align-items:center;padding:8px 0;cursor:pointer;border-bottom:1px solid var(--border-light)" data-route="${route.id}">
        <span class="mono" style="flex:1">${fmt.originName} → ${fmt.destName} <span class="iata-caption">${fmt.originIata}/${fmt.destIata}</span></span>
        <span class="mono bold ${cls}" style="margin-right:8px">${t('currency_signed', net)}</span>
        <span style="color:var(--text-caption)">›</span>
      </div>
    `;
  }

  const totalNet = totalRevenue - totalCost;
  const totalNetCls = totalNet >= 0 ? 'profit' : 'loss';

  return `
    <div class="serif-italic caption" style="margin-bottom:12px">── ${t('tab_revenue')} ──</div>

    <div style="display:flex;justify-content:space-between;padding:4px 0">
      <span class="caption">${t('daily_revenue')}</span>
      <span class="mono profit">${t('currency_signed', totalRevenue)}</span>
    </div>
    <div style="display:flex;justify-content:space-between;padding:4px 0">
      <span class="caption">${t('daily_cost')}</span>
      <span class="mono loss">${t('currency_signed', -Math.abs(totalCost))}</span>
    </div>
    <div class="dashed-line"></div>
    <div style="display:flex;justify-content:space-between;padding:4px 0">
      <span class="bold">${t('net_profit')}</span>
      <span class="mono bold ${totalNetCls}">${t('currency_signed', totalNet)}</span>
    </div>

    <div class="dashed-line" style="margin:12px 0"></div>

    <div class="serif-italic caption" style="margin-bottom:8px">── 노선별 순이익 ──</div>
    ${save.routes.length > 0
      ? routeRows
      : '<div class="caption" style="padding:16px;text-align:center">운영 중인 노선이 없습니다</div>'
    }
    <!-- *(구현 시 AD 모드3 REVISE로 "노선별 순이익" -> t('route_profit_section'), "운영 중인 노선이 없습니다" -> t('route_no_routes') i18n 키로 교체됨)* -->
  `;
}
```

**변경 5: `_buildGoalHTML` 신규 추가**

기존 `_buildSummaryHTML`의 마일스톤 + 주가 섹션을 추출한다.

```js
/**
 * 목표 탭 HTML — 마일스톤 진척도 + IPO/주가.
 * @param {Object} save
 * @returns {string}
 * @private
 */
function _buildGoalHTML(save) {
  const milestonesHTML = _buildMilestonesHTML(save);

  return `
    <div class="serif-italic caption" style="margin-bottom:12px">── ${t('tab_goal')} ──</div>
    ${milestonesHTML}
    <div class="dashed-line" style="margin:12px 0"></div>
    ${_buildStockSection(save)}
  `;
}
```

**변경 6: 이벤트 바인딩 함수 분리**

기존 `_bindSummaryEvents(el)` 삭제 후, 두 함수로 분리:

```js
/**
 * 수익 탭의 이벤트를 바인딩한다.
 * @param {HTMLElement} el
 * @private
 */
function _bindRevenueEvents(el) {
  // 노선 행 클릭 → route-detail 이동
  el.querySelectorAll('[data-route]').forEach(row => {
    row.addEventListener('click', () => {
      navigate('route-detail', { routeId: row.dataset.route });
    });
  });
}

/**
 * 목표 탭의 이벤트를 바인딩한다.
 * @param {HTMLElement} el
 * @private
 */
function _bindGoalEvents(el) {
  // IPO 신청 버튼
  el.querySelector('#report-ipo-btn')?.addEventListener('click', () => {
    showIPOModal(() => {
      const save = getSave();
      _renderActiveTab(save);
      _el?.querySelectorAll('.challenge-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === _activeTab));
    });
  });

  // 자사주 매입 버튼
  el.querySelector('#report-buyback-btn')?.addEventListener('click', () => {
    showBuybackModal(() => {
      const save = getSave();
      _renderActiveTab(save);
      _el?.querySelectorAll('.challenge-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === _activeTab));
    });
  });
}
```

기존 `_buildSummaryHTML` 함수는 완전히 삭제한다.

#### `contrail/css/screens.css`

**변경 1: `.challenge-tab` 폰트 크기 및 패딩 조정**

5개 탭이 360px 폭에 들어가야 한다. 현재 `flex: 1`이므로 탭당 72px. 13px 폰트에서 한국어 2글자 레이블("수익", "목표", "계약") + 3~4글자("챌린지", "경쟁사")가 공존하므로 11px로 축소.

