const _renderedLabels = []; // {x, y, w, h}
function _wouldOverlap(x, y, w, h) {
  for (const r of _renderedLabels) {
    if (x < r.x + r.w && x + w > r.x && y < r.y + r.h && y + h > r.y) return true;
  }
  return false;
}
```

