  const nonDeficitCards = allCards.filter(c => c.type !== 'deficit' || c.title === '필수 목표 실패');

  // 통합 1장 추가
  const count = deficitCardRoutes.size;
  nonDeficitCards.push({
    type: 'deficit',
    icon: '📉',
    title: count === 1
      ? `${_getRouteName(save.routes.find(r => r.id === [...deficitCardRoutes][0]))} 적자`
      : `적자 노선 ${count}개`,
    body: count === 1
      ? '해당 노선이 적자 상태입니다.'
      : `${count}개 노선이 적자 상태입니다. 가격 조정 또는 폐지를 검토하세요.`,
    routeId: count === 1 ? [...deficitCardRoutes][0] : null,
    cityId: null,
    action: count === 1 ? 'respond' : null,
  });

  allCards.length = 0;
  allCards.push(...nonDeficitCards);
}
```

