#### contrail/js/save.js — prestige() 함수 추가

```js
/**
 * 프레스티지를 실행한다. SAVE-SCHEMA.md §8 기준.
 * save 객체를 직접 변경한다.
 * @param {Object} save - 현재 세이브 데이터
 */
export function prestige(save) {
  const now = Date.now();
  const today = new Date().toISOString().slice(0, 10);

  // ── 유지 필드 백업 ──
  const airlineName = save.airline.name;
  const progression = save.progression; // 이미 RP/업그레이드 반영 완료 상태
  const settings = save.settings;
  const retention = save.retention;

  // ── 프레스티지 카운트 증가 ──
  progression.prestigeCount += 1;
  const round = progression.prestigeCount + 1; // 2회차

  // ── 시작 자금 계산 (RP 보너스 적용) ──
  const baseFunds = 75000;
  const fundsMultiplier = Math.pow(1.20, progression.rpUpgrades.startingFunds);
  const startingFunds = Math.round(baseFunds * fundsMultiplier);

  // ── 리셋 필드 ──
  save.version = SAVE_VERSION;
  save.createdAt = now;
  save.lastTickAt = now;
  save.playTime = 0;

  save.airline = { name: airlineName, hubAirportId: null };
  save.funds = startingFunds;
  save.reputation = 50;
  save.aircraft = [{ id: 'ac_001', typeId: 'turboprop50', assignedRouteId: null }];
  save.routes = [];

  // ── airports: 국내 15개 + 국제 8개 ──
  save.airports = [
    { cityId: 'GMP', unlocked: true },
    { cityId: 'PUS', unlocked: true },
    { cityId: 'CJU', unlocked: true },
    { cityId: 'ICN', unlocked: true },
    { cityId: 'TAE', unlocked: false },
    { cityId: 'KWJ', unlocked: false },
    { cityId: 'TJN', unlocked: false },
    { cityId: 'CJJ', unlocked: false },
    { cityId: 'USN', unlocked: false },
    { cityId: 'RSU', unlocked: false },
    { cityId: 'KPO', unlocked: false },
    { cityId: 'KUV', unlocked: false },
    { cityId: 'WJU', unlocked: false },
    { cityId: 'HIN', unlocked: false },
    { cityId: 'YNY', unlocked: false },
    // 2회차 국제선 도시
    { cityId: 'NRT', unlocked: false },
    { cityId: 'KIX', unlocked: false },
    { cityId: 'FUK', unlocked: false },
    { cityId: 'NGO', unlocked: false },
    { cityId: 'CTS', unlocked: false },
    { cityId: 'PVG', unlocked: false },
    { cityId: 'PEK', unlocked: false },
    { cityId: 'TPE', unlocked: false },
  ];

  save.market = {
    oilPrice: 75,
    oilHistory: [75],
    gameDay: 0,
    currentSeason: 0,
    activeEvents: [],
    eventCooldown: 7,
  };
  save.competitors = [];

  // ── 유지 필드 복원 ──
  progression.unlockedCities = ['GMP', 'PUS', 'CJU', 'ICN'];
  progression.milestones = [];
  save.progression = progression;

  save.onboarding = { completed: true, currentStep: 5 }; // 2회차 온보딩 스킵
  save.stats = {
    totalRevenue: 0, totalProfit: 0, totalFlights: 0, totalPassengers: 0,
    routesOpened: 0, citiesServed: 0, maxConcurrentRoutes: 0,
    aircraftPurchased: 1, competitorsExpelled: 0,
  };
  save.retention = retention; // 연속 접속 유지
  save.strike = null;
  save.briefing = null;
  save.activePolicy = null;
  save.settings = settings; // 유저 설정 유지
}
```

