// 기존 adjustedDemand 계산 후 RP demandBonus 추가
const rpDemandMult = 1 + 0.05 * (save.progression?.rpUpgrades?.demandBonus || 0);
const adjustedDemand = baseDemand * priceCoeff * seasonCoeff * competitionCoeff * hubCoeff * reputationCoeff * rpDemandMult;

// dailyMaintenance에 RP maintenanceEff 적용
const rpMaintMult = 1 - 0.05 * (save.progression?.rpUpgrades?.maintenanceEff || 0);
