**국제선 도시 해금 로직:**
`_updateStats()` 또는 시뮬 후 별도 함수에서:

```js
/**
 * 2회차 국제선 도시 순차 해금.
 * @param {Object} save
 */
function _checkInternationalUnlock(save) {
  if ((save.progression?.prestigeCount || 0) < 1) return; // 1회차에서는 무시

  const domesticRoutes = save.routes.filter(r => {
    // 국내선 도시끼리의 노선만 카운트
    const DOMESTIC = new Set(['GMP','PUS','CJU','ICN','TAE','KWJ','TJN','CJJ','USN','RSU','KPO','KUV','WJU','HIN','YNY']);
    return DOMESTIC.has(r.originId) && DOMESTIC.has(r.destId);
  }).length;

  // 해금 임계값 테이블
  const THRESHOLDS = [
    { routes: 7,  cities: ['FUK'] },
    { routes: 8,  cities: ['KIX'] },
    { routes: 9,  cities: ['PVG', 'NGO'] },
    { routes: 10, cities: ['NRT', 'PEK'] },
    { routes: 11, cities: ['TPE', 'CTS'] },
  ];

  for (const t of THRESHOLDS) {
    if (domesticRoutes >= t.routes) {
      for (const cityId of t.cities) {
        const airport = save.airports.find(a => a.cityId === cityId);
        if (airport && !airport.unlocked) {
          airport.unlocked = true;
          if (!save.progression.unlockedCities.includes(cityId)) {
            save.progression.unlockedCities.push(cityId);
          }
        }
      }
    }
  }
}
```

이 함수는 `runSimulation()` 틱 루프 끝(stats 업데이트 후)에서 호출.
또한 `route-open.js`의 `_confirmOpen()` 직후에도 호출하여 실시간 해금 반영.

