  // stageClears 구조 변환: { stage_1: 3 } → { stage_1: { normal: 3, hard: 0, nightmare: 0 } }
  if (data.stageClears) {
    const old = data.stageClears;
    const converted = {};
    for (const [stageId, count] of Object.entries(old)) {
      if (typeof count === 'number') {
        converted[stageId] = { normal: count, hard: 0, nightmare: 0 };
      } else {
        converted[stageId] = count; // 이미 변환됨
      }
    }
    data.stageClears = converted;
  }
  if (!data.selectedDifficulty) data.selectedDifficulty = 'normal';
  data.version = 11;
}
```

#### API 변경

| 기존 API | 변경 후 |
|---------|--------|
| `clearStage(stageId)` | `clearStage(stageId, difficulty = 'normal')` |
| `isStageClear(stageId)` | `isStageClear(stageId, difficulty = 'normal')` |
| `getStageClearCount(stageId)` | `getStageClearCount(stageId, difficulty = null)` — null이면 전 난이도 합산 |

신규 메서드:
- `getSelectedDifficulty()` → 현재 선택된 난이도 문자열 반환
- `setSelectedDifficulty(diff)` → 선택된 난이도 저장
- `isDifficultyUnlocked(stageId, difficulty)` → 해당 스테이지의 난이도 해금 여부

```javascript
static isDifficultyUnlocked(stageId, difficulty) {
  if (difficulty === 'normal') return true;
  if (difficulty === 'hard') return SaveManager.isStageClear(stageId, 'normal');
  if (difficulty === 'nightmare') return SaveManager.isStageClear(stageId, 'hard');
  return false;
}
```

#### 호출부 수정 목록

| 파일 | 현재 호출 | 수정 |
|------|---------|------|
| `StageSelectScene.js:95` | `isStageClear(stageData.unlocksAfter)` | `isStageClear(stageData.unlocksAfter, 'normal')` (스테이지 해금은 normal 기준) |
| `StageSelectScene.js:109` | `getStageClearCount(stageData.id)` | `getStageClearCount(stageData.id)` (합산이므로 변경 없음) |
| `GameScene.js:1688` | `clearStage(this.stageId)` | `clearStage(this.stageId, this.difficulty)` |
| `AchievementManager.js:287` | `getStageClearCount(condition.stageId) >= 1` | 변경 없음 (합산) |
| `AchievementManager.js:290` | `getStageClearCount(id) >= 1` | 변경 없음 (합산) |

