// ── 무기 드롭 시스템 ──

/**
 * 게임 시작 시 스테이지 무기를 맵 랜덤 위치에 단일 배치한다.
 * 플레이어 시작 위치에서 최소 300px 이상, 월드 경계에서 100px 마진을 유지한다.
 * 조건 충족 위치를 최대 20회 재시도하며, 초과 시 안전 폴백 위치를 사용한다.
 * @private
 */
_placeWeaponOnMap() {
  if (!this.stageData || !this.stageData.unlockWeaponId) return;

  const weaponId = this.stageData.unlockWeaponId;
  const margin = WEAPON_DROP_MARGIN;
  const minDist = WEAPON_DROP_MIN_DIST_FROM_PLAYER;
  const cx = WORLD_WIDTH / 2;
  const cy = WORLD_HEIGHT / 2;

  let x, y;
  let attempts = 0;
  const maxAttempts = 20;

  do {
    x = Phaser.Math.Between(margin, WORLD_WIDTH - margin);
    y = Phaser.Math.Between(margin, WORLD_HEIGHT - margin);
    attempts++;
  } while (
    Phaser.Math.Distance.Between(x, y, cx, cy) < minDist &&
    attempts < maxAttempts
  );

  // 재시도 초과 시 안전 폴백: 월드 좌상단 마진 지점 (플레이어 시작 위치에서 약 1273px 이격)
  // 주의: WORLD_WIDTH - cx = 1000이므로 플레이어 시작 위치와 동일해지는 오류를 피하기 위해 margin 좌표 사용
  if (attempts >= maxAttempts) {
    x = margin;
    y = margin;
  }

  const drop = this.weaponDropPool.get(x, y);
  if (drop) {
    drop.spawn(x, y, weaponId, true);
    this._showWarning(t('weaponDrop.appeared'), 'info');
  }
}

/**
 * 플레이어가 무기 드롭 아이템을 수집했을 때 처리한다.
 * @param {import('../entities/Player.js').default} player - 플레이어
 * @param {import('../entities/WeaponDropItem.js').default} drop - 무기 드롭 아이템
 * @private
 */
_onCollectWeaponDrop(player, drop) {
  // 기존 로직 그대로 유지
  ...
}
```

`_checkWeaponDropSchedule()`, `_spawnWeaponDrop()` 메서드 삭제.

#### `neon-exodus/js/entities/WeaponDropItem.js`

`spawn()` 메서드 내 ±80px 랜덤 오프셋 제거:
```javascript
// 삭제:
const offsetX = Phaser.Math.Between(-80, 80);
const offsetY = Phaser.Math.Between(-80, 80);
this.setPosition(x + offsetX, y + offsetY);

// 교체:
this.setPosition(x, y);
```
이유: 배치 위치가 이미 충분한 랜덤성을 가지므로 추가 오프셋이 불필요하고, 거리 조건 계산과의 정합성을 위해 정확한 좌표를 사용한다.

#### `neon-exodus/js/config.js`

`AUTO_HUNT` 객체의 `weaponDropSearchRadius` 값을 맵 전체 탐색이 가능한 수치로 확장:
```javascript
// 변경 전
weaponDropSearchRadius: 400,
// 변경 후 (월드 대각선 길이 ≈ 2828px, 여유를 두어 3000 설정)
weaponDropSearchRadius: 3000,
```

`weaponDropUrgentLifetime`과 긴급 수집 관련 상수는 유지 (permanent=true 아이템은 `_evaluateWeaponDropUrgent` 내 조건 `if (item.permanent ...)` 에 의해 자동으로 무시됨, 코드 삭제 불필요).

새 상수를 `// ── 스폰 설정 ──` 섹션 하단에 추가:
```javascript
/** 무기 드롭 맵 배치 시 월드 경계 마진 (px) */
export const WEAPON_DROP_MARGIN = 100;

/** 무기 드롭 맵 배치 시 플레이어 시작 위치와의 최소 이격 거리 (px) */
export const WEAPON_DROP_MIN_DIST_FROM_PLAYER = 300;
```

`GameScene.js` import에 두 상수 추가:
```javascript
import {
  ...
  WEAPON_DROP_MARGIN,
  WEAPON_DROP_MIN_DIST_FROM_PLAYER,
} from '../config.js';
```

### 의존성
- 추가 패키지 없음
- Phaser.Math.Between, Phaser.Math.Distance.Between — 기존 사용 중

## 수용 기준 (Acceptance Criteria)
- [ ] `stages.js`에 `WEAPON_DROP_SCHEDULE` 상수가 존재하지 않는다
- [ ] `GameScene.js`에 `_checkWeaponDropSchedule`, `_spawnWeaponDrop` 메서드가 존재하지 않는다
- [ ] `GameScene.js` update() 내에 `_checkWeaponDropSchedule()` 호출이 존재하지 않는다
- [ ] 게임 시작 직후(create 완료 시) weaponDropPool에 active 아이템 1개가 존재한다
- [ ] 해당 아이템의 `permanent === true`이다
- [ ] 아이템 위치가 (100, 100) ~ (1900, 1900) 범위 내이다
- [ ] 아이템 위치가 (1000, 1000)에서 300px 이상 이격되어 있다 (폴백 예외 허용)
- [ ] AutoPilotSystem이 활성화된 상태에서 무기 위치 방향으로 이동한다
- [ ] 아이템에 도달하면 `_stageWeaponCollected = true`가 되고 이후 추가 스폰이 없다
- [ ] 수집 알림 및 VFX/SFX가 기존과 동일하게 발생한다
- [ ] WeaponDropItem.spawn() 호출 시 인수로 전달한 x, y가 그대로 setPosition에 사용된다

## Art Director 실행 계획
- visual_change: none
- AD 모드 1 (에셋 컨셉): 해당 없음 — visual_change: none, 에셋 신규 생성 없음
- AD 모드 2 (에셋 검증): 해당 없음 — visual_change: none
- AD 모드 3 (UI 레이아웃): 해당 없음 — visual_change: none, UI 변경 없음

## 제약사항
- WeaponDropItem의 렌더링, VFX, SFX 변경 금지 (Out of Scope)
- 스테이지 unlockWeaponId 구조 변경 금지
- 수집 후 처리 로직(_onCollectWeaponDrop) 변경 금지
- 복수 무기 배치 구현 금지 (항상 단일 드롭)
- 미니맵/레이더 위치 힌트 UI 추가 금지

## 참고사항
- 플레이어 시작 위치: `WORLD_WIDTH / 2 = 1000`, `WORLD_HEIGHT / 2 = 1000` (GameScene.js 138번 라인)
- 맵 대각선 길이: `Math.sqrt(2000² + 2000²) ≈ 2828px` → weaponDropSearchRadius: 3000으로 커버
- `_evaluateWeaponDropUrgent`는 `item.permanent === true` 조건으로 자동 스킵됨 (AutoPilotSystem.js 267번 라인)
- ObjectPool.get(x, y)는 비활성 인스턴스를 반환하고 해당 위치로 이동시킴; spawn()은 setPosition으로 덮어씀
