##### 3. _enterMoveMode(slotIndex) — 신규 메서드

팝업을 닫고 이동 모드로 진입한다. 원점 슬롯을 기록하고 모든 슬롯에 하이라이트 오버레이를 그린다.

```js
/**
 * 머신 이동 모드에 진입한다.
 * 팝업을 닫고, 원점 슬롯을 기록하며, 슬롯에 하이라이트 오버레이를 표시한다.
 * @param {number} slotIndex - 이동할 머신의 원점 슬롯 인덱스
 * @private
 */
_enterMoveMode(slotIndex) {
  this._closePopup();

  this._moveMode = true;
  this._movingSlotIndex = slotIndex;

  // 하이라이트 오버레이 그리기
  this._drawMoveHighlights();

  // 취소 버튼 표시
  this._showMoveCancelButton();
}
```

##### 4. _drawMoveHighlights() — 신규 메서드

현재 플로어의 모든 슬롯에 대해 하이라이트 오버레이를 생성한다.

```js
/**
 * 이동 모드 하이라이트 오버레이를 모든 슬롯 위에 그린다.
 * - 원점 슬롯: NEON_GREEN (0x39FF14), alpha 0.3
 * - 빈 슬롯: NEON_CYAN (0x00FFFF), alpha 0.3
 * - 다른 머신 슬롯: NEON_ORANGE (0xFF6600), alpha 0.3
 * @private
 */
_drawMoveHighlights() {
  this._clearMoveHighlights();

  const machines = this._getActiveMachines();
  const defaultFloor = this._getDefaultFloor();

  for (const slot of this._slots) {
    const { x, y, index } = slot;
    const half = SLOT_SIZE / 2;

    let color;
    if (index === this._movingSlotIndex) {
      // 원점 슬롯: 녹색
      color = COLORS.NEON_GREEN;
    } else {
      const hasMachine = machines.some(
        m => m.slotIndex === index && (m.floorId || defaultFloor) === this._currentFloor
      );
      color = hasMachine ? COLORS.NEON_ORANGE : COLORS.NEON_CYAN;
    }

    const highlight = this.add.graphics();
    highlight.fillStyle(color, 0.3);
    highlight.fillRoundedRect(x - half, y - half, SLOT_SIZE, SLOT_SIZE, 6);
    highlight.setDepth(15);
    this._moveHighlights.push(highlight);
  }
}
```

##### 5. _clearMoveHighlights() — 신규 메서드

```js
/**
 * 이동 모드 하이라이트 오버레이를 모두 제거한다.
 * @private
 */
_clearMoveHighlights() {
  for (const h of this._moveHighlights) {
    if (h && !h.destroyed) h.destroy();
  }
  this._moveHighlights = [];
}
```

