_onSlotTap(slotIndex) {
  if (this._popup) return;

  const slot = this._slots[slotIndex];

  // ── 이동 모드 처리 ──
  if (this._moveMode) {
    if (slotIndex === this._movingSlotIndex) {
      // 원점 슬롯 재탭 → 이동 취소
      this._exitMoveMode();
      return;
    }
    this._executeMachineMove(this._movingSlotIndex, slotIndex);
    return;
