##### 10. _executeMachineMove(fromSlot, toSlot) — 신규 메서드

실제 이동 또는 교환(swap) 로직을 수행한다.

```js
/**
 * 머신을 fromSlot에서 toSlot으로 이동하거나 교환(swap)한다.
 * 이동 완료 후 벨트를 재계산하고 슬롯 그리드를 재구성한다.
 * @param {number} fromSlot - 이동 원점 슬롯 인덱스
 * @param {number} toSlot - 이동 대상 슬롯 인덱스
 * @private
 */
_executeMachineMove(fromSlot, toSlot) {
  const machines = this._getActiveMachines();
  const defaultFloor = this._getDefaultFloor();
  const currentFloor = this._currentFloor;

  const fromMachine = machines.find(
    m => m.slotIndex === fromSlot && (m.floorId || defaultFloor) === currentFloor
  );
  if (!fromMachine) {
    this._exitMoveMode();
    return;
  }

  const toMachine = machines.find(
    m => m.slotIndex === toSlot && (m.floorId || defaultFloor) === currentFloor
  );

  // ── 벨트 업데이트 ──
  const belts = this._getActiveBelts();

  if (toMachine) {
    // --- 교환(swap) ---
    // 1. 벨트에서 from/to 슬롯 인덱스를 서로 교체
    for (const belt of belts) {
      if (belt.floorId !== currentFloor) continue;
      let newFrom = belt.fromSlot;
      let newTo = belt.toSlot;
      let changed = false;

      if (belt.fromSlot === fromSlot) { newFrom = toSlot; changed = true; }
      else if (belt.fromSlot === toSlot) { newFrom = fromSlot; changed = true; }

      if (belt.toSlot === fromSlot) { newTo = toSlot; changed = true; }
      else if (belt.toSlot === toSlot) { newTo = fromSlot; changed = true; }

      if (changed) {
        belt.fromSlot = newFrom;
        belt.toSlot = newTo;
      }
    }

    // 2. 머신 슬롯 인덱스 교환
    fromMachine.slotIndex = toSlot;
    toMachine.slotIndex = fromSlot;
  } else {
    // --- 빈 슬롯으로 이동 ---
    // 1. 기존 벨트에서 fromSlot -> toSlot으로 인덱스 업데이트
    for (const belt of belts) {
      if (belt.floorId !== currentFloor) continue;
      if (belt.fromSlot === fromSlot) belt.fromSlot = toSlot;
      if (belt.toSlot === fromSlot) belt.toSlot = toSlot;
    }

    // 2. 머신 슬롯 인덱스 변경
    fromMachine.slotIndex = toSlot;
  }

  // ── 매니저 갱신 ──
  // Coder 구현 시 _getAssignedProdManager 로직을 확인하여,
  // 매니저 배정이 slotIndex 기반이면 해당 값도 교체할 것.

  // ── UI 재구성 ──
  this._rebuildSlotGrid();
  this._renderBelts();

  // ── 이동 모드 종료 ──
  this._exitMoveMode();

  // ── 피드백 ──
  this._showFeedback(t(toMachine ? 'move.swapped' : 'move.moved'));

  // ── 즉시 저장 ──
  this._autoSave();
}
```
