## 2. BootScene.js 변경

### 2-1. `_buildPngKeySet()` 확장
기존 머신 7종에 자원 7종 + 탭 6종 + UI 5종 = 18종 추가.

```javascript
_buildPngKeySet() {
  this._pngKeys = new Set();
  // 구역1 머신 PNG 7종 (Phase 1)
  const zone1Machines = ['miner', 'smelter', 'ecell', 'assembler', 'nanofab', 'aicore', 'qproc'];
  for (const id of zone1Machines) this._pngKeys.add('machine-' + id);

  // Phase 2: 자원 7종
  const zone1Resources = ['ore', 'metal', 'parts', 'energy', 'nanochip', 'data', 'qbit'];
  for (const id of zone1Resources) this._pngKeys.add('resource-' + id);

  // Phase 2: 탭 6종
  const tabs = ['factory', 'bp', 'manager', 'research', 'codex', 'stats'];
  for (const id of tabs) this._pngKeys.add('tab-' + id);

  // Phase 2: UI 5종
  const uis = ['coin', 'diamond', 'prestige', 'star', 'gear'];
  for (const id of uis) this._pngKeys.add('ui-' + id);
}
```

### 2-2. `_loadPngAssets()` 확장
3개 카테고리 PNG 로딩 추가 + loaderror fallback 범용화.

```javascript
_loadPngAssets() {
  // Phase 1: 머신
  const zone1Machines = ['miner', 'smelter', 'ecell', 'assembler', 'nanofab', 'aicore', 'qproc'];
  for (const id of zone1Machines) {
    this.load.image('machine-' + id, 'assets/images/machines/' + id + '.png');
  }

  // Phase 2: 자원
  const zone1Resources = ['ore', 'metal', 'parts', 'energy', 'nanochip', 'data', 'qbit'];
  for (const id of zone1Resources) {
    this.load.image('resource-' + id, 'assets/images/resources/' + id + '.png');
  }

  // Phase 2: 탭
  const tabs = ['factory', 'bp', 'manager', 'research', 'codex', 'stats'];
  for (const id of tabs) {
    this.load.image('tab-' + id, 'assets/images/tabs/' + id + '.png');
  }

  // Phase 2: UI
  const uis = ['coin', 'diamond', 'prestige', 'star', 'gear'];
  for (const id of uis) {
    this.load.image('ui-' + id, 'assets/images/ui/' + id + '.png');
  }

  // PNG 로드 실패 시 SVG fallback (범용)
  this.load.on('loaderror', (file) => {
    if (!file.key || !this._pngKeys.has(file.key)) return;

    // 키에서 prefix와 id 분리
    let svgSource = null;
    if (file.key.startsWith('machine-')) {
      svgSource = MACHINE_ICONS[file.key.replace('machine-', '')];
    } else if (file.key.startsWith('resource-')) {
      svgSource = RESOURCE_ICONS[file.key.replace('resource-', '')];
    } else if (file.key.startsWith('tab-')) {
      // tab-research는 icons.js에 없으므로 enhance 폴백
      const tabId = file.key.replace('tab-', '');
      svgSource = TAB_ICONS[tabId] || TAB_ICONS['enhance'];
    } else if (file.key.startsWith('ui-')) {
      svgSource = UI_ICONS[file.key.replace('ui-', '')];
    }

    if (svgSource) {
      const dataUrl = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgSource)));
      this.textures.addBase64(file.key, dataUrl);
    }
  });
}
```

