## 3. GameScene.js — 머신별 특화 트윈

### 3-1. `_startMachineTween()` 리팩토링
현재 모든 머신에 동일한 트윈(x±1 진동 + alpha 글로우)을 적용하는 구조에서,
machineId를 파라미터로 받아 머신별 고유 트윈을 적용하도록 변경.

```javascript
_startMachineTween(slot, icon, machineId) {
  this._stopMachineTween(slot);
  const originX = icon.x;
  const originY = icon.y;

  switch (machineId) {
    case 'miner':
      // 드릴 작동: Y축 미세 진동
      slot.vibTween = this.tweens.add({
        targets: icon,
        y: { from: originY - 1, to: originY + 1 },
        duration: 80, yoyo: true, repeat: -1, ease: 'Linear',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.8 },
        duration: 1200, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    case 'smelter':
      // 용광로: 밝기 강한 글로우 펄스
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.5 },
        duration: 800, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    case 'ecell':
      // 에너지: 스케일 펄스 (충전/방전)
      slot.vibTween = this.tweens.add({
        targets: icon,
        scaleX: { from: icon.scaleX * 0.95, to: icon.scaleX * 1.05 },
        scaleY: { from: icon.scaleY * 0.95, to: icon.scaleY * 1.05 },
        duration: 1000, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.7 },
        duration: 1500, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    case 'assembler':
      // 기어 회전: 미세 각도 회전 (±3°)
      slot.vibTween = this.tweens.add({
        targets: icon,
        angle: { from: -3, to: 3 },
        duration: 600, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.8 },
        duration: 1500, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    case 'nanofab':
      // 나노 공정: 빠른 알파 깜빡임
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.3 },
        duration: 400, yoyo: true, repeat: -1, ease: 'Linear',
      });
      break;

    case 'aicore':
      // AI 연산: 느린 스케일 펄스
      slot.vibTween = this.tweens.add({
        targets: icon,
        scaleX: { from: icon.scaleX * 0.98, to: icon.scaleX * 1.02 },
        scaleY: { from: icon.scaleY * 0.98, to: icon.scaleY * 1.02 },
        duration: 2000, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.8 },
        duration: 2000, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    case 'qproc':
      // 양자 프로세서: 빠른 글로우 + X축 미세 진동
      slot.vibTween = this.tweens.add({
        targets: icon,
        x: { from: originX - 0.5, to: originX + 0.5 },
        duration: 60, yoyo: true, repeat: -1, ease: 'Linear',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.5 },
        duration: 500, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
      break;

    default:
      // 기본: Phase 1 동일 (X축 진동 + 글로우)
      slot.vibTween = this.tweens.add({
        targets: icon,
        x: { from: originX - 1, to: originX + 1 },
        duration: 100, yoyo: true, repeat: -1, ease: 'Linear',
      });
      slot.glowPulseTween = this.tweens.add({
        targets: icon, alpha: { from: 1.0, to: 0.7 },
        duration: 1500, yoyo: true, repeat: -1, ease: 'Sine.easeInOut',
      });
  }
}
```

### 3-2. `_stopMachineTween()` — 추가 정리
angle과 scale 리셋도 필요:
```javascript
_stopMachineTween(slot) {
  // 기존: vibTween, glowPulseTween 정지/파괴
  // 추가: angle, scale 복원
  if (slot.machineIcon && slot.machineIcon.active) {
    slot.machineIcon.setAlpha(0.5);
    slot.machineIcon.setX(slot.x);
    slot.machineIcon.setAngle(0);        // Phase 3: 회전 복원
    slot.machineIcon.setScale(slot.machineIcon._origScaleX || slot.machineIcon.scaleX,
                               slot.machineIcon._origScaleY || slot.machineIcon.scaleY); // Phase 3: 스케일 복원
  }
}
```

### 3-3. 호출부 변경
`_placeMachineVisual()` 내 `_startMachineTween(slot, machineIcon)` 호출을
`_startMachineTween(slot, machineIcon, machineId)` 로 변경.

`_updateMachineWaitingVisual()` 내 `_startMachineTween(slot, slot.machineIcon)` 호출도
`_startMachineTween(slot, slot.machineIcon, slot.machineId)` 로 변경.
(slot에 machineId 저장 필요)

