##### 3. _tickMachines() — crossResourcesMap 7번째 파라미터 추가

교차 레시피(zone3:darkMatter, zone4:spaceStation)를 처리하기 위해 7번째 파라미터를 추가한다.
resourceId가 `zoned+:resId` 패턴이면 crossResourcesMap에서 차감한다.

```js
/**
 * @param {Array} machines
 * @param {object} resources - 현재 구역 자원 풀
 * @param {object} machineMap
 * @param {number} deltaSeconds
 * @param {boolean} updateVisuals
 * @param {string} zoneId
 * @param {object|null} crossResourcesMap - { zone3: zone3Resources, zone4: zone4Resources } 형태
 */
_tickMachines(machines, resources, machineMap, deltaSeconds, updateVisuals, zoneId, crossResourcesMap = null) {
  // ... 기존 로직 (생략) ...
  for (const machine of machines) {
    // ... 기존 speed 계산 동일 ...
    if (machineDef.inputs !== null) {
      // 가공 머신: progress 누적
      while (machine.progress >= 1.0) {
        let canProduce = true;
        for (const inp of machineDef.inputs) {
          // 교차 레시피 파싱
          const crossMatch = inp.resourceId.match(/^(zoned+):(.+)$/);
          if (crossMatch) {
            const [, crossZone, crossResId] = crossMatch;
            const crossPool = crossResourcesMap && crossResourcesMap[crossZone];
            if (!crossPool || (crossPool[crossResId] || 0) < inp.amount) {
              canProduce = false; break;
            }
          } else {
            if ((resources[inp.resourceId] || 0) < inp.amount) {
              canProduce = false; break;
            }
          }
        }
        if (canProduce) {
          for (const inp of machineDef.inputs) {
            const crossMatch = inp.resourceId.match(/^(zoned+):(.+)$/);
            if (crossMatch) {
              const [, crossZone, crossResId] = crossMatch;
              crossResourcesMap[crossZone][crossResId] -= inp.amount;
            } else {
              resources[inp.resourceId] -= inp.amount;
            }
          }
          resources[machineDef.output] += 1;
          machine.progress -= 1.0;
          machine.totalProduced += 1;
          machine.isWaiting = false;
        } else {
          machine.isWaiting = true;
          machine.progress = 1.0;
          break;
        }
      }
    }
  }
}
```

**기존 zone1~zone3 _tickMachines 호출에 crossResourcesMap 미전달** (null 기본값 사용, 변경 없음):

