##### 7. _calcOfflineEarnings() — zone4/zone5 tier1 머신 반영

교차 레시피 머신(tier2/tier3)은 오프라인 중 소재 파악 불가이므로 tier1만 반영한다:

```js
// zone3 블록 직후:
const z4Unlocked2 = (this._state.bpUpgrades && this._state.bpUpgrades.zone4Unlock >= 1);
const z4LogisticsBonus = this._getLogisticsBonus("zone4");
if (z4Unlocked2 && this._state.zone4Machines) {
  for (const machine of this._state.zone4Machines) {
    const machineDef = MACHINES4[machine.machineId];
    if (!machineDef || machineDef.tier !== 1) continue; // tier1만 반영
    const baseSpeed = machineDef.baseSpeed + (machine.level - 1) * LEVELUP_SPEED_BONUS;
    let speed = baseSpeed * (1 + prodSpeedLv * 0.05);
    if (z4LogisticsBonus > 0) speed *= (1 + z4LogisticsBonus);
    const resDef = RESOURCES4[machineDef.output];
    if (!resDef) continue;
    totalCredits += speed * resDef.sellPrice * (1 + salesBonus) * cappedSec * efficiency;
    offlineResources[machineDef.output] = (offlineResources[machineDef.output] || 0) + Math.floor(speed * cappedSec * efficiency);
  }
}
const z5Unlocked2 = (this._state.bpUpgrades && this._state.bpUpgrades.zone5Unlock >= 1);
const z5LogisticsBonus = this._getLogisticsBonus("zone5");
if (z5Unlocked2 && this._state.zone5Machines) {
