if(upgradeId==="zone5Unlock"&&(this._state.prestigeCount||0)<4){
  this._showFeedback(t("bp.zone5.locked")); return;
}
if(upgradeId==="zone4Unlock") this.time.delayedCall(200,()=>{this._showStoryPopup("zone4");});
if(upgradeId==="zone5Unlock") this.time.delayedCall(200,()=>{this._showStoryPopup("zone5");});
```

