##### 12. _checkEndingCondition() + _showEndingPopup() — 신규 메서드

gaiaSeed 최초 생산 후 seenEnding 플래그로 1회만 표시. 게임 진행 유지.

```js
/** gaiaSeed 최초 생산 확인. update() 루프에서 zone5 틱 직후 호출. */
_checkEndingCondition() {
  if(this._state.seenEnding) return;
  if(!this._state.zone5Resources) return;
  const sold=(this._state.stats&&this._state.stats.zone5ResourcesSold&&this._state.stats.zone5ResourcesSold.gaiaSeed)||0;
  const held=this._state.zone5Resources.gaiaSeed||0;
  if(sold>0||held>0) this._showEndingPopup();
}

/** NEON_EMERALD 글로우 배경, 타이핑 효과, 누적 통계 3줄. 닫기 후 게임 진행. */
_showEndingPopup() {
  if(this._popup) this._closePopup();
  this._state.seenEnding=true;
  const cx=GAME_WIDTH/2, cy=GAME_HEIGHT/2;
  const popupW=300, popupH=420;
  const emerald=COLORS.NEON_EMERALD, emeraldCSS="#00FF88";
  // 배경 오버레이 (어두운 녹색계)
  this._overlay=this.add.rectangle(cx,cy,GAME_WIDTH,GAME_HEIGHT,0x001a0d,0.92).setInteractive().setDepth(90);
  // 글로우 사각형 (주기적 트윗)
  const glow=this.add.rectangle(cx,cy,GAME_WIDTH,GAME_HEIGHT,emerald,0.06).setDepth(91);
  this.tweens.add({targets:glow,alpha:0.12,yoyo:true,repeat:-1,duration:1500});
  this._popup=this.add.container(cx,cy).setDepth(92);
  const bg=this.add.graphics();
  this._drawGlassPanel(bg,-popupW/2,-popupH/2,popupW,popupH,{radius:12,fillAlpha:0.97,strokeColor:emerald,strokeAlpha:1,strokeWidth:3});
  this._popup.add(bg);
  // 제목
  const tit=this.add.text(0,-popupH/2+24,t("ending.title"),{fontSize:"16px",fontFamily:"monospace",color:emeraldCSS,fontStyle:"bold"}).setOrigin(0.5);
  this._popup.add(tit);
  // 타이핑 효과
  const fullText=t("ending.message");
  const typTxt=this.add.text(0,-popupH/2+70,"",{fontSize:"10px",fontFamily:"monospace",color:"#CCFFEE",wordWrap:{width:popupW-32},align:"center"}).setOrigin(0.5);
  this._popup.add(typTxt);
  let ci=0;
  const timer=this.time.addEvent({delay:40,repeat:fullText.length-1,callback:()=>{ci++;typTxt.setText(fullText.substring(0,ci));}});
  // 누적 통계
  const pc=this._state.prestigeCount||0;
  const tc=Math.floor(this._state.stats.totalCreditsEarned||0);
  const lp=Math.floor(this._state.stats.lifetimeTotalProduced||0);
  const st=[t("ending.stat.prestige",pc),t("ending.stat.credits",tc.toLocaleString()),t("ending.stat.produced",lp.toLocaleString())].join("
");
  const stTxt=this.add.text(0,popupH/2-150,st,{fontSize:"10px",fontFamily:"monospace",color:emeraldCSS,align:"center"}).setOrigin(0.5);
  this._popup.add(stTxt);
  // 닫기 버튼
  const btn=this.add.rectangle(0,popupH/2-30,200,36,emerald,0.85).setInteractive({useHandCursor:true});
  const bTxt=this.add.text(0,popupH/2-30,t("ending.close"),{fontSize:"13px",fontFamily:"monospace",color:"#001a0d",fontStyle:"bold"}).setOrigin(0.5);
  this._popup.add(btn); this._popup.add(bTxt);
  btn.on("pointerdown",()=>{
    if(timer) timer.remove();
    this._autoSave();
    this._closePopup();
    if(glow&&glow.scene) glow.destroy();
  });
}
```

