- nameKey: string — i18n 이름 키
- descKey: string — i18n 설명 키 (파라미터 치환용)
- targetValue: number — 달성 목표치
- rewardType: 'credits' | 'blueprints' — 보상 통화 유형
- rewardAmount: number — 보상 수량
- statKey: string — 추적할 진행 통계 키 (dailyStats 내 필드명)

**미션 풀 (8종)**

| # | id | 이름(ko) | 조건 | 목표치 | 보상 |
|---|---|---|---|---|---|
| 1 | sellResources100 | 자원 판매 100 | 오늘 판매한 자원 총량 ≥ 100 | 100 | 500 CR |
| 2 | sellResources500 | 자원 판매 500 | 오늘 판매한 자원 총량 ≥ 500 | 500 | 2,000 CR |
| 3 | placeMachines2 | 머신 배치 2 | 오늘 배치한 머신 수 ≥ 2 | 2 | 300 CR |
| 4 | placeMachines5 | 머신 배치 5 | 오늘 배치한 머신 수 ≥ 5 | 5 | 1,000 CR |
| 5 | tapMine200 | 탭 채굴 200 | 오늘 탭 채굴 자원량 ≥ 200 | 200 | 500 CR |
| 6 | tapMine1000 | 탭 채굴 1000 | 오늘 탭 채굴 자원량 ≥ 1,000 | 1000 | 1 BP |
| 7 | earnCredits5000 | 크레딧 획득 5K | 오늘 획득한 크레딧 ≥ 5,000 | 5000 | 1 BP |
| 8 | doPrestige | 프레스티지 수행 | 오늘 프레스티지 ≥ 1 | 1 | 3 BP |

**내보낼 항목**

```js
export const MISSION_POOL = [ /* 8개 MissionDef 객체 */ ];

/**
 * UTC 날짜 문자열(YYYY-MM-DD)을 시드로 사용해 미션 풀에서 3개를 선정한다.
 * 같은 날짜에는 항상 동일한 3개가 선정된다.
 * @param {string} dateStr - UTC 날짜 문자열 ('2026-03-15')
 * @returns {MissionDef[]} 선정된 3개 미션 정의
 */
export function selectDailyMissions(dateStr) {
  // 날짜 문자열을 해시하여 시드 생성
  let hash = 0;
  for (let i = 0; i < dateStr.length; i++) {
    hash = ((hash << 5) - hash) + dateStr.charCodeAt(i);
    hash |= 0;
  }
  // Fisher-Yates 셔플 (시드 기반 의사 랜덤)
  const indices = MISSION_POOL.map((_, i) => i);
  for (let i = indices.length - 1; i > 0; i--) {
    hash = (hash * 1103515245 + 12345) & 0x7fffffff;
    const j = hash % (i + 1);
    [indices[i], indices[j]] = [indices[j], indices[i]];
  }
  return [MISSION_POOL[indices[0]], MISSION_POOL[indices[1]], MISSION_POOL[indices[2]]];
}
```

