##### 3. _checkDailyReset() 확장

기존 boostUsedToday 리셋 직후에 일일 미션 리셋 로직 추가:

```js
_checkDailyReset() {
  const now = new Date();
  const todayMidnight = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  if ((this._state.lastDailyReset || 0) < todayMidnight) {
    this._state.boostUsedToday = 0;
    this._state.lastDailyReset = todayMidnight;

    // 일일 미션 리셋
    this._resetDailyMissions();
  }
}
```

##### 4. _resetDailyMissions() (신규)

```js
/**
 * 일일 미션을 리셋한다. UTC 날짜 기반으로 미션 풀에서 3개를 선정.
 * @private
 */
_resetDailyMissions() {
  const now = new Date();
  const dateStr = now.toISOString().slice(0, 10); // 'YYYY-MM-DD'

  // 같은 날짜면 리셋하지 않음
  if (this._state.dailyMissionsDate === dateStr) return;

  const selected = selectDailyMissions(dateStr);
  this._state.dailyMissions = selected.map(m => m.id);
  this._state.dailyMissionsDate = dateStr;
  this._state.dailyMissionsClaimed = [false, false, false];

  // 일일 통계 리셋
  this._state.dailyStats = {
    resourcesSold: 0,
    machinesPlaced: 0,
    tapProduced: 0,
    creditsEarned: 0,
    prestigeCount: 0,
  };

  this._autoSave();
}
```

