  // 히트 영역
  const hitArea = this.add.rectangle(btnX + 16, btnY + 16, 32, 32)
    .setOrigin(0.5).setDepth(3).setInteractive({ useHandCursor: true });
  hitArea.on('pointerdown', () => this._openMissionPopup());

