##### 6. _updateMissionBadge() (신규)

```js
/**
 * 미션 배지의 미완료 수를 갱신한다.
 * @private
 */
_updateMissionBadge() {
  if (!this._missionBadge) return;
  const unclaimed = this._getUnclaimedMissionCount();
  if (unclaimed > 0) {
    this._missionBadge.setText(String(unclaimed));
    this._missionBadge.setVisible(true);
  } else {
    this._missionBadge.setVisible(false);
  }
}

/**
 * 수령 가능한(달성했지만 미수령) 미션 수를 반환한다.
 * @returns {number}
 * @private
 */
_getUnclaimedMissionCount() {
  const missions = this._state.dailyMissions || [];
  const claimed = this._state.dailyMissionsClaimed || [];
  const stats = this._state.dailyStats || {};
  let count = 0;
  for (let i = 0; i < missions.length; i++) {
    if (claimed[i]) continue; // 이미 수령
    const def = MISSION_POOL.find(m => m.id === missions[i]);
    if (!def) continue;
    if (this._getMissionProgress(def, stats) >= def.targetValue) {
      count++;
    }
  }
  return count;
}
```

##### 7. _getMissionProgress() (신규)

```js
/**
 * 미션의 현재 진행도를 반환한다.
 * @param {object} def - 미션 정의
 * @param {object} stats - dailyStats 객체
 * @returns {number} 현재 진행값
 * @private
 */
_getMissionProgress(def, stats) {
  return stats[def.statKey] || 0;
}
```

##### 8. _openMissionPopup() (신규)

기존 popup 패턴(overlay + container)을 따른다.

```js
/**
 * 일일 미션 팝업을 연다.
 * @private
 */
_openMissionPopup() {
  if (this._popup) return;

  // 미션 초기화 확인
  this._checkDailyReset();
  if (!this._state.dailyMissions || this._state.dailyMissions.length === 0) {
    this._resetDailyMissions();
  }

  const cx = GAME_WIDTH / 2;
  const cy = GAME_HEIGHT / 2;
  const popupW = 320;
  const popupH = 340;

  // 오버레이
  this._overlay = this.add.rectangle(cx, cy, GAME_WIDTH, GAME_HEIGHT, 0x000000, 0.7)
    .setDepth(10).setInteractive();

  // 팝업 컨테이너
  this._popup = this.add.container(0, 0).setDepth(11);

  // 배경
  const bg = this.add.graphics();
  bg.fillStyle(COLORS.PANEL, 0.95);
  bg.fillRoundedRect(cx - popupW/2, cy - popupH/2, popupW, popupH, 10);
  bg.lineStyle(2, COLORS.NEON_CYAN, 0.8);
  bg.strokeRoundedRect(cx - popupW/2, cy - popupH/2, popupW, popupH, 10);
  this._popup.add(bg);

  // 타이틀
  const title = this.add.text(cx, cy - popupH/2 + 24, t('mission.title'), {
    fontSize: '14px', fontFamily: 'monospace', fontStyle: 'bold',
    color: UI_COLORS.neonCyan,
  }).setOrigin(0.5);
  this._popup.add(title);

  // 미션 카드 3개
  const missions = this._state.dailyMissions;
  const claimed = this._state.dailyMissionsClaimed;
  const stats = this._state.dailyStats || {};

  for (let i = 0; i < missions.length; i++) {
    const def = MISSION_POOL.find(m => m.id === missions[i]);
    if (!def) continue;

    const cardY = cy - popupH/2 + 60 + i * 80;
    const cardW = popupW - 32;
    const cardH = 70;
    const cardX = cx - cardW/2;

    // 카드 배경
    const cardBg = this.add.graphics();
    const isClaimed = claimed[i];
    const progress = this._getMissionProgress(def, stats);
    const isComplete = progress >= def.targetValue;

    cardBg.fillStyle(isClaimed ? 0x1A3A1A : COLORS.PANEL_BORDER, 0.9);
    cardBg.fillRoundedRect(cardX, cardY, cardW, cardH, 6);
    if (isComplete && !isClaimed) {
      cardBg.lineStyle(1, COLORS.NEON_GREEN, 0.8);
      cardBg.strokeRoundedRect(cardX, cardY, cardW, cardH, 6);
    }
    this._popup.add(cardBg);

    // 미션 이름
    const nameText = this.add.text(cardX + 8, cardY + 8,
      t(def.nameKey), {
        fontSize: '11px', fontFamily: 'monospace', fontStyle: 'bold',
        color: isClaimed ? '#39FF14' : UI_COLORS.textPrimary,
      });
    this._popup.add(nameText);

    // 미션 설명 + 진행도
    const progressStr = `${Math.min(progress, def.targetValue)}/${def.targetValue}`;
    const descText = this.add.text(cardX + 8, cardY + 24,
      t(def.descKey, def.targetValue) + '  ' + progressStr, {
        fontSize: '9px', fontFamily: 'monospace',
        color: UI_COLORS.textSecondary,
      });
    this._popup.add(descText);

    // 보상 표시
    const rewardLabel = def.rewardType === 'blueprints' ? 'BP' : 'CR';
    const rewardColor = def.rewardType === 'blueprints' ? UI_COLORS.neonMagenta : UI_COLORS.neonYellow;
    const rewardText = this.add.text(cardX + 8, cardY + 42,
      t('mission.reward') + ': ' + this._formatNumber(def.rewardAmount) + ' ' + rewardLabel, {
        fontSize: '9px', fontFamily: 'monospace',
        color: rewardColor,
      });
    this._popup.add(rewardText);

    // 수령 버튼 (달성 + 미수령 시)
    if (isComplete && !isClaimed) {
      const btnW = 60;
      const btnH = 22;
      const btnX = cardX + cardW - btnW - 8;
      const btnY2 = cardY + cardH - btnH - 8;

      const btnBg2 = this.add.graphics();
      btnBg2.fillStyle(COLORS.NEON_GREEN, 1);
      btnBg2.fillRoundedRect(btnX, btnY2, btnW, btnH, 4);
      this._popup.add(btnBg2);

      const btnText = this.add.text(btnX + btnW/2, btnY2 + btnH/2,
        t('mission.claim'), {
          fontSize: '10px', fontFamily: 'monospace', fontStyle: 'bold',
          color: '#000000',
        }).setOrigin(0.5);
      this._popup.add(btnText);

      const btnHit = this.add.rectangle(btnX + btnW/2, btnY2 + btnH/2, btnW, btnH)
        .setOrigin(0.5).setDepth(11).setInteractive({ useHandCursor: true });
      btnHit.on('pointerdown', () => this._claimMission(i));
      this._popup.add(btnHit);
    } else if (isClaimed) {
      // 수령 완료 텍스트
      const doneText = this.add.text(cardX + cardW - 16, cardY + cardH - 20,
        '✅', { fontSize: '14px' }).setOrigin(0.5);
      this._popup.add(doneText);
    }
  }

  // 닫기 버튼
  const closeY = cy + popupH/2 - 32;
  const closeBg = this.add.graphics();
  closeBg.fillStyle(COLORS.PANEL_BORDER, 1);
  closeBg.fillRoundedRect(cx - 40, closeY, 80, 24, 4);
  this._popup.add(closeBg);

  const closeText = this.add.text(cx, closeY + 12, t('mission.close'), {
    fontSize: '10px', fontFamily: 'monospace',
    color: UI_COLORS.textPrimary,
  }).setOrigin(0.5);
  this._popup.add(closeText);

  const closeHit = this.add.rectangle(cx, closeY + 12, 80, 24)
    .setOrigin(0.5).setDepth(11).setInteractive({ useHandCursor: true });
  closeHit.on('pointerdown', () => this._closePopup());
  this._popup.add(closeHit);
}
```

##### 9. _claimMission(index) (신규)

```js
/**
 * 미션 보상을 수령한다.
 * @param {number} index - 미션 인덱스 (0-2)
 * @private
 */
_claimMission(index) {
  const missionId = this._state.dailyMissions[index];
  const def = MISSION_POOL.find(m => m.id === missionId);
  if (!def) return;

  // 보상 지급
  if (def.rewardType === 'credits') {
    this._state.credits += def.rewardAmount;
    this._state.stats.totalCreditsEarned += def.rewardAmount;
  } else if (def.rewardType === 'blueprints') {
    this._state.blueprints += def.rewardAmount;
  }

  // 수령 상태 갱신
  this._state.dailyMissionsClaimed[index] = true;

  // 피드백
  const rewardLabel = def.rewardType === 'blueprints' ? 'BP' : 'CR';
  this._showFeedback(t('mission.claimed') + ' +' + def.rewardAmount + ' ' + rewardLabel);

  // 업적 체크
  this._checkAndGrantAchievements();

  this._autoSave();

  // 팝업 새로고침
  this._closePopup();
  this._openMissionPopup();
}
```

