#### 2. _getActive*() 헬퍼 메서드 확장 (10개)

기존 zone1/zone2 이분법을 zone3까지 확장. 패턴:

```js
_getActiveResources() {
  if (this._activeZone === 'zone3') return this._state.zone3Resources;
  if (this._activeZone === 'zone2') return this._state.zone2Resources;
  return this._state.resources;
}
_getActiveMachines() {
  if (this._activeZone === 'zone3') return this._state.zone3Machines;
  if (this._activeZone === 'zone2') return this._state.zone2Machines;
  return this._state.machines;
}
_setActiveMachines(m) {
  if (this._activeZone === 'zone3') this._state.zone3Machines = m;
  else if (this._activeZone === 'zone2') this._state.zone2Machines = m;
  else this._state.machines = m;
}
_getActiveUnlockedFloors() {
  if (this._activeZone === 'zone3') return this._state.zone3UnlockedFloors;
  if (this._activeZone === 'zone2') return this._state.zone2UnlockedFloors;
  return this._state.unlockedFloors;
}
_getActiveFloorDefs() {
  if (this._activeZone === 'zone3') return ZONE3_FLOORS;
  if (this._activeZone === 'zone2') return ZONE2_FLOORS;
  return FLOORS;
}
_getActiveMachineMap() {
  if (this._activeZone === 'zone3') return MACHINES3;
  if (this._activeZone === 'zone2') return MACHINES2;
  return MACHINES;
}
_getActiveMachineOrder() {
  if (this._activeZone === 'zone3') return MACHINE3_ORDER;
  if (this._activeZone === 'zone2') return MACHINE2_ORDER;
  return MACHINE_ORDER;
}
_getActiveResourceMap() {
  if (this._activeZone === 'zone3') return RESOURCES3;
  if (this._activeZone === 'zone2') return RESOURCES2;
  return RESOURCES;
}
_getActiveResourceOrder() {
  if (this._activeZone === 'zone3') return RESOURCE3_ORDER;
  if (this._activeZone === 'zone2') return RESOURCE2_ORDER;
  return RESOURCE_ORDER;
}
_getActiveResourcesSold() {
  if (this._activeZone === 'zone3') return this._state.stats.zone3ResourcesSold;
  if (this._activeZone === 'zone2') return this._state.stats.zone2ResourcesSold;
  return this._state.stats.totalResourcesSold;
}
```

