#### 8. _tickAutoSell() 수정

비활성 구역 자동 판매에 zone3 추가:

```js
// zone3 비활성 자동 판매
const z3Unlocked = (this._state.bpUpgrades && this._state.bpUpgrades.zone3Unlock >= 1);
if (z3Unlocked && this._activeZone !== 'zone3') {
  for (const resId of RESOURCE3_ORDER) {
    const amount = Math.floor(this._state.zone3Resources[resId] || 0);
    if (amount > 0) {
      this._state.zone3Resources[resId] -= amount;
      this._state.stats.zone3ResourcesSold[resId] = (this._state.stats.zone3ResourcesSold[resId] || 0) + amount;
      totalSold += amount;
      const resDef = RESOURCES3[resId];
      if (resDef) rev += amount * resDef.sellPrice * (1 + salesBonus);
    }
  }
}
```

