### neon-factory/js/data/research.js (신규)

@fileoverview: 연구 시스템 데이터. 18개 연구 노드의 ID, 비용(RP), 선행 조건, 효과를 정의한다.
트리 구조: 기초 3 -> 생산 5 + 판매 4 + 오프라인 3 + 매니저 3

```js
/**
 * @fileoverview 연구 시스템 데이터. 18개 연구 노드의 ID, 비용(RP), 선행 조건, 효과를 정의한다.
 * 트리 구조: 기초 3 -> 생산 5 + 판매 4 + 오프라인 3 + 매니저 3
 */

/**
 * 연구 효과 누적 계산 함수. 순수 함수 (side effect 없음).
 * @param {string[]} unlocked - 해금된 노드 ID 배열
 * @param {string} effectType - 효과 타입
 *   ('prodSpeed'|'sellPrice'|'offlineEfficiency'|'offlineTime'|'critChance'|'managerEffect')
 * @returns {number} 누적 효과값 (비율 0.0~N, offlineTime은 초 단위)
 */
export function calcResearchBonus(unlocked, effectType) {
  const set = new Set(unlocked);
  let total = 0;
  for (const node of RESEARCH_NODES) {
    if (node.effect.type === effectType && set.has(node.id)) {
      total += node.effect.value;
    }
  }
  return total;
}

