#### 7. _createResearchPanel() 신규

```js
/**
 * 연구 패널 Container를 생성한다. 초기에는 숨김 상태이다.
 * 18개 노드를 스크롤 가능한 목록으로 표시. 선행 조건 미달 시 잠금 표시.
 * @private
 */
_createResearchPanel() {
  const panelX = 0, panelY = HUD_HEIGHT, panelW = GAME_WIDTH, panelH = TAB_BAR_Y - HUD_HEIGHT;
  this._researchPanel = this.add.container(0, 0).setDepth(2).setVisible(false);

  // 패널 배경 (글래스모피즘)
  const bg = this.add.graphics();
  this._drawGlassPanel(bg, panelX, panelY, panelW, panelH, {
    radius: 0, fillColor: COLORS.BG_DARK, fillAlpha: 0.95, strokeWidth: 0,
  });
  this._researchPanel.add(bg);

  // 헤더
  this._researchPanel.add(this.add.text(GAME_WIDTH / 2, panelY + 16, t('research.title'), {
    fontSize: '12px', fontFamily: 'monospace', color: '#AAFFAA',
  }).setOrigin(0.5));

  // RP 보유량 (패널 내)
  this._researchRpText = this.add.text(GAME_WIDTH / 2, panelY + 30, '', {
    fontSize: '10px', fontFamily: 'monospace', color: '#AAFFAA',
  }).setOrigin(0.5);
  this._researchPanel.add(this._researchRpText);

  // 노드 카드 목록 (cardH=72px, margin=6px)
  const cardW = 320, cardH = 72, cardMargin = 6;
  const cardX = (GAME_WIDTH - cardW) / 2;
  let cardY = panelY + 46;
  for (const node of RESEARCH_NODES) {
    this._createResearchNodeCard(node, cardX, cardY, cardW, cardH);
    cardY += cardH + cardMargin;
  }
}
```

#### 8. _createResearchNodeCard() 신규

```js
/**
 * 연구 노드 카드 1개를 생성하여 연구 패널에 추가한다.
 * @param {object} node - RESEARCH_NODES 항목
 * @param {number} x - 좌상단 X
 * @param {number} y - 좌상단 Y
 * @param {number} w - 카드 너비
 * @param {number} h - 카드 높이
 * @private
 */
_createResearchNodeCard(node, x, y, w, h) {
  const unlocked  = (this._state.researchUnlocked || []).includes(node.id);
  const prereqMet = node.prerequisites.every(p => (this._state.researchUnlocked || []).includes(p));
  const rpCost    = this._getNodeRpCost(node);
  const canAfford = (this._state.researchPoints || 0) >= rpCost;
  const locked    = !prereqMet;

  // 카드 배경 (상태별 테두리 색상)
  const strokeColor = unlocked ? COLORS.NEON_GREEN
    : locked ? COLORS.PANEL_BORDER : COLORS.NEON_CYAN;
  const cardBg = this.add.graphics();
  this._drawGlassPanel(cardBg, x, y, w, h, { radius: 6, strokeColor, strokeAlpha: unlocked ? 0.8 : 0.3 });
  this._researchPanel.add(cardBg);

  // 이름 텍스트
  this._researchPanel.add(this.add.text(x + 10, y + 10, t(node.nameKey), {
    fontSize: '12px', fontFamily: 'monospace',
    color: unlocked ? '#AAFFAA' : locked ? '#888888' : '#FFFFFF',
  }));

  // 효과 설명
  this._researchPanel.add(this.add.text(x + 10, y + 28, t(node.descKey), {
    fontSize: '10px', fontFamily: 'monospace', color: '#888888',
  }));

  if (unlocked) {
    // 완료 표시
    this._researchPanel.add(this.add.text(x + w - 10, y + h / 2, t('research.completed'), {
      fontSize: '10px', fontFamily: 'monospace', color: '#AAFFAA',
    }).setOrigin(1, 0.5));
  } else if (!locked) {
    // 구매 버튼
    const btn = this.add.text(x + w - 10, y + h / 2, t('research.buyBtn', [rpCost]), {
      fontSize: '10px', fontFamily: 'monospace',
      color: canAfford ? '#AAFFAA' : '#888888',
      backgroundColor: canAfford ? '#1A3A1A' : '#1A1A2E',
      padding: { x: 6, y: 3 },
    }).setOrigin(1, 0.5);
    if (canAfford) {
      btn.setInteractive({ useHandCursor: true });
      btn.on('pointerdown', () => this._doUnlockResearch(node.id));
    }
    this._researchPanel.add(btn);
  } else {
    // 잠금 표시
    this._researchPanel.add(this.add.text(x + w - 10, y + h / 2, t('research.locked'), {
      fontSize: '10px', fontFamily: 'monospace', color: '#555555',
    }).setOrigin(1, 0.5));
  }
}
```

#### 9. _doUnlockResearch() 신규

```js
/**
 * 연구 노드를 구매하여 해금한다. RP 차감, researchUnlocked 추가, 패널 갱신.
 * @param {string} nodeId - 해금할 노드 ID
 * @private
 */
_doUnlockResearch(nodeId) {
  const node = RESEARCH_NODE_MAP[nodeId];
  if (!node) return;

  // 선행 조건 재확인
  if (!node.prerequisites.every(p => (this._state.researchUnlocked || []).includes(p))) return;

  const rpCost = this._getNodeRpCost(node);
  if ((this._state.researchPoints || 0) < rpCost) {
    this._showFeedback(t('research.noRp'));
    return;
  }

  // RP 차감 및 해금
  this._state.researchPoints -= rpCost;
  if (!this._state.researchUnlocked) this._state.researchUnlocked = [];
  this._state.researchUnlocked.push(nodeId);

  // 패널 재빌드 (destroy & rebuild 패턴)
  if (this._researchPanel) this._researchPanel.destroy();
  this._researchPanel = null;
  this._createResearchPanel();
  this._researchPanel.setVisible(true);
  this._isResearchTabActive = true;

  this._showFeedback(t('research.unlocked', [t(node.nameKey)]));
  SaveManager.save(this._state);
}
```

#### 10. _getNodeRpCost() 신규

```js
/**
 * 연구 매니저 할인을 반영한 노드 RP 비용을 반환한다.
 * @param {object} node - RESEARCH_NODES 항목
 * @returns {number} 실제 RP 비용 (최소 1)
 * @private
 */
_getNodeRpCost(node) {
  return Math.max(1, Math.floor(node.rpCost * (1 - this._getResearchManagerDiscount())));
}
```

#### 11. _getResearchManagerDiscount() 신규

```js
/**
 * 연구 매니저 합산 RP 할인율을 반환한다. 상한 90%.
 * @returns {number} 할인율 (0.0 ~ 0.9)
 * @private
 */
_getResearchManagerDiscount() {
  if (!this._state.managers) return 0;
  let discount = 0;
  for (const mgr of this._state.managers) {
    if (mgr.type === 'research') {
      const grade = MANAGER_GRADES[mgr.grade];
      discount += MANAGER_DEFS.research.baseValue * (grade ? grade.multiplier : 1);
    }
  }
  return Math.min(0.9, discount);
}
```

